quests[26333] = { id = 26333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Panzer!", description = "Wir haben bereits einige Späher bei dem Versuch verloren, herauszufinden, was Razlo Ritzelstoß mit all den Mechanopanzern vorhat, die seine bestrahlten Techniker reparieren.\n\nWir dürfen nicht noch mehr Zeit verlieren. Wir müssen handeln, bevor Ritzelstoß seine Anhänger und seine Waffen auf uns hetzt.\n\nIn dieser Techno-Granate befindet sich genügend Sprengkraft, um die Mechanopanzer zu zerstören. Dann wird Ritzelstoß sie nicht mehr verwenden können. Nehmt sie mit nach Norden, auf die Straße, die zu Ritzelstoß' Arsenal führt, und vernichtet diese Panzer!", sourceObjective = "Benutzt die Techno-Granate, um 5 reparierte Mechanopanzer in Ritzelstoß' Arsenal zu vernichten.", completion = "Mekkadrill wird zufrieden sein, wenn er erfährt, dass Ihr Ritzelstoß davon abgehalten habt, seine Anhänger mit unseren alten Waffen auszurüsten. Wenn er die Mechanopanzer nicht einsetzen kann, wird er schwach und angreifbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26334] = { id = 26334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutfürst Mandokir", description = "{race}. {race}, {race}, {race}... Ihr dachtet nicht, ich wäre Euch freundlich gesinnt, oder, {race}? Ah, ha, hahahaa!\n\nIhr habt Euren Zweck erfüllt. Ich bin ins Reich der Lebenden zurückgekommen und das nur dank Euch. Anstatt Euch zu töten werde ich Euch also ein Angebot machen.\n\nGebt mir den Raptor.\n\nIhr solltet bereits gemerkt haben, dass sie kein normaler Schmetterschwanz ist und ich brauche einen Ersatz für Ohgan. Tut, was ich sage, oder Ihr und Euer Hexendoktor werdet meine Wut zu spüren bekommen.", sourceObjective = "Bringt das Eierfragment eines Schmetterschwanz' zu Blutfürst Mandokir im Basislager Grom'gol.", progress = "Ich will nicht mehr als den Raptor, {name}. Gebt sie mir und Ihr und der Troll könnt weiterleben.", completion = "Gut, dass Ihr zu Sinnen kommt.\n\nVielleicht wollt Ihr mich ja mal in Zul'Gurub besuchen, {race}. Ich werde Euch im Auge behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26335] = { id = 26335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht die Marine startklar", description = "Höllschrei erwartet eine Armada von Schiffen für seinen Einmarsch, aber die Arbeiten hier hinken dem Zeitplan um Wochen hinterher. Die Kosten sind himmelhoch und die Qualität erbärmlich. Das Problem hier ist Korruption, {name}! Und ich brauche Euch, um dieses Übel auszumerzen.\n\nDie Feindbrecher, ein Kriegsschiff, das am nordwestlichen Pier liegt, sollte schon vor Tagen ausgestattet werden. Da ist etwas faul. Geht dorthin und überwacht den Bau selbst.\n\nFindet heraus, wer unsere Schiffsvorbereitungen unterbricht und setzt dem ein Ende!", sourceObjective = "Untersucht den Rumpf der Feindbrecher.", completion = "<Dies sind die Blaupausen für die Feindbrecher mit allen noch so kleinen Details.>\n\n<Ihr dreht und wendet die Dokumente und versucht, die Notizen, Bemerkungen und Korrekturen zu entziffern.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26336] = { id = 26336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wank O'Breen", description = "Ihr seid in Ordnung, {name}. Man trifft nur selten sogenannte Helden, die so weit entfernt von der Heimat tatsächlich wissen, was sie tun. Ich würde Euch gern etwas mehr Arbeit überlassen. \n\nIch habe einen Freund namens Wank O'Breen. Er kommandiert eine Piratenbesatzung, die Schwarzmeerräuber; das sind gute Jungs, respektabel für Piraten. Sie haben in Faldirs Bucht angelegt, die versteckt am Südstrand liegt.\n\nO'Breen wird Euch sicherlich einige lukrative Angebote machen können, wenn Ihr interessiert seid.", sourceObjective = "Findet Wank O'Breen in Faldirs Bucht im Arathihochland.", completion = "Ahoi, {class}. Jeder Freund von Skuerto ist auch mein Freund.\n\nHier gibt es eine Menge zu tun. Wir sitzen nicht in dieser Bucht und drehen Däumchen, weil wir das wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26337] = { id = 26337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagfertige Überredungskunst", description = "<Es ist offensichtlich, warum die Feindbrecher im Zeitplan hinterherhinkt. Alle zwei Tage nimmt ein Großknecht Änderungen an den Blaupausen vor.>\n\n<Am beunruhigendsten sind die letzten Änderungen. Den Arbeitern wurde befohlen, Nieten zu entfernen, um Kosten zu sparen!>\n\n<Ihr solltet einen der Bilgewässer Großknechte finden, die dafür verantwortlich sind und ein Exempel statuieren. Ansonsten kommen noch Mitglieder der Horde wegen der fehlerhaften Schiffe ums Leben!>", sourceObjective = "Sucht einen Bilgewässer Großknecht im Bilgewasserhafen und mischt ihn ein wenig auf.", completion = "Also haben sie versucht, bei den Produktionskosten zu schummeln? Völlig inakzeptabel!\n\nIch bin froh, dass Ihr ihnen ein wenig Verstand eingeprügelt habt. Wenn dieser Großknecht sein Wort hält, ist unsere Flotte rechtzeitig für unsere Invasion seetauglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[26338] = { id = 26338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bevölkerungskon-Trolle", description = "Ich habe gehört, dass Ihr bald nach Zul'Kunda aufbrechen werdet. Ich habe eine kleine Aufgabe für Euch, wenn Ihr dort seid.\n\nDie Bevölkerung der Trolle ist zu groß für Schlingendorntal geworden. Die Blutskalpe im Westen, die Schädelspalter im Osten... sie kommen aus den Ruinen und machen sich im Dschungel breit. Das stört das natürliche Gleichgewicht der Gegend. Dieses Gleichgewicht muss jetzt wiederhergestellt werden.\n\nZul'Kunda ist die Hochburg der Blutskalpe. Dort werdet Ihr die hochrangigsten Blutskalpe finden. Reduziert ihre Zahlen und kehrt zu mir zurück.", sourceObjective = "Tötet 7 Mystiker der Blutskalpe, 7 Jäger der Blutskalpe, 7 Späher der Blutskalpe und 1 Bestienmeister der Blutskalpe.", completion = "Das Gleichgewicht ist erst einmal wiederhergestellt. Wir werden uns vielleicht zu einem späteren Zeitpunkt wieder an Euch wenden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26339] = { id = 26339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitungen in Bräuhall", description = "Während Hochtüftler Mekkadrill, seine militärischen Berater und ich die Pläne für den Angriff auf Razlo Ritzelstoß durchgehen, ist mein Assistent schon einmal nach Bräuhall gereist, um mit den Vorbereitungen zu beginnen.\n\nFolgt der Straße nach Südosten aus der Stadt hinaus, um nach Bräuhall zu gelangen. Findet Jarvi Schattenschritt nach Eurer Ankunft und findet heraus, ob er Hilfe benötigt. Unsere Zwergencousins haben einen Trupp Gebirgsjäger aus Eisenschmiede abgestellt, um uns im Kampf gegen Ritzelstoß zu unterstützen.", sourceObjective = "Sprecht mit Jarvi Schattenschritt in Bräuhall.", completion = "Ach ja, Kelsey sagte mir, Ihr würdet bald eintreffen. Es gibt viel zu erledigen, bevor wir uns Ritzelstoß stellen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26340] = { id = 26340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd", description = "Von allen Plätzen in Azeroth stecke ich ausgerechnet hier in Grom'gol fest. Es ist ein Wunder, dass ich noch am Leben bin, mit den gefährlichen Wildtieren, den Überfällen auf Karawanen und der dauernden Bedrohung durch Angriffe der Trolle.\n\nEs könnte schlimmer sein. Hier in Grom'gol gibt es wenigstens Mauern und Wächter. Eine Gruppe Jäger hat nördlich von hier mitten im Dschungel ihr Lager errichtet!\n\nIch sehe die ganze Zeit, wie Leute dort hingehen. Wenn Ihr nach Ärger sucht, solltet Ihr in diese Richtung aufbrechen. Ich bleibe in Grom'gol.", sourceObjective = "Meldet Euch bei Barnil Steinkrug bei Nesingwarys Expedition im Nördlichen Schlingendorntal.", completion = "Hmm? Ich heiße Barnil. Und wer seid Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[26341] = { id = 26341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Steinsplitter", description = "Ich habe das ganze Hochland bereist, {name}, und dabei etwas gefunden, für das ich keine Erklärung habe.\n\nNordöstlich von hier gibt es einen Steinkreis, ähnlich denen, die man überall in Arathi findet... nur deutlich größer und beeindruckender. Er wurde in den Berg hineingebaut.\n\nUnter uns: Ich hörte Stimmen, als ich dort war. Das Flüstern der Erde. Solltet Ihr neugierig geworden sein, könnt Ihr Euch das selbst ansehen...", sourceObjective = "Untersucht die Splitter von Myzrael.", completion = "<Die Splitter pulsieren sanft; ein Flüstern windet sich langsam durch Euren Kopf.>\n\nHilfe...", sourceObjectiveStatus = "unverified-source-field" }
quests[26342] = { id = 26342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzmalerei", description = "Uns liegen verlässliche Informationen vor, laut derer Razlo Ritzelstoß eine Verteidigungsstellung auf der Insel in der Mitte des gefrorenen Eiswellensees errichtet hat. Hinzu kommt, dass er sich mit zahlreichen Späh-o-Bots umgibt, die mögliche Angreifer entdecken sollen.\n\nWir können uns Ritzelstoß erst stellen, wenn diese Späher zerstört worden sind. Dieses Gerät schießt eine dunkle, klebrige Farbe ab. Sie wird die optischen Sensoren von Ritzelstoß' Späh-o-Bots verdecken. Schaltet sein Frühwarnsystem damit aus.", sourceObjective = "Benutzt den Farbinator, um 5 von Ritzelstoß' Späh-o-Bots die Sicht zu nehmen.", completion = "Ihr habt es uns gerade ermöglicht, Ritzelstoß zu überrumpeln. Hervorragende Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26343] = { id = 26343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angebot und Nachfrage", description = "Der beste Ledermacher der Südlichen Meere und der Alten wie der Neuen Welt. So nennen sie mich. Mich! Drizzlik! Der beste Le... ähem. Nun ja.\n\nMeine Lederwaren sind nah und fern als absolut vorzüglich bekannt, erste Wahl der wahren Kenner!\n\nGerade habe ich eine Bestellung von Direktor Quizvox vom Tüftlerverband über ein Dutzend seiner Lieblingsstiefel aus der Exzelsiorlinie erhalten. Unsere Verkaufsschlager, ehrlich gesagt.\n\nFür die Grundform benötige ich Krokiliskenhäute von den Krokis entlang des Flusses im Nördlichen Schlingendorntal.", sourceObjective = "Bringt 2 große Flusskrokiliskenhäute zu Drizzlik bei Nesingwarys Expedition.", progress = "Meine Ausrüstung ist startklar, {name}, ich warte nur noch auf die Häute. Wir wollen Quizvox ja nicht warten lassen.\n\nEs ist für niemanden gut, wenn der Cheferfinder des Tüftlerverbands unzufrieden ist.", completion = "Diese Häute sollen genügen. Ihre Qualität ist nicht allzu wichtig, da sie ja nur die innere Schicht der Stiefel bilden, aber sie sollten schon bequem sein.\n\nWenn sie ein bisschen zu steif sind, verwende ich ein wenig Tigerblut, um sie aufzuweichen. Kleines Betriebsgeheimnis, wisst Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[26344] = { id = 26344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Zusammenbau benötigt", description = "Nun, ich habe die Grundform der Stiefel so weit und sie werden auch sehr gut, aber die Häute, die Ihr mir brachtet, werden leider nicht für die inneren Schichten ausreichen.\n\n\"Was sollen wir tun, Drizzlik?\" Diese Frage brennt Euch zweifelsohne auf den Lippen, und Ihr habt wirklich Glück, dass Ihr mit Drizzlik sprecht, denn er wird Euch genauestens erklären, was wir zu tun gedenken!\n\nDie inneren Schichten sieht sowieso nie jemand, also werden wir uns zum Ausfüllen der Stiefel einige der billigeren, dickeren Häute der Krokis holen, die um den Nazferitisee leben.", sourceObjective = "Bringt 5 Schnappkieferkrokiliskenhäute zu Drizzlik bei Nesingwarys Expedition.", progress = "Drizzliks Exzelsiorlederstiefel, feinste Handwerksarbeit, Stiefel aus 100 Prozent Salzwasserkrokiliskenhaut von höchster Qualität. Es gibt nichts Besseres!\n\nSo eine tolle Beschreibung sucht ihresgleichen, was?\n\nOder habt Ihr vielleicht schon diese Häute für mich?", completion = "Meine Stiefel... sie sind 'n bisschen wie Würstchen, {name}. Sehen gut aus und schmecken auch so. Ich sag Euch, dass sie mit dem allerbesten Fleisch und feinsten Zutaten gefüllt sind und Ihr esst sie und Ihr liebt sie.\n\nEs ist sicherer - und schmackhafter -, wenn Ihr mir einfach nur traut und nicht allzu viele Fragen stellt, was wirklich drin ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26345] = { id = 26345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exzelsior", description = "Die Innenseiten sind fertig gestellt, jetzt fehlt nur noch die äußere Schicht. Dafür verwende ich nur die besten Häute der alten Krokilisken. Sie sind widerstandsfähiger und eine bessere Leinwand - wenn Ihr es so nennen wollt - für die Muster und Akzente, die Drizzliks Exzelsiorlinie ausmachen.\n\nEs ist allerdings äußerst schwierig, diese vollkommene Haut zu finden; die Einzige, die meinen Plänen gerecht wird, ist die eines alten Salzwasserkrokilisken. Ihr findet sie im Süden, in der der Nähe der Grenze am Kap.", sourceObjective = "Bringt die Haut eines alten Krokilisken zu Drizzlik bei Nesingwarys Expedition.", progress = "Irgendwo habe ich gelesen, dass die älteren Krokilisken langsam aussterben... schlecht für mein Geschäft, was?\n\nEgal, ich hoffe, Ihr habt die Haut eines alten Salzwasserkrokilisken für mich!", completion = "Großartig! Dank Eurer Hilfe habe ich diese Bestellung fertig und kann sie mit dem nächsten Schiff zu Direktor Quizvox nach Lorenhall abschicken. Sogar noch vor der Frist!\n\nFür all Eure harte Arbeit, hier, ich habe einige zusätzlich gemacht, nehmt Euch ein Paar. Geht auf Drizzliks Rechnung.\n\nUnd denkt dran, nirgends gibt es Stiefel, die so fein, wie Stiefel von Drizzliks Exzelsiorlinie ganz allein!", sourceObjectiveStatus = "unverified-source-field" }
quests[26346] = { id = 26346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzraels Geschichte", description = "Als der Stein verstummt, hallt ein ungutes Gefühl in Euch nach. Etwas stimmt nicht.\n\nVielleicht solltet Ihr Skuerto erzählen, was Ihr bis jetzt getan habt.", sourceObjective = "Kehrt zu Skuerto in der Zuflucht im Arathihochland zurück.", completion = "Ihr müsst nicht mehr sagen, {name}. Ich habe mich mit einem... \"alten Freund\" unterhalten, während Ihr unterwegs wart. Ich hätte Euch nicht zu diesen Splittern schicken sollen.\n\nEs war ein schwerer Fehler von uns beiden, uns damit zu beschäftigen. Zum Glück konnte ich meinen Freund Gerrig davon \"überzeugen\", mir zu erklären, was in diesem Fall zu tun ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26347] = { id = 26347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewahrer der Flamme", description = "Die Nacht, als die Leuchtturmwärterfamilie starb, war schrecklich. Ich musste hilflos zusehen, während Trübauge der Alte den Angriff anführte. Aber die Vergangenheit lässt sich nicht ändern und meine Hauptsorge gilt jetzt den Leben der Seeleute auf dem Großen Meer. Ihre Schiffe kommen den gefährlichen Felsen entlang der Küste oft zu nahe. Da niemand mehr auf das Leuchtfeuer aufpasst, fällt diese Aufgabe jetzt mir zu.\n\nHelft mir, die Flamme am Leben zu erhalten, indem Ihr mir Schluchtenschlamm von den Schleimen im Rasenden Schlund im Nordosten bringt.", sourceObjective = "Bringt 5 Schluchtenschlamme zu Kapitän Grausohn am Leuchtturm von Westfall.", progress = "Das Feuer wird ohne Schlamm nicht sehr lang brennen, {name}. Früher haben wir Öl benutzt, aber das war schwer zu beschaffen!", completion = "Ich muss Euch für Euren Mut loben, {class}. Die Felsen an der Küste Westfalls werden dank Eurer harten Arbeit beleuchtet sein. Solange das Feuer brennt, werden viele Leben verschont bleiben.\n\nMein Tod an diesem Strand war unnötig. Meine Aufgabe im Jenseits ist es, dafür zu sorgen, dass niemand dem gleichen Schicksal erliegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26348] = { id = 26348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger an der Küste", description = "Die vielen Schiffswracks entlang der Küste sind Euch ja vermutlich schon aufgefallen. Das Große Meer ist überaus tückisch. Die Küste von Westfall muss freigehalten werden, damit die Seeleute sicher sind, wenn sie unsere Ufer erreichen. Aber die Murlocs sind ein Problem.\n\nTötet Gezeitenjäger und Orakel, dann sorge ich dafür, dass Ihr belohnt werdet.", sourceObjective = "Tötet 7 Murlocgezeitenjäger und 7 Murlocorakel.", completion = "Gut gemacht, {name}. Ihr habt ein ziemliches Talent für den Kampf. Dank Euch ist die Küste Westfalls jetzt sicherer als zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[26349] = { id = 26349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung an der Küste", description = "Als ich auf den Felsen mein Leben aushauchte, hatte ich keine Ahnung, was das Leben nach dem Tode für mich bereithalten würde. In jener Nacht war der Leuchtturm erloschen, weil Trübauge der Alte die Familie des Leuchtturmwärters vertrieben hatte. Die Familie kehrte zurück und zündete die Flamme wieder an, doch Trübauge brachte die willensschwächeren Murlocs dazu, den Leuchtturm noch einmal mit ihm zusammen anzugreifen. Beim zweiten Mal hatte die Familie nicht so viel Glück. Vor meinen Augen starben sie alle, ohne sich wehren zu können.\n\nTötet Trübauge den Alten, wenn Ihr ihn am Ufer seht, und bringt mir eine seiner Schuppen, dann werdet Ihr eine Belohnung erhalten.", sourceObjective = "Bringt Kapitän Grausohn am Leuchtturm von Westfall eine Schuppe von Trübauge dem Alten.", progress = "Habt Ihr der Bedrohung namens Trübauge schon den Garaus gemacht? Er ist gesehen worden, wie er an der Küste von Westfall umherstreifte.\n\nKehrt zu mir zurück, sobald das garstige Ungeheuer tot ist.", completion = "Also ist Trübauge, dieser garstige Heide, endlich tot. Gut gemacht, {name}. Durch Eure Hand ist ein Leben beendet worden, doch vielleicht wurden gerade durch diese Tat viele weitere Leben gerettet. So gefährlich das Große Meer auch ist, diese Nacht wird es dank Eurer heldenhaften Tat ein wenig sicherer sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26350] = { id = 26350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priesterin Hu'rala", description = "Ich danke Euch, {name}. Ich weiß, Ihr hättet mich nicht retten müssen und... nun, ich bin Euch sehr dankbar.\n\nDie Rückkehr von Blutfürst Mandokir ist eine schreckliche Nachricht. Er wurde vor vielen Jahren in Zul'Gurub getötet und wir dachten, es wäre das Ende von ihm und seinesgleichen. Die Trolle von Zul'Gurub haben versucht, ein abscheuliches, furchtbares Ritual durchzuführen. Wenn Mandokir lebt, so gibt es Grund zur Annahme dass er nicht der Einzige ist.\n\nDie Trolle in Bambala östlich von hier könnten mehr wissen. Sprecht mit der Priesterin.", sourceObjective = "Sprecht mit Priesterin Hu'rala in Bambala im Nördlichen Schlingendorntal.", completion = "Mandokir lebt, ja.\n\nIhr seid dafür verantwortlich, ja.\n\nIhr könnten ihn noch aufhalten können, ja.", sourceObjectiveStatus = "unverified-source-field" }
quests[26351] = { id = 26351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedankensicht", description = "Um Mandokir zu erkennen, müsst Ihr Mandokir sehen.\n\nUm Mandokir zu sehen, müsst Ihr Augen von Raptor nutzen.\n\nIhr habt Euch angefreundet mit Raptor: Ohgan'aka: Tochter von Ohgan.\n\nUm Freundschaft zu stärken, brauchen wir Federn.\n\nGeht nach Westen und Ihr werdet Federn finden, ja.", sourceObjective = "Erhaltet 5 Dschungelpirscherfedern von Dschungelpirschern im Nördlichen Schlingendorntal.", progress = "Raptor namens Ohgan'aka immer noch Eure Freundin.", completion = "Ihr bringt Federn, ja.\n\nIhr könnt Anweisungen folgen, ja.", sourceObjectiveStatus = "unverified-source-field" }
quests[26352] = { id = 26352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cozzles Vorhaben", description = "Ich mag den Dunkelspeeren abstammen, aber ich habe meine Kindheit hier im Schlingendorntal verbracht. Ich habe jedes Fleckchen des Schlingendorntals gesehen; es gibt jedoch nichts schlimmeres als die Zerstörung, die die Venture Company dem Flussbett zugefügt hat.\n\nUnd es wird noch schlimmer, weil Großknecht Cozzle und seine Arbeiter ihre Aktivität gesteigert haben. Ich fürchte, sie haben etwas Neues vor. Schließt die Aufgabe ab, an der ich gescheitert bin, {name}: tötet Cozzle, nehmt seinen Schlüssel und stehlt die Blaupausen aus seinem Heim.", sourceObjective = "Nehmt Cozzles Schlüssel dem Großknecht Cozzle ab und erhaltet die Treibstoffreglerblaupausen.", progress = "Was die Venture Company dem Schlingendorntal angetan hat kann nicht verziehen werden.", completion = "Ein Treibstoffregler? Das scheint wichtig zu sein. Zumindest hoffe ich das.\n\nWir werden die Unternehmungen der Venture Company nicht beendet haben, aber wenigstens haben wir sie verlangsamt. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26353] = { id = 26353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Sanders' versteckter Schatz", description = "Wenn Ihr das hier lesen tut, dann heißt das, dass der alte Käpt'n Sanders in den Fluten begraben is'. Also tut mein Schatz jetz' Euch gehör'n, Ihr braucht bloß den Hinweisen folgen. \n\nErst müsst Ihr ma' meine Schließkiste finden. Wahrscheinlich is' die jetz' da an der Westküste von Westfall in der Nähe von dem Schiffswrack schon halb im Sand verschwunden. 's gibt da an der Küste massig Schiffswracks, aber bloß einen rostigen Anker. Wenn Ihr den Anker finden tut, dann habt Ihr auch meine Schließkiste gefunden. Da müsst ihr reingucken, denn da steht der nächste Hinweis drin.", sourceObjective = "Findet Käpt'n Sanders' Schließkiste und sucht darin nach dem nächsten Hinweis.", completion = "Der Schließkasten knarrt als Ihr ihn langsam öffnet. Sand und Wasser scheinen der einzige Inhalt zu sein. Aber halt! Eine kleine Krabbe huscht mit einem Hinweis auf den Schatz in den Scheren davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[26354] = { id = 26354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Sanders' versteckter Schatz", description = "Der Hinweis auf den Schatz lautet folgendermaßen: Gut gemacht, Kumpel! Jetz' müsst Ihr Euch imma nach Osten halten. Im Osten die Steilhänge hoch, dann weiter nach Osten bis zur Straße. Schaut Euch nach so 'nem ollen verfallenen Kamin nahe bei der Straße um. Dort findet Ihr 'n altes Fass mit Eurem nächsten Hinweis drin.", sourceObjective = "Findet das alte Fass in der Nähe des verfallenen Kamins und durchsucht es nach Eurem nächsten Hinweis.", progress = "Das sieht wie das richtige Fass aus.", completion = "Gut gemacht! Das war der nächste Schritt auf der Schatzsuche.", sourceObjectiveStatus = "unverified-source-field" }
quests[26355] = { id = 26355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Sanders' versteckter Schatz", description = "Als Ihr das Fass durchsucht, findet Ihr ein weiteres Stück Pergament. Darauf steht: Also, von dem Fass dort müsst Ihr Euch nach Norden halten tun. Un' dann geht Ihr immer der Nase nach schnurstracks geradeaus, bis Ihr den leeren Henkelkrug sehen tut, der da irgendwo bei so 'ner einzeln stehenden Windmühle oben auf dem Steilhang über dem Meer liegt. Wenn Ihr Euch den Henkelkrug mal genau anguckt, dann findet Ihr vielleicht sogar, was Ihr sucht.", sourceObjective = "Durchsucht den leeren Henkelkrug neben der Windmühle nach dem nächsten Hinweis.", progress = "Es steckt ein Hinweiszettel in dem leeren Henkelkrug.", completion = "Ihr seid bei Eurer Schatzsuche auf dem richtigen Weg!", sourceObjectiveStatus = "unverified-source-field" }
quests[26356] = { id = 26356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Sanders' versteckter Schatz", description = "Und tatsächlich, ganz unten, fast am Boden des alten Henkelkruges findet sich der nächste Hinweis auf Sanders' Schatz. An manchen Stellen ist die Tinte verwischt und das Papier riecht nach Whisky, aber zum Teil kann man den Text noch lesen: Jetz', wo Ihr mein'n alten Whiskykrug gefunden habt, habt Ihr den Schatz schon so gut wie in der Tasche. Von der Flasche aus müsst Ihr Euch einfach nach Westen halten und runter zum Strand geh'n. Und dann heißt es schwimmen! Schwimmt schnurstracks nach Westen, bis Ihr an der Insel seid, da wo meine Schatztruhe drauf is'!", sourceObjective = "Findet Käpt'n Sanders' Truhe und öffnet sie. Darin befindet sich Eure Belohnung.", progress = "Der verlorene Schatz von Käpt'n Sanders wartet!", completion = "Die Scharniere der alten Truhe sind rostig, aber sie funktionieren noch. Ihr brecht die Truhe auf und nehmt die Beute heraus.\n\nHerzlichen Glückwunsch!", sourceObjectiveStatus = "unverified-source-field" }
quests[26357] = { id = 26357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichter des Bösen", description = "Die Blutfratzen haben ihre Tikimasken überall in Jintha'Alor an die Mauern gehangen. Die Geister werden nicht mehr lange über sie wachen.\n\nNehmt die Fackel und kämpft Euch durch die Blutfratzen, {class}. Zündet ihre Tikimasken an. Ich werd zusehen, wie ihre Abwehr- und Schutzzauber vergehen und ihr ketzerischer dunkler Voodoo in Rauch aufgeht.", sourceObjective = "Zündet mit der Tikifackel 8 Tikimasken in Jintha'Alor an.", completion = "Was für'n schöner Anblick. Die Hoffnungen des Feindes verbrennen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26358] = { id = 26358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht die Luftwaffe startklar", description = "Ich habe Höllschrei persönlich garantiert, dass seine Luftflotte diese Woche fertig wird, aber unser Flaggschiff, die Speer von Durotar, hat immer noch keine Haupttriebwerke.\n\nFliep hat mir letzte Woche ein niegelnagelneues Triebwerk versprochen. Geht zu ihrem Schrottplatz hinter der Bank und findet den Grund für die Verzögerung heraus.\n\nDie Luftflotte erwartet uns, {name}!", sourceObjective = "Sucht nach Fliep auf ihrem Schrottplatz im Bilgewasserhafen in Azshara.", completion = "<Fliep wischt sich das Gesicht ab und verschmiert sich dabei gehörig die Wange mit Schmieröl.>\n\nWas? Der Kapitän hat WAS gesagt?\n\n<Sie schwingt bedrohlich ihre Rohrzange.>\n\nEs ist SEINE Schuld, dass dieses Monstrum von Triebwerk verspätet ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[26359] = { id = 26359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seht Raptor", description = "Wir haben Federn, ja.\n\nWir haben <den/die:c> {class}, ja.\n\nSprecht mit Priesterin, wenn bereit.", sourceObjective = "Sprecht mit Priesterin Hu'rala in Bambala, um am Ritual der Gedankensicht teilzunehmen.", completion = "Was hat Priesterin Euch gesagt?\n\nRaptor ist Tochter von Ohgan, Erbe von Mandokir.\n\nHah!", sourceObjectiveStatus = "unverified-source-field" }
quests[26360] = { id = 26360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedankenkontrolle", description = "Gedankensicht nicht genug, nein.\n\nGedankenkontrolle viel mächtigere Magie, ja.\n\nMächtige Magie braucht mächtige Reagenzien und Trollhirn ist mächtiges Reagenz.\n\nBraddok in Zul'Mamwe sehr intelligent, ja.\n\nGeht nach Süden und untersucht Braddoks großes Gehirn.", sourceObjective = "Erhaltet Braddoks Riesengehirn von Braddok in Zul'Mamwe.", progress = "Riesenzauber brauchen Riesenhirne, ja.", completion = "Passt auf, nächster Teil schwierig, ja.\n\nScheitern sehr möglich, ja.\n\nAber {name} und {name}'aka werden wiedervereint... ja, werden sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[26361] = { id = 26361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoots Samophlang", description = "Es war der Kapitän, der darauf bestanden hat, dass die neuen Triebwerke ein Induktionssamophlang haben.\n\nSo etwas wurde noch nicht einmal erfunden!\n\nIch habe Smoot damit beauftragt, ein Induktionssamophlang auf Basis von gestohlenen Zeichnungen der Venture Company zu entwerfen. Endlich ist es ihm auch gelungen, ein funktionierendes Modell zu bauen.\n\nDoch jetzt, wo er das Samophlang hat, ist er vor lauter Macht ganz berauscht. Er schleift es in der ganzen Stadt mit sich herum, wie ein Besessener.\n\nVersetzt Smoot eine Tracht Prügel und schnappt Euch mein Samophlang, {name}.", sourceObjective = "Findet Smoot im Bilgewasserhafen. Stellt ihn und besorgt Euch das Induktionssamophlang.", progress = "Smoot ist ein hervorragender Ingenieur.\n\nEin Samophlang kann aus 30 Metern Entfernung töten, wenn die Reduktionskaliphraketen falsch ausgerichtet sind.", completion = "Ausgezeichnet! Ich sollte dieses Triebwerk noch in dieser Stunde samophlanginiert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26362] = { id = 26362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seid Raptor", description = "Gedankenkontrolle sehr mächtig, ja.\n\nMit Glück könnt Ihr Ohgan'aka helfen, aus Zul'Gurub zu fliehen.\n\nDann wird Ohgan'aka wieder {name}'aka werden!\n\nSprecht mit Priesterin, ja, und helft {name}'aka bei Flucht.", sourceObjective = "Sprecht mit Priesterin Hu'rala und helft dem gefangenen Schmetterschwanzjungen bei der Flucht aus Zul'Gurub.", completion = "Sehr schade, ja.\n\nDies ist der Wille der Geister, ja.\n\nWenn Ihr stärker seid, werdet Ihr vielleicht nach Zul'Gurub gehen und deine {name}'aka von Mandokir zurückholen, ja.\n\nDoch erst einmal gibt Euch Priesterin dies.", sourceObjectiveStatus = "unverified-source-field" }
quests[26363] = { id = 26363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksalsgipfel", description = "Ihr wart im Vorgehen gegen ihre Krieger sehr erfolgreich, {name}. Ich möchte, dass Ihr den Gipfel von Jintha'Alor untersucht.\n\nWir waren auf den härtesten Kampf vorbereitet, darauf, ihren dunklen Altar zu stürmen, aber es ist zu leise. Kein Geräusch weit und breit. Es könnte eine furchtbare Falle sein und jemand, der stark genug ist, sollte sich dort umsehen, bevor wir alle gesammelt einlaufen.\n\nWenn es keine Falle sein sollte... würde es mich auf jeden Fall auch interessieren, was dort los ist. Bringt mir jegliche Hinweise, die Ihr finden könnt.", sourceObjective = "Sammelt 8 Spinnengötzen der Blutfratzen auf dem Gipfel von Jintha'Alor.", progress = "Was habt Ihr gefunden?", completion = "Tot? Alle, um den ganzen Alter herum? Und sie hatten diese Spinnengötzen bei sich...\n\nEine Massenopfergabe. Sie haben Sharda ihre Leben geopfert.", sourceObjectiveStatus = "unverified-source-field" }
quests[26364] = { id = 26364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit Ritzelstoß!", description = "Unsere Cousins, die Zwerge von Eisenschmiede, haben sich bereit erklärt, uns im Kampf gegen Razlo Ritzelstoß zu unterstützen. Gebirgsjäger Steinschleifer ist ein Veteran, der Dun Morogh gut kennt. Er und Hochtüftler Mekkadrill halten sich auf einer kleinen, schneebedeckten Insel im Eiswellensee nördlich von hier bereit. Trefft sie dort und sagt dem Hochtüftler Bescheid, wenn Ihr bereit seid, dem Verräter Ritzelstoß entgegenzutreten.\n\nNehmt dieses orbitale Zielgerät und benutzt es während der Schlacht. Es wird die Spezialwaffen des Hochtüftlers zum Ziel führen.", sourceObjective = "Besiegt Razlo Ritzelstoß. Sprecht mit Hochtüftler Mekkadrill auf dem Eiswellensee, wenn Ihr bereit seid, den Kampf zu beginnen.", completion = "Endlich sind wir frei von Razlo Ritzelstoß und seinen Störungen! Nach der Niederlage von Ritzelstoß und seinen Truppen, kann Thermadraht es sich nicht mehr leisten, weitere seiner Anhänger an die Oberfläche zu schicken. Ich kann den Tag, an dem wir ihn endgültig besiegen werden, kaum erwarten!", sourceObjectiveStatus = "unverified-source-field" }
quests[26365] = { id = 26365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Rotkammgebirge!", description = "Die Lage hier ist zwar schlimm, aber in anderen Gegenden bebt es wortwörtlich nach dem großen Aufruhr immer noch.\n\nIch habe hier einen Bericht von Wachhauptmann Parker aus dem Rotkammgebirge, eines unserer Gebiete östlich vom Wald von Elwynn. Er ersucht die Hilfe eines Helden.\n\nSo, wie wir im Moment aufgestellt sind, kann ich keine weiteren Truppen losschicken. Könnt Ihr Parker aufsuchen und sehen, was er braucht? Ihr könnt Wachhauptmann Parker auf dem Turm bei den Drei Ecken finden.", sourceObjective = "Meldet Euch bei Wachhauptmann Parker an der Turmwacht im Rotkammgebirge.", completion = "Ich habe gehört, dass Westfall wirklich in der Klemme steckt.\n\n<Parker sieht Euch nicht einmal an, als er mit Euch spricht.>\n\nNun, wir haben hier selbst Probleme. Seht Ihr die Gnolle dort? Es sieht so aus, als haben sie wieder etwas vor. Das gefällt mir nicht. Das gefällt mir überhaupt nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26366] = { id = 26366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfprämie", description = "Umboda von den Blutfratzen ist einer ihrer stärksten Krieger und ein kranker Schlächter.\n\nEr sammelt und benutzt die Köpfe aller, die vor ihm fallen, als Schmuck, Belohnungen... und sogar Waffen! Es ist an der Zeit, dass er fällt.\n\nFindet Umboda Dreikopf, tötet ihn und bringt mir SEINEN Kopf! Wir werden sehen, wie die Blutfratzen kämpfen, wenn wir seinen Kopf über ihre Mauern werfen!", sourceObjective = "Besiegt Umboda Dreikopf und holt Euch seinen Kopf.", progress = "Zeigt ihn her!", completion = "Der Ausdruck von Angst und Verwirrung in seinem Gesicht... das ist genau das, was er verdient hat! Jetzt müssen wir nur noch sicherstellen, dass alle Blutfratzen so einen Gesichtsausdruck bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26367] = { id = 26367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ongo'longos Rache", description = "Ongo'longo war einer von uns. Außenseiter mögen ihn einen Terrortroll nennen, aber er war ein Bruchhauer und ein stolzer Krieger, so wie wir auch!\n\nDann haben die Blutfratzen ihn gefangen genommen. Sie halten ihn gefesselt in einer Grube oben in Jintha'Alor und zwingen ihn, zu ihrer kranken Unterhaltung zu tanzen.\n\nKeine Ketten können Ongo'longo halten. Ihr müsst nur sein Temperament aufwecken. Bekämpft ihn, bis er sich genug ärgert, um sich an sein wahres Ich zu erinnern und die Fesseln sprengt... und dann geht ihm schnell aus dem Weg!", sourceObjective = "Bekämpft Ongo'longo bis er seine Fesseln sprengt.", completion = "Ich wünschte, ich hätte es selbst sehen können, {name}. Ich muss die Geschichte auch von Ongo'longo selbst hören, wenn wir hier fertig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[26368] = { id = 26368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftige Geheimnisse", description = "Von diesem interessanten Gift wird es noch mehr geben, wenn Shadra gerufen wurde.\n\nSeid nicht so überrascht... Die Verlassenen haben diese Länder schon seit längerem untersucht und wir haben die Königin des Gifts hier mindestens einmal gesehen. Ihre Gifte haben sich in der Vergangenheit als recht nützlich herausgestellt.\n\nUnd sie werden sich der Horde erneut als nützlich erweisen. Seid so nett und holt so viel Gift, wie Ihr von der Brut von Shadra erhalten könnt, die in der Höhle auf dem Gipfel sind... Ihr werdet ohnehin voll davon sein, wenn Ihr die Höhle betretet.", sourceObjective = "Erhaltet 6 Giftprobe der Shadrabrut von der Brut von Shadra in Jintha'Alor.", progress = "Habt Ihr das Gift...?", completion = "Mmh, ja... dieser alte, wohlbekannte Geruch.\n\nIhr habt den Verlassenen und der Horde gute Dienste geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26369] = { id = 26369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt die Bewahrerin", description = "Kotonga hat mir von Shadra berichtet. Sie ist die Giftkönigin, die Loa der Spinnen, in der Dunkelheit verehrt. Falls die Blutfratzen vorhaben, Rituale durchzuführen, so werde ich dies zu verhindern wissen.\n\nUntersucht die Höhle hinter dem Altar oben auf Jintha'Alor. Tief in der Höhle könnte sich noch eine Bewahrerin Shadras verstecken. Tötet sie und nehmt alles, was sie bei sich hat, damit wir herausfinden können, was dort vor sich geht.", sourceObjective = "Tötet Morta'gya die Bewahrerin und erhaltet die Tafel von Shadra.", progress = "Durchsucht ihren Leichnam. Ich möchte nicht, dass von den Blutfratzen gelegte Fallen von den Toten verdeckt werden.", completion = "Die Teile sind zersprungen und die Bewahrerinnen wurden getrennt... nun gut.\n\nDas ist das Ritual, um Shadra zu rufen. Sie scheinen es nicht abgeschlossen zu haben. Es sollte zerstört werden...", sourceObjectiveStatus = "unverified-source-field" }
quests[26370] = { id = 26370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Späherkuppe", description = "Die Bruderschaft der Defias sollte man nicht auf die leichte Schulter nehmen, {name}. Was Ihr da gesehen habt, war die Geburtsstunde einer skrupellosen Verbrecherorganisation, die vor nichts Halt machen wird, bevor Sturmwind nicht in Schutt und Asche liegt.\n\nIch möchte, dass Ihr zur Späherkuppe zurückkehrt und Gryan wissen lasst, dass ich ihm Truppen schicke. Ich hoffe, es ist noch nicht zu spät.", sourceObjective = "Erstattet Marschall Gryan Starkmantel an der Späherkuppe in Westfall Bericht.", completion = "Fünf Jahre Arbeit innerhalb von fünf Minuten zu Asche verbrannt. Verfluchte Defias!\n\nUnd das ist erst der Anfang, {name}! Wir haben einen langen, anstrengenden Weg vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[26371] = { id = 26371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende des Kapitän Grausohn", description = "Habt Ihr von Kapitän Grausohn gehört? Einige sagen, er ist die Erfindung eines betrunkenen Seemannsgehirns, aber jeder in Westfall wird Euch sagen, dass Grausohn existiert! Er ist ein Geist, der den Leuchtturm von Westfall ganz im Westen, vor der Endlosen Küste, heimsucht.\n\nWagt Ihr es, das zu untersuchen?", sourceObjective = "Findet Kapitän Grausohn beim Leuchtturm von Westfall in Westfall.", completion = "Ja... Ich war auch einst aus Fleisch und Blut, genau wie Ihr, mein Junge. Bis zu dem schicksalsträchtigen Tag, als die Murlocs den Leuchtturm angriffen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26372] = { id = 26372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzte Tests vor dem Flug", description = "Dieses neue Triebwerk ist extrem schnell. Und gefährlich. Ich würde es \"brisant\" nennen.\n\nGenau so mag der Kapitän es.\n\nRennt schnell den Hügel hinauf und sagt ihm Bescheid, dass ich dieses Schätzchen jetzt einbaue und er sich auf der Baustelle mit mir treffen soll.", sourceObjective = "Sprecht mit Kapitän Krazz im Bilgewasserhafen in Azshara.", completion = "Mein Luftschiff hat Triebwerke? Endlich!\n\nJetzt können wir uns wieder in die Lüfte schwingen!\n\nSobald die Boden- und Seetruppen bereit sind, werden wir den Himmel über dem Schattenhochland in Brand stecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[26373] = { id = 26373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiter nach Kharanos", description = "Einige der Gebirgsjäger unter Steinschleifers Kommando haben mir von den Problemen draußen in Kharanos berichtet. Als die Troggs die Höhle der Frostmähnen eroberten, sind die überlebenden Trolle anscheinend nach Westen, bis ins Herz der Zwergenheimat geflohen.\n\nJetzt bedrohen sie die Zwergenstadt Kharanos. Die Zwerge dort brauchen wohl dringend Hilfe. Warum reist Ihr nicht nach Kharanos und stellt Euch Hauptmann Tharran vor? Folgt der Straße, die nach Osten aus Bräuhall herausführt und folgt ihr, bis Ihr die Stadt seht.", sourceObjective = "Sprecht mit Hauptmann Tharran in Kharanos.", completion = "Wenn der Geheimdienst von Gnomeregan Euch empfiehlt, müsst Ihr einen sehr guten Eindruck gemacht haben. Eure Hilfe können wir hier gut gebrauchen, da wir reich an Feinden, aber arm an Gebirgsjägern sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[26374] = { id = 26374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht die Bodentruppen startklar", description = "Es war keine gute Idee, die Truppen in dieser pulsierenden Goblinmetropole einzuberufen. Jedes Laster, das man mit Gold kaufen kann, ist nur eine Armlänge entfernt. Unsere mächtigen Veteranen sind völlig zügellos und hauen ihren über Jahre mühsam in Nordend verdienten Sold auf den Kopf. Die Stadt droht, zusammenzubrechen!\n\nKönntet Ihr durch die Stadt streifen und die fahnenflüchtigen Nachzügler einsammeln?\n\nMeine Krieger der Axtbeißer sind auf dem Schlachtfeld unschlagbar, aber ich lasse nicht zu, dass sie ihren Uniformen während ihres Landgangs Schande bringen.", sourceObjective = "Durchsucht den Bilgewasserhafen und überzeugt 12 fahnenflüchtige Grunzer, sich zum Dienst zu melden.", completion = "Danke, {name}! Die meisten meiner Soldaten haben sich bereits zum Dienst gemeldet, einige leider etwas lädiert.\n\nBilgewässer Nächte sind lang.\n\nEin frischer Kampf im Schattenhochland sollte ihre Disziplin jedoch wiederherstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26375] = { id = 26375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesselte Steine", description = "Die Schattenhammerkultisten rauben meine Steinlinge. Sie stehlen ihre Energie und foltern sie. Sie nehmen ihnen die Essenz, die dem Stein Leben einhaucht.\n\nBitte, {race}, befreit meine Steinlinge. Weder Diamant noch ich verfügen über das Fingerspitzengefühl, ihre Ketten zu zerschlagen, ohne sie zu verletzen. Aber wir haben ein Werkzeug, das Ihr vielleicht verwenden könnt.\n\nNehmt dies. Sprengt ihre Ketten und befreit sie.", sourceObjective = "Benutzt den filigranen Kettensprenger, um 6 Quarzsteinlinge zu befreien.", progress = "Ich kann es kaum mitansehen. Sie kennen kein Erbarmen. Daher sollten wir ihnen auch keines gönnen.", completion = "Ihr seid sehr großzügig, {race}. Ihr gebt der Erde, die Euch so viel gibt, etwas zurück. Ihr habt meinen Respekt. Mit der Zeit werdet Ihr auch sicher den Respekt der Steinlords erlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26376] = { id = 26376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefsitzender Hass", description = "Ich würde mich ja für Boden entschuldigen, aber Stein ist stur.\n\nOhne den nagenden Zahn der Zeit weicht er nicht von seinen Gewohnheiten ab.\n\nDie Steinlords, darunter Boden und ich, haben die Aufgabe, die Weltensäule zurückzuholen.\n\nDoch wir sind uns uneinig.\n\nIch möchte Euch gerne meine Geduld zuteilwerden lassen, {race}.\n\nBeweist, dass Ihr kein Verbündeter des Schattenhammerkults oder Todesschwinges seid...\n\nTragt unseren Hass zu ihnen.\n\nSchlagt schnell zu, wo wir es nicht können.\n\nHabt Ihr Erfolg, werde ich Euch zuhören.", sourceObjective = "Tötet Dragul Riesenschlächter und 12 Schattenhammerkultisten an Lorthunas Tor.", completion = "Ich habe Euch beobachtet, {race}.\n\nIhr scheut Euch nicht, das Blut des Schattenhammers zu vergießen.\n\nDaher bin ich geneigt, Euch bis zu einem gewissen Grad zu vertrauen.\n\nEs ist ein Anfang.\n\nAlles zu seiner Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26377] = { id = 26377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loser Grund", description = "Der Schattenhammerkult baut in der Nähe seines Lagers Jadekristalle ab.\n\nDumm…\n\nWaghalsig…\n\nSammelt die abgebauten Kristalle. Bringt sie in die Mitte ihres Lagers. Verteilt sie auf dem Boden.\n\nDie Schwingungen und der aufgeladene Kristall werden die Tunnelgräber auf sie hetzen.\n\nSie werden lernen, die Erde zu respektieren...\n\nStück für Stück...\n\nFels für Fels...\n\n... mit der Zeit.", sourceObjective = "Sammelt 6 Jadekristallformationen und kombiniert sie miteinander. Verteilt sie dann im Lager an Lorthunas Tor.", completion = "Die Zeit bringt allen Respekt bei.\n\nDem kleinsten Kiesel.\n\nDem größten Berg.\n\nDem starrsinnigsten Kultisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26378] = { id = 26378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Westfall!", description = "In Westfall herrschen harte Zeiten. Jetzt, da die Bedrohung durch die Defias beseitigt ist, ist das Gebiet zu einer Zuflucht für Obdachlose und Unterdrückte geworden. Die Verbrechensrate in dieser Region ist astronomisch in die Höhe geschossen, da die Leute sich um Unterschlupf und Nahrung zanken. Und jetzt hört man sogar von Mord!\n\nWenn Ihr der Allianz helfen wollt, dann beginnt in Westfall. Meldet Euch bei Leutnant Horatio Laine auf Jansens Hof. Ihr findet Westfall direkt westlich des Waldes von Elwynn.", sourceObjective = "Meldet Euch bei Leutnant Horatio Laine auf Jansens Hof in Westfall.", completion = "Mord, Grünschnabel. Das seht Ihr da auf dem Boden vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[26379] = { id = 26379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Flüchtlinge", description = "Ich hoffe, Ihr seid hier, um zu helfen! Ihr habt keine Ahnung, wovon ich spreche, oder?\n\nIch habe keine Zeit, um Euch alle Details zu erläutern, aber hier in Dunkelküste gab es einen Ort namens Auberdine, der vom Kataklysmus übel zugerichtet wurde. Wir sind dabei, einige der Überlebenden zu retten, aber ich brauche jemanden mit etwas mehr Erfahrung, der nach dem Flüchtlingslager sieht, das sich im Süden befinden soll. Jemanden wie Euch!\n\nÜberlasst uns die Dinge im Norden. Geht direkt nach Süden und helft den Flüchtlingen, wo Ihr nur könnt.", sourceObjective = "Schildwache Lendra in Lor'danel möchte, dass Ihr mit Priesterin Alinya im Flüchtlingslager sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26380] = { id = 26380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für Kharanos", description = "Ich sollte diese Bierfässer zum Gasthaus von Kharanos bringen. In den Fässern befindet sich ein mysteriöses neues Bier, das von einer neuen Brauerei in Bräuhall hergestellt wird. Als ich die Stadt verließ, wurde ich von Trollen der Frostmähnen überfallen. Ich werde Tage brauchen, um den Wagen zu reparieren!\n\nWürdet Ihr mir vielleicht einen Gefallen erweisen? Die großen Fässer lassen sich nicht bewegen, aber ich habe hier ein paar kleine Probefässer. Würdet Ihr die für mich nach Kharanos bringen? Folgt einfach nur der Straße nach Südosten.", sourceObjective = "Bringt die Probefässer zu Gastwirt Belm in der Brauerei Donnerbräu in Kharanos.", progress = "Seid willkommen, Besucher. Habt Ihr dieses Gasthaus betreten, weil Ihr Euch ausruhen wollt oder weil Ihr einen neuen Ruhestein benötigt?", completion = "Die sehen vielversprechend aus. Ich habe viel Gutes über die Brauerei \"Kurz, aber Deftig\" gehört, aber ihr Bier konnte ich bisher nicht probieren.\n\nEntspannt Euch ein wenig, solange Ihr hier seid. Wenn Ihr einen Ersatzruhestein braucht oder Kharanos zu Eurer Heimat machen wollt, sprecht mich an. Ich helfe Euch gern.", sourceObjectiveStatus = "unverified-source-field" }
quests[26381] = { id = 26381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Shadra", description = "Shadra muss gerufen werden, das ist sicher. Uns diese Gelegenheit entgehen zu lassen, wäre schlicht und ergreifend dumm. Die Apotheker finden sicher Verwendung für das Gift der Göttin, aber von Ritualmagie haben sie nicht viel Ahnung.\n\nGlücklicherweise bin ich mit der Vorbereitung dunkler Beschwörungen recht vertraut. Bringt mir die verstreuten Teile Shadras und ich werde sie auf diese Ebene beschwören.\n\nZuerst brauchen wir das Auge von Shadra. Es wird in Agol'watha bewacht.", sourceObjective = "Holt das Auge von Shadra aus Agol'watha.", progress = "Wenn es sich bei den Tafeln um eine Täuschung handelt, werde ich nicht erfreut sein. Habt Ihr das Auge gefunden?", completion = "Ich bin zufrieden, {name}. Das war schneller, als ich erwartet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[26382] = { id = 26382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiertanz", description = "Marnal liegt mir schon seit Tagen mit seinem Shadravorhaben in den Ohren. Ich bereue schon fast, die Tafel wirklich gefunden zu haben – zu dem Zeitpunkt hätte er meiner Meinung nach schon den Mund halten können.\n\nUnd trotz seiner Erfahrung mit Ritualmagie braucht er meine Hilfe genauso sehr wie ich seine. Ich muss ein Basismedium mit ähnlichen...\n\n...wisst Ihr was, ich werde Euch die Einzelheiten ersparen. Bringt mir die Eier der Shadrabrut aus Agol'watha. Ihr solltet dort viele finden – sie werden von den Trollen der Blutfratzen bewacht.", sourceObjective = "Sammelt 5 Eier der Shadrabrut aus Agol'watha.", progress = "Ich hoffe, Ihr habt genügend.", completion = "Gut, gut. Legt sie da drüben hin, ich habe beide Hände voll.", sourceObjectiveStatus = "unverified-source-field" }
quests[26383] = { id = 26383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unaufhaltsame Veränderungen", description = "Ihr da! Ihr seht fähig aus. Und vielleicht sogar hilfsbereit?\n\nAuberdine ist letztendlich gefallen. Zwar haben viele Einwohner bereits vor langem die Stadt verlassen, als der Kataklysmus uns heimsuchte, doch einige der hartnäckigeren Bewohner wurden noch nicht gefunden. Und jetzt scheint die Stadt auch noch von Elementaren überrannt zu werden.\n\nMeine Schwestern brauchen Hilfe bei der Rettung der Überlebenden. Bitte, {class}, benutzt den westlichen Teleportbaum, um nach Rut'theran zu gelangen, sprecht mit Vesprystus und sichert einen Flug nach Lor'danel. Beeilt Euch!", sourceObjective = "Benutzt den Teleportbaum im westlichen Teil von Darnassus und reist nach Rut'theran. Sprecht dort mit Vesprystus, um einen Flug nach Lor'danel zu sichern.", completion = "Haben die Schildwachen Euch geschickt? Elune sei Dank. Wir brauchen jede Hilfe, die wir bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26384] = { id = 26384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der dunkle Kleriker Marnal", description = "Wir können die Tafel noch nicht einfach wegschmeißen, {name}. Wir können sie benutzen...\n\nWisst Ihr, mir geht es in erster Linie um das Gift der Spinnen. Es ist eindeutig magisch und wahrscheinlich gibt es eine Verbindung zur Spinnengöttin, mit der die Trolle etwas zu tun haben. Und wenn man die Tafel zur Beschwörung nutzen kann...\n\nNa ja, ich glaube, Ihr wisst, worauf ich hinaus will. Die Horde kann sich diese Gelegenheit nicht entgehen lassen. Bringt die Tafel zu den Verlassenen. Sie sind westlich von hier in der Forschungsstation in den Ruinen von Hiri'watha.", sourceObjective = "Bringt die Tafel von Shadra zum dunklen Kleriker Marnal.\n\nBereitgestellter Gegenstand:", completion = "Ah, was haben wir den hier...\n\nFaszinierend. Wirklich faszinierend.", sourceObjectiveStatus = "unverified-source-field" }
quests[26385] = { id = 26385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unaufhaltsame Veränderungen", description = "Sieht aus, als hättet Ihr Euren ersten Auftrag. Ihr müsst zurück nach Rut'theran reisen, wo wir zuerst ankamen, und mit Vesprystus sprechen, um einen Transport nach Lor'danel zu bekommen.\n\nSeid Ihr erst einmal in Lor'danel angekommen, müsst Ihr den Nachtelfen dort auf jede nur erdenkliche Weise helfen, die Euch möglich ist. Ich vertraue darauf, dass Ihr sie mit dem Respekt behandelt, den sie verdienen, nach Allem was sie für uns getan haben.\n\nIch selbst muss in die ferne Stadt Sturmwind reisen und mich mit König Varian treffen. Ich hoffe, Euer Gesicht bald wieder zu sehen, {name}. Bis dahin ein herzliches Lebewohl.", sourceObjective = "Sprecht mit Vesprystus in Rut'theran, um nach Lor'danel zu fliegen.", completion = "Unsere Verbündeten eilen zu unserer Hilfe? Elune sei Dank! Es war weise von Tyrande, Eurem Volk mit offenen Armen zu begegnen.\n\nWir brauchen Hilfe. Wir brauchen jede helfende Hand, die wir bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26386] = { id = 26386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surkhan", description = "Priesterin spricht nicht gut Orcisch, nein.\n\nVielleicht sprecht Ihr mir Surkhan, er ist oben.\n\nSagt ihm, was Ihr in Zul'Gurub gesehen habt, ja.", sourceObjective = "Meldet Euch bei Surkhan in Bambala im Nördlichen Schlingendorntal.", completion = "<Ihr erklärt Surkhan, was sich bisher ereignet hat.>\n\nEs scheint, dass Jin'do überlebt hat und dass er seine Brüder versammelt, um Hakkar erneut in diese Welt beschwören zu können. Es war eine weise Entscheidung, mit mir zu sprechen.\n\nLeider können wir im Moment nicht sehr viel mehr machen als warten und beobachten. Jin'do ist schwach und die Zeit wäre für einen Angriff gut, aber ich muss auf die Reaktion aus Rastakhan warten, bevor ich Befehle erteilen kann. Bis dahin müsst Ihr und Euer Raptor warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26387] = { id = 26387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungerdiät", description = "Die Spinnen, die die Gruselruinen östlich von hier heimsuchen, sind nutzlos. Wir nennen sie zwar Shadrabrut und sie sind auch ganz offensichtlich mit der Spinnengöttin verwandt, aber das ändert auch nichts an der Tatsache, dass sie mehr Ärger machen als Nutzen bringen. Mir wäre es lieber, wenn wir die kleinen Plagegeister einfach ausmerzen könnten.\n\nFalls Ihr Euch zu den Gruselruinen aufmachen solltet, tötet alle Kokons, die Ihr finden könnt. Sie ernähren sich tagelang von den Leichen - die Nahrung der Biester zu zerstören wird effektiver sein, als der Versuch, sie alle zu zerquetschen.", sourceObjective = "Vernichtet 6 eingesponnene Opfer in den Gruselruinen.", completion = "Nun, das ist eine weitaus bessere Situation, von der wir alle etwas haben. Die Spinnen werden entweder verhungern oder sich Zwerge oder Elfen schnappen, um sich zu ernähren. An mir und meinen Kollegen ist ja nichts dran, was ein nahrhaftes Mahl darstellen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[26388] = { id = 26388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichthimmel", description = "In Ordnung, Ihr seid also bereit. Wartet hier, bis Kapitän Krazz den Zeppelin gewendet hat und begleitet dann die Luftflotte. Admiral Steinfaust erwartet Euch beim Hafen des Drachenmals!", sourceObjective = "Begleitet die Luftflotte der Horde ins Schattenhochland. Nehmt den Zeppelin vom Turm an der Südlichen Endhaltestelle der Raketenbahn in Azshara.", completion = "Das ist eine Katastrophe, {name}!\n\nUnsere Luftflotte wurde dezimiert. Und wir erhalten Berichte, dass unsere Schiffe grundlos auf offenem Meer von der Allianz angegriffen wurden.\n\nUnd was ist mit Höllschrei? Ist der Kriegshäuptling tot?", sourceObjectiveStatus = "unverified-source-field" }
quests[26389] = { id = 26389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzfelsinvasion", description = "Die Orcs haben begonnen, den Wald niederzubrennen, {name}! Sie haben den Weinberg im Osten übernommen und planen ihren Entscheidungsangriff auf uns! Sie müssen aufgehalten werden!\n\nGeht nach Osten, überquert den Fluss und tötet die wildgewordenen Orcs des Schwarzfelsklans. Sammelt als Beweis ihres Ablebens ihre Waffen ein und kehrt zu mir zurück.\n\nIhr seid unsere einzige Hoffnung, {name}!", sourceObjective = "Bringt 8 Waffen der Orcs des Schwarzfelsklans an Euch.", progress = "Habt Ihr die wildgewordenen Orchorden getötet?", completion = "Die Orcs des Schwarzfelsklans werden jetzt, da ihre Hauptstreitkraft geschlagen wurde, sicherlich fallen. Nun bleibt nur noch eine Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26390] = { id = 26390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt der Invasion ein Ende!", description = "Die wütende Orchorde wird von einem Ungeheuer angeführt, das als Kurtok der Schlächter bekannt ist. Kurtok ist für den vor Kurzem erfolgten Einmarsch verantwortlich und muss getötet werden, wenn wir Frieden im Tal haben wollen.\n\nGeht vorsichtig nach Osten zurück, überquert den Fluss und begebt Euch durch den Weinberg. Haltet Ausschau nach der Passage, die in die Berge führt. Dort wird Kurtok sich aufhalten und einen weiteren Angriff vorbereiten. Tötet ihn und kehrt zurück zu mir.", sourceObjective = "Tötet Kurtok den Schlächter.", progress = "Habt Ihr Kurtok gefunden?", completion = "Jetzt, da Kurtok tot ist, sind wir wieder vor den Orchorden sicher. Ich werde Arbeiter zum Pass entsenden und versuchen, die Passage zu verschließen, damit dort keine Orcs mehr hindurch und auf unser Gebiet gelangen können.\n\nIhr habt den Dank von Sturmwind und der Allianz, Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[26391] = { id = 26391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hoffnung ersticken", description = "Tage wie diese lassen mich die Zeiten zurücksehnen, in denen die Defias noch da waren. Der Kataklysmus hat einen Weg aus der Brennenden Steppe geöffnet, und jetzt überlaufen Schwarzfelsorcs das Nordhaintal! Sie haben mein Weingut übernommen und brennen es nieder! SIE BRENNEN ES NIEDER!\n\nBitte, {name}, dieses Weingut ist alles, was ich habe. Nehmt meinen Feuerlöscher und löscht die Flammen im Weingut. Vielleicht besteht noch Hoffnung für dieses Land!", sourceObjective = "Benutzt Millys Feuerlöscher, um 8 Brände im Weingut zu löschen.", progress = "Habt Ihr die Feuer gelöscht?", completion = "Seid gesegnet, {name}. Ihr seid ein wahrer Held der Allianz! Auch wenn dieses Land völlig verbrannt und nichts als Schutt und Asche vom Weingut übrig ist, kann es sich vielleicht erholen. Stimmt's? Wie schlimm kann es schon sein?", sourceObjectiveStatus = "unverified-source-field" }
quests[26393] = { id = 26393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine eilige Nachricht", description = "Wir bekommen zwar nicht viel Unterstützung von Sturmwind direkt, aber ich habe einen Kontaktmann in der Stadt, der uns mit Rüstungen versorgt. Sein Name ist Osric Strang. Sein Geschäft, Begrenzte Immunität, liegt in der Altstadt von Sturmwind.\n\nUnser Vorrat an Rüstung schwindet, ich muss bei Osric mehr bestellen. Könnt Ihr ihm diese Notiz bringen?\n\nDer schnellste Weg nach Sturmwind führt über Bartlett den Tapferen, unseren Greifenmeister. Er ist direkt bei der Schmiede; bringt ihm meine Notiz und nehmt dann einen Greifen nach Sturmwind.", sourceObjective = "Bringt Argus' Notiz zu Bartlett dem Tapferen, dem Greifenmeister.", progress = "Ihr seht aus, als hättet Ihr es eilig. Tja, dann seid Ihr hier genau richtig!", completion = "Ihr müsst diese Notiz nach Sturmwind bringen? Das ist kein Problem, Ihr könnt einen meiner Greifen nehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26394] = { id = 26394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiter nach Sturmwind", description = "Gegen eine geringe Gebühr könnt Ihr einen Greifen nach Sturmwind nehmen und so Argus' Notiz zu Osric bringen. Einen schnelleren Weg gibt es nicht.\n\nWenn Euch das akzeptabel erscheint, sprecht mich wieder an, sobald Ihr bereit seid für den Flug. Das kostet eine Kleinigkeit, aber glaubt mir, es lohnt sich!", sourceObjective = "Bucht einen Greifenritt bei Greifenmeister Bartlett dem Tapferen, dann bringt Argus' Notiz zu Osric Strang, im Laden Begrenzte Immunität, in der Altstadt von Sturmwind.", progress = "Ihr seid gereist, ja? Seid Ihr an irgendwelchen interessanten Orten gewesen?", completion = "Ah, eine Notiz von Schmied Argus? Es überrascht mich gar nicht, dass er mehr Ausrüstung braucht. Heutzutage gibt es so viele neue Rekruten.\n\nIch danke Euch, {name}. Hier habt Ihr etwas Geld für Eure Reisespesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26395] = { id = 26395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dungar Trinkfest", description = "{name}, ich habe alles, worum Argus gebeten hat, in diese Kiste gepackt. Würdet Ihr sie ihm bringen?\n\nWenn Ihr bereits mit Bartlett in Goldhain gesprochen habt, dann könnt Ihr einen Greif zurück zu ihm nehmen. Dungar Trinkfest ist unser Greifenmeister drüben im Handelsdistrikt.\n\nSprecht mit Dungar, dann bringt diese Kiste auf dem schnellsten Weg zu Argus. Wir möchten nicht, dass unsere kämpfenden Männer und Frauen in Goldhain ohne neue Ausrüstung sind!", sourceObjective = "Bringt Osrics Kiste zu Dungar Trinkfest, dem Greifenmeister.", progress = "Ist das Schweiß auf Eurer Stirn, der Herr? Ihr habt Euch beim Laufen zu sehr verausgabt. Nehmt nächstes Mal einen Greifen!", completion = "Eine Kiste für Goldhain, eh? Seid Ihr schon mal in Goldhain gewesen? Falls ja, ist das kein Problem. Ich habe viele Greifen ausgebildet, damit sie diese Route fliegen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[26396] = { id = 26396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Argus", description = "Der Name des Greifenmeisters in Goldhain ist Bartlett. Wenn Ihr bereits mit ihm gesprochen habt, könnt Ihr auf einem meiner Greifen zu ihm fliegen.\n\nVergesst nicht: Greifen sind so ausgebildet, dass sie jederzeit in ihre Hauptstadt fliegen können, bringen Euch aber nur zu anderen Greifenmeistern, wenn Ihr schon einmal dort wart.\n\nIhr habt Euch schon einmal mit Bartlett unterhalten, daher sprecht mich einfach erneut an, wenn Ihr auf einem Greifen nach Goldhain fliegen wollt. Sobald Ihr da seid, könnt Ihr Osrics Kiste zu Schmied Argus bringen.", sourceObjective = "Bucht einen Greifenritt nach Goldhain bei Greifenmeister Dungar Trinkfest, dann bringt Osrics Kiste zu Schmied Argus in Goldhain.", progress = "Ihr seid zurück aus Sturmwind? Hat Osric die Rüstungen geschickt?", completion = "Wunderbar, Ihr habt die Rüstungen gebracht! Wir werden sie sofort unter denen verteilen, die sie brauchen.\n\nVielen Dank, {name}. Ihr wart uns wirklich eine große Hilfe. Und jetzt, da Ihr Euch ein wenig mit den Greifen vertraut gemacht habt, hoffe ich, dass Ihr öfter kommt und Goldhain unterstützt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26397] = { id = 26397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geht mit der Erdenmutter", description = "Viel hat sich geändert in der Welt außerhalb Mulgores, {name}. Die Welt ist gebrochen und unsere Verbündeten der Horde haben dunkle Wege eingeschlagen. Wir müssen sie leiten. Selbst in der dunkelsten aller Stunden werden wir unsere Köpfe mutig hoch erhoben haben und der Erdenmutter Ehre erweisen.\n\nIhr müsst Euch auf den Weg machen und der Welt ein gutes Beispiel sein. Reist nach Orgrimmar. Berichtet Kriegshäuptling Höllschrei, dass die Grimmtotem vertrieben wurden. Berichtet von unserem Stolz, unserer Disziplin, unserer Stärke und unserem Leid.\n\nTal beim Himmelsturm wird Euch auf den Weg schicken. Geht in Frieden, und vergesst nie, wo Ihr herkommt.", sourceObjective = "Bringt das Mal von Bluthuf zu Garrosh Höllschrei in der Feste Grommash in Orgrimmar.\n\nSprecht mit Tal dem Windreitermeister oder wartet auf den Zeppelin, um Eure Reise anzutreten.", progress = "Was ist Euer Anliegen beim Kriegshäuptling der Horde, {race}?", completion = "Die Grimmtotem aus Mulgore vertrieben... wenn Baine möchte, dass dies gehört wird, so seid Ihr wohl wirklich ein gefährlicher Kämpfer.\n\nVom heutigen Tag an wird Eure Stärke nicht mehr Euch gehören. Sie gehört nun mir und der Horde und ist eine Waffe für den Krieg.\n\nHöllschrei wacht über Euch, {name}. Bringt den Sieg oder findet den Tod!", sourceObjectiveStatus = "unverified-source-field" }
quests[26399] = { id = 26399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schatzkiste der Mosh'Ogg", description = "Sagt, habt Ihr von den Ogern gehört? Ich hab' 'nen heißen Tipp von 'nem Typen namens Mok'thardin bekommen, dass so <'n schwachköpfiger/'ne schwachköpfige:r> {race}, lächerlich angezogen wie <ein/eine:c> {class}, 'ne Ogerhand gefunden hat und...\n\n<Skeezy bricht ab und mustert Euch.>\n\nWas sagte ich gerade? Ach ja... <ein SCHWERTSCHWINGENDER HELD/eine ATEMBERAUBENDE HELDIN> fand diese Ogerhand und Mok'thardin glaubt deswegen, dass die Oger ein besonderes Artefakt haben. Ich habe gesehen, dass sie eine Kiste in den Ruinen hinter ihrem Hügel bewachen. Habt Ihr Lust, sie für mich zu holen?", sourceObjective = "Holt die Belohnung der Mosh'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh'Ogg.", progress = "Wie kommt es, dass ausgerechnet OGER immer die unbezahlbaren Artefakte finden?", completion = "<Skeezy müht sich vergebens ab, den Kasten zu öffnen.>\n\nDiese Oger wissen wirklich, wie man eine Schatztruhe verschließt. Ich sag' Euch 'was... Ein Kasten bringt mir nichts, Held. Wir müssen einen Weg in diese Kiste hinein finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26400] = { id = 26400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Universalschlüssel", description = "Wir brauchen etwas stärkeres, als Eure fleischigen Hände, um das hier zu öffnen. Und die Trottel der Venture Company im Nordwesten haben möglicherweise genau das Richtige.\n\nDas letzte Mal, als ich da drüben war, sah ich Schredder herumlaufen, die riesige, rotierende Klingen an den Händen hatten. Das wäre eine Möglichkeit, einen Kasten zu öffnen.\n\nWenn Ihr keine Schredder findet, könnt Ihr auch die riesige Sägeklinge in ihrem Sägewerk am See ausprobieren.", sourceObjective = "Öffnet die Belohnung der Mosh'Ogg, indem Ihr gegen einen Schredder der Venture Co. kämpft, oder die Sägeklinge im Sägewerk der Venture Company benutzt.", progress = "Habt Ihr die Kiste schon geöffnet? Ich kann es kaum erwarten, zu sehen, was sich darin befindet.", completion = "<Der Goblin späht hinein.>\n\nWaaaaaaaa...?!?\n\nIch... Ich muss das zu... zu Flem... im Süden schicken. Er wird etwas damit anzufangen wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26401] = { id = 26401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Vestia", description = "Das sanfte Leuchten des Podests wird stärker. Ihr seht eine schlichte Kette, die zurückgelassen wurde. War es das, wonach der Lehrling gesucht hatte?", sourceObjective = "Bringt das Graunebelamulett zu Vestia Mondspeer im Turm von Estulan.", progress = "Ihr seid zurück… ohne ihn….", completion = "Wie schrecklich, dass jemand so voller Jungend und Talent den Dämonen zum Opfer fallen musste!\n\nBitte, verzeiht mir, dass ich auch Euch in Gefahr gebracht habe, {name}. Ich hoffe, dass Ihr dieser Dämonin nie wieder begegnen müsst…", sourceObjectiveStatus = "unverified-source-field" }
quests[26402] = { id = 26402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Shandris Mondfeder", description = "Wir Druiden haben nicht besonders viel mit den Schildwachen zu tun, aber wir arbeiten bereitwillig zusammen, um unser Land zu verteidigen. Jetzt, da Ihr mir geholfen habt, wäre es äußerst nachlässig, wenn ich Euch nicht bitten würde, auch ihnen zu helfen.\n\nShandris Mondfeder, General der Schildwachen, hat den Oberbefehl über alle militärischen Vorgänge in Kalimdor. Sie hält sich in der neu errichteten Mondfederfeste im Süden auf. Sagt Ihr, dass ich Euch schicke. Ich bin mir sicher, dass sie Eure Fähigkeiten benötigt.", sourceObjective = "Sprecht mit Shandris Mondfeder in der Mondfederfeste in Feralas.", completion = "Telaron hat mir bereits von Euch berichtet, {name}. Ich bin gespannt, ob Ihr nur halb so talentiert seid, wie er behauptet.\n\nIch kämpfe einen Krieg an mehreren Fronten und kümmere mich gleichzeitig darum, dass unsere Gebiete richtig verteidigt und unsere jüngsten Schildwachen richtig ausgebildet werden. Wenn Ihr ein geschickter Kämpfer seid, habe ich genug für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[26403] = { id = 26403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venture Company-Bergbau", description = "Mann, ich hasse die Venture Company. Sie haben eine ganze Reihe von Operationen überall im Schlingendorntal, die hart arbeitende Goblins wie mich davon abhalten, ehrliches Gold zu verdienen!\n\nWie ich das mache? Durch Diebstahl. Die Geologen der Venture Co. in der Nähe des Nazferitisees im Nordwesten sind sehr an diesen merkwürdigen blauen Kristallen interessiert, die sie in den Minen finden. Bringt mir Proben dieses Gesteins von ihren Geologen. Mir ist egal, was Ihr tun müsst, um sie zu erhalten.", sourceObjective = "Bringt 5 gerommelte Kristalle zu Skeezy Whillzap in Bambala im Nördlichen Schlingendorntal.", progress = "Habt Ihr die Kristalle? Ich brauche sie!!\n\nIch meine... ich muss wissen, dass die böse Venture Company im Schlingendorntal an Boden verliert. Denn wisst Ihr, wir ehrlichen Leute müssen unseren Lebensunterhalt verdienen!", completion = "Großartig! Wunderbar! Die werden mir einiges einbringen!!\n\nDiese Venture Company hat sich den falschen Dschungel zum Schürfen ausgesucht, nicht wahr? Es würde uns allen besser gehen, wenn sie hier verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26404] = { id = 26404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhere Lohngruppe", description = "Hey, seid Ihr schon in Hartzangs Versteck gewesen? Oh, das MÜSST Ihr sehen. Das ist alles, was ein Goblin sich je erträumen kann.\n\nIch sag Euch was... Ihr seht aus, wie <ein überzeugter/eine überzeugte:c> {class}. Rashka, die da drüben in Weste und Rock, kann Euch einen Flug verschaffen, wenn Ihr den Weg nicht bereits kennt.\n\nDer Flug geht auf mich.", sourceObjective = "Sucht Sassy Hartzang in Hartzangs Versteck am Schlingendornkap auf.", completion = "Skeezy hat Euch an den richtigen Ort geschickt. Willkommen in Hartzangs Versteck!", sourceObjectiveStatus = "unverified-source-field" }
quests[26405] = { id = 26405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mambo in Zul'Mamwe", description = "Die Schädelspalter sind eine Schande für das ganze Trollreich. Ihre kindischen Zankereien mit den Blutskalpen haben das Nördliche Schlingendorntal zerrissen. Während Stämme wie die Dunkelspeere und die Zandalari erblühen, kämpfen die Schädelspalter um Ruinen.\n\nIch wurde ermächtigt, allen Söldnern eine Belohnung zu bezahlen, die bereit sind, den Schädelspaltern eine Lektion zu erteilen. Ich ermutige daher Euch und alle, die Ihr kennt, nach Zul'Mamwe zu reisen und ihrem abtrünnigen Stamm ein Ende zu setzen.", sourceObjective = "Tötet 16 Trolle der Schädelspalter in Zul'Mamwe.", completion = "Hier ist Eure Belohnung, wie versprochen. Ihr erfüllt das Volk der Trolle mit Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[26406] = { id = 26406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fangzahn von Shadra", description = "Als nächstes brauchen wir den Fangzahn von Shadra.\n\nShadras eigene Brut bewacht ihn in den Gruselruinen im Osten. Ihr Gift ist stark, {name}... werdet nicht unvorsichtig.", sourceObjective = "Besorgt den Fangzahn von Shadra aus den Gruselruinen.", progress = "Habt Ihr den Fangzahn?", completion = "Da ist er... nur noch einer übrig.", sourceObjectiveStatus = "unverified-source-field" }
quests[26407] = { id = 26407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Handschrift von Mosh'Ogg", description = "Dieser Oger hatte einen ungewöhnlichen Gegenstand bei sich: die abgetrennte Hand eines anderen Ogers, die er an einer Schnur befestigt um den Hals trug Die Hand selbst weist viele Narben auf, die in einem schwachen lila leuchten.\n\nEine Narbe, die nach dem Tod leuchtet, ist höchst ungewöhnlich. So einen Gegenstand bei einem Oger zu finden, ist noch merkwürdiger. Vielleicht weiß jemand in Grom'gol etwas mit dieser Kuriosität anzufangen.", sourceObjective = "Bringt die entstellte Hand eines Mosh'Ogg zu Scharfseher Mok'thardin im Basislager Grom'gol im Nördlichen Schlingendorntal.", progress = "Eine Hand sagt Ihr?", completion = "<Der Scharfseher achtet darauf, dass er den Gegenstand an der Schnur hält und vermeidet sorgfältig, die Faust des toten Ogers zu berühren.>\n\nDas ist in der Tat merkwürdig. Ich werde das meinen Kontakten im Osten, in der Nähe des Hauptlagers der Mosh'Ogg, unterbreiten. Ich habe so ein Gefühl, als ob sie sich für diese seltsamen Narben interessieren könnten.\n\nIch danke Euch, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26408] = { id = 26408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche im Eschental", description = "Dunkelküste mag zerschlagen und zerschmettert sein, aber dank Euch haben wir hier ein gewisses Maß an Sicherheit erlangt. Ein gewisses Maß an Frieden. Wir müssen noch viel wieder aufbauen.\n\nIhr solltet weitermachen, <mein Freund/meine Liebe>. Garrosh hat die geballte Macht seiner Horde gegen uns im Eschental aufgefahren. Sie werden uns alle töten und den Wald roden, wenn wir nicht gegen sie vorgehen.\n\nUm Hoffnung zu bewahren, diese Wälder nicht vollständig aufgeben zu müssen, benötigen wir Eure Hilfe. Folgt der Straße in Richtung Süden und sucht Schildwache Shyela auf.", sourceObjective = "Sprecht mit Schildwache Shyela bei Orendils Zuflucht im Eschental.", completion = "Schön, ein neues Gesicht in dieser Gegend zu sehen!\n\nDie Horde kriecht überall in den Wäldern herum, aber mein Auftrag sieht vor, dass ich diesen Außenposten absichere. Ich könnte wirklich jemanden gebrauchen, der ein wenig Kampflust mitbringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26409] = { id = 26409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Goldmine?", description = "Mein goblinischer Initiand ist schon eine ganze Weile fort. Sein Name ist Goldmine.\n\nIch habe ihn losgeschickt, um die Felsklauen im Südwesten im Quarzitbecken zu beobachten. Wärt Ihr bereit, ihn zu suchen? Wenn Ihr ihn findet, bittet ihn, zum Tempel zurückzukommen.", sourceObjective = "Findet Initiand Goldmine am Quarzitbecken in Tiefenheim.", completion = "Hallöchen! Könnt Ihr mir vielleicht kurz helfen, Spezi?", sourceObjectiveStatus = "unverified-source-field" }
quests[26410] = { id = 26410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Verbundmasse", description = "Dieser Kerl ist der Sohn des Anführers der Irdenen! Er hatte es schon fast zurück in den Tempel geschafft, als er von mehr Felsklauen angegriffen wurde, als ich zählen konnte!\n\nWir wissen, dass der Steinvater der Irdenen das mittlere Fragment der Weltensäule besitzt. Wenn wir seinen Sohn heilen, gibt er uns vielleicht das Fragment.\n\nMeine Heilzauber funktionieren bei Flint hier nicht. Aber wenn wir an etwas Quarzitharz von diesen Monstern kommen könnten, könnte ich eine explosive Verbundmasse herstellen, die seine Wunden schließt und kauterisiert.", sourceObjective = "Sammelt 5 Einheiten Quarzitharz.", progress = "Ich brauche nicht viel Harz. Diese Felsklauen sind jedoch ziemlich gefährlich.", completion = "Was für ein Glück, dass ich zufällig Großmeister der explosiven Alchemie bin.\n\nDas hier wird sich aber nicht von allein entzünden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26411] = { id = 26411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitztrocknung", description = "In Ordnung, nehmt dies und gebt es auf seine Wunden. Wenn die blitzartige Kauterisation ihn nicht in Stücke reißt, sollte er dadurch vollständig heilen.\n\nGlaube ich…", sourceObjective = "Behandelt Flint Erzmantel mit der explosiven Verbundmasse.", progress = "Quasselt mich nicht voll. Behandelt Flint mit der explosiven Verbundmasse.", completion = "Sieht aus, als hätte es gewirkt. Er sollte jeden Moment zu sich kommen.\n\nIch habe Euch doch gesagt, dass ich ein Großmeister der Alchemie bin!\n\nIch habe noch etwas Harz übrig. Daraus kann ich allerlei wundervolle explodierende Dinge bauen. Was wollt Ihr haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[26412] = { id = 26412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schatzkiste der Mosh'Ogg", description = "Sagt, habt Ihr von den Ogern gehört? Ich hab' 'nen heißen Tipp von 'nem Typen namens Mok'thardin bekommen, dass sie ein ganz besonderes, magisches Artefakt in ihrer Höhle verstecken. Skeezy weiß das aber besser. Ich rieche Geld aus einer Mulgoremeile Entfernung und ich wette, das Ogerdingsbums ist ein Vermögen wert.\n\nHier ist ein Hinweis: Ich habe gesehen, dass sie eine Kiste in den Ruinen hinter ihrem Hügel bewachen. Habt Ihr Lust, sie für mich zu holen?", sourceObjective = "Holt die Belohnung der Mosh'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh'Ogg.", sourceObjectiveStatus = "unverified-source-field" }
quests[26413] = { id = 26413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt ihn zur Erdenruferin", description = "Er scheint mir immer noch etwas wackelig auf den Beinen zu sein. Sein Kopf muss dröhnen.\n\nAm besten bringt Ihr ihn in den Tempel zur Erdenruferin und schaut, was sie für ihn tun kann.\n\nIch werde noch ein Weilchen hier draußen bleiben und diese Felsklauen \"beobachten\".", sourceObjective = "Bringt Flint Erzmantel zu Erdenruferin Yevaa im Tempel der Erde.", progress = "Einer der Irdenen? Das ist eine unerwartete und günstige Überraschung, {name}.", completion = "Die Anwesenheit von Flint Erzmantel ehrt uns. Wie ich gehört habe, befindet sich ein Fragment der Weltensäule im Besitz des Steinvaters.\n\nEs ist von oberster Wichtigkeit, dass wir alle Fragmente wiedererlangen. Die Instabilität zwischen den Welten wird immer stärker. Bald ist sie vielleicht schon so groß, das nicht einmal der mächtige Thrall ihr Einhalt gebieten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26414] = { id = 26414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Zander erwischen", description = "Manchmal fische ich zum Spaß. Dann wieder, um zu entspannen, aber manchmal brauche ich eine Herausforderung. Da kommt der verhärtete Zander ins Spiel. Dieser wertvolle Fisch wird nicht als Speise gefangen, sondern wegen der Herausforderung. Ihr werdet den Zander im Sturmwindsee nördlich der Stadt finden. Glaubt Ihr, Ihr seid der Herausforderung gewachsen?", sourceObjective = "Catherine Leland in Sturmwind möchte, dass Ihr ihr 8 verhärtete Zander bringt.", progress = "War die Herausforderung zu viel für Euch?", completion = "Gute Arbeit, {name}. Wie ich sehe, seid Ihr inzwischen ein ziemlich guter Angler. Vielleicht sollte ich Euch bald mit dem Boot mit hinausnehmen, um zu sehen, was Ihr wirklich könnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26416] = { id = 26416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf in den Dschungel", description = "Mein Kommandant hat mich ausgeschickt, um nach Rekruten Ausschau zu halten, die bei der Verteidigung des Basislagers von Grom'gol im Nördlichen Schlingendorntal helfen. Kennt Ihr das Schlingendorntal? Es ist sehr weit weg... Man muss das Große Meer überqueren, und dann befindet es sich an der südlichen Spitze der Östlichen Königreiche. Ihr passt auf die Beschreibung, die er mir gegeben hat... Seid Ihr daran interessiert, Kalimdor für eine Weile zu verlassen?\n\nWenn ja, sprecht mit meinem Kollegen Bort in Orgrimmar. Er wird Euch behilflich sein, an Bord des Zeppelins zu gehen.\n\nUnd sagt ihm von mir \"Wusel-Dusel\". Er weiß schon, was das bedeutet.", sourceObjective = "Meldet Euch bei Bort in Orgrimmar.", completion = "Hah! Diese Allumpass ist wirklich zu komisch.\n\nOh, stimmt ja, Schlingendorntal. Ihr wollt wirklich dorthin?", sourceObjectiveStatus = "unverified-source-field" }
quests[26417] = { id = 26417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Nördliche Schlingendorntal: Das Gefallene Reich", description = "Kommandant Aggro'gosh sucht nach ergebenen Hordenmitgliedern, um ihm bei seiner Mission in Grom'gol zu helfen. Wenn Ihr interessiert seid, geht einfach oben auf den Zeppelinturm und besteigt den Zeppelin nach Grom'gol. So einfach ist das!\n\nIm Ernst, das Schlingendorntal ist momentan genau der richtige Aufenthaltsort... Dort gibt es reichlich Action und nicht annähernd so viel Schäden durch den Kataklysmus wie im... sagen wir... Steinkrallengebirge. Ich wünschte, ich könnte mit Euch kommen.", sourceObjective = "Meldet Euch bei Kommandant Aggro'gosh im Basislager Grom'gol im Nördlichen Schlingendorntal.", completion = "Schön, dass Ihr es geschafft habt! Gehen wir an die Arbeit, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[26418] = { id = 26418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Panzer von Shadra", description = "Wir müssen noch einen weiteren Teil finden und dann haben wir alles, was wir brauchen.\n\nDer Panzer von Shadra wird von der letzten lebenden Priesterin der Spinnengöttin bewacht, von Qiaga der Bewahrerin. Sie ist auf dem Altar von Zul und wird von anderen fanatischen Zeloten bewacht.\n\nEin Kinderspiel, oder? Steigt die Treppen des Altars hoch und lasst ihren Kopf die Treppen runter rollen. Bringt mir den Panzer und wir können Shadra endlich beschwören.", sourceObjective = "Tötet Qiaga die Bewahrerin und besorgt den Panzer von Shadra.", progress = "Habt Ihr den Panzer?", completion = "Ja... endlich ist es soweit. Shadra wird unser sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[26419] = { id = 26419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadra, Königin des Giftes", description = "<Der Boden wackelt als der Götze auf den Altar gesetzt wird und der See beginnt zu schäumen! Shadra erscheint!>", sourceObjective = "Tötet Shadra, die Königin des Giftes.", completion = "Ausgezeichnete Arbeit. Ihr habt der Dunklen Fürstin gute Dienste geleistet, {name}.\n\nIhr böses Blut wird unsere Armeen mit einer mächtigen Waffe gegen die verachtenswerte Allianz bieten. Wir werden sie aus diesen Ländern vertreiben.\n\nFür die Horde, versteht sich... und alles dank Eurer Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26420] = { id = 26420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Würmern graben", description = "He da, Angler! Arnold hier sagt, dass Ihr nach einem neuen Angelpunkt sucht und ich glaube, ich kenne genau den richtigen Ort. Nördlich von Sturmwind gibt es ein kleines Fleckchen Erde, das Olivias Teich heißt.\n\nDer Teich wird jedes Jahr mit neuen Kristallbarschen bestückt, aber sie sind schwer zu fangen. Sie beißen nur bei einem bestimmten Köder... Übergroße Regenwürmer. Wenn Ihr das Ufer des Teichs absucht, solltet Ihr ausreichend Würmer finden, die Ihr als Köder benutzen könnt.", sourceObjective = "Findet einen übergroßen Regenwurm in der Nähe von Olivias Teich und benutzt ihn als Köder, um einen Kristallbarsch zu fangen. Kristallbarsche findet man in Olivias Teich, nördlich von Sturmwind.", progress = "Hat der Köder funktioniert?", completion = "Das sind doch mal nette Barsche, {name}. Lasst sie uns braten und probieren, wie sie schmecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[26421] = { id = 26421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochtüftler", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.\n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", sourceObjective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", completion = "Schön, Euch kennenzulernen, {name}. Wahrscheinlich habt Ihr andere bereits von der Operation: Gnomeregan sprechen gehört. Lasst mich Euch ein wenig darüber erzählen, was geschehen ist und warum wir die Zwergenstadt Eisenschmiede verlassen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26422] = { id = 26422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochtüftler", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen. \n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", sourceObjective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", completion = "Schön, Euch kennenzulernen, {name}. Wahrscheinlich habt Ihr andere bereits von der Operation: Gnomeregan sprechen gehört. Lasst mich Euch ein wenig darüber erzählen, was geschehen ist und warum wir die Zwergenstadt Eisenschmiede verlassen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26423] = { id = 26423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochtüftler", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen. \n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", sourceObjective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", completion = "Schön, Euch kennenzulernen, {name}. Wahrscheinlich habt Ihr andere bereits von der Operation: Gnomeregan sprechen gehört. Lasst mich Euch ein wenig darüber erzählen, was geschehen ist und warum wir die Zwergenstadt Eisenschmiede verlassen haben.", sourceObjectiveStatus = "unverified-source-field" }
