quests[26425] = { id = 26425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochtüftler", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.\n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", sourceObjective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[26426] = { id = 26426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein grausamer Sturm", description = "Es gibt eine Aufgabe, die ich Euch anvertrauen kann.\n\nEs ist eine gefährliche Aufgabe. Wenn Ihr sie erfüllt, könnt Ihr weitere der sturen Steinlords beeindrucken.\n\nIm Nordwesten findet Ihr den Geschliffenen Schlund. Harte Winde schlagen dort gegen die Felsen und verbergen die wahre lebende Bedrohung darunter.\n\nIn den Geschliffenen Weiten leben die Schleifwürmer. Sie fressen sich durch die Felsen, als wären sie aus Wasser. Dasselbe tun sie auch mit unserer Steinhaut.\n\nSucht Felsen den Ausdauernden. Er wird Euch sagen, wie Ihr in die Bruchtiefen gelangt. Ich werde mit Euch sprechen, sobald Ihr dort angelangt seid.", sourceObjective = "Findet Felsen den Ausdauernden und folgt seinen Anweisungen, um in die Bruchtiefen zu gelangen.", completion = "<Der Boden zittert ein wenig, als Ihr Euch der Höhle nähert. Dies scheint der Eingang zu sein, von dem Diamant und Felsen gesprochen haben.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26427] = { id = 26427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Kapitän oder Besatzung", description = "Ich weiß nicht, zu wem Ihr gehört, aber Ihr seht nicht aus wie einer von… ihnen.\n\nIch weiß nicht, was geschehen ist. Ich habe das Abendessen verschlafen und bin dann auf einem Schiff voller Toter und Mörder aufgewacht.\n\nIch weiß nicht, ob Ihr mich töten wollt, aber ich erspare Euch die Mühe.\n\n<Mürrisch zeigt auf eine Wunde in seinem Bauch. Seine Innereien sind nicht mehr da, wo sie sein sollten.>\n\nIch kann das Schiff noch eine Weile steuern. Von einer Bauchwunde stirbt man nicht sofort. Bringt mir einfach ein Stück Seil und etwas Rum... nein, Whiskey.", sourceObjective = "Bringt dem Ersten Maat Mürrisch eine Whiskeyflasche und eine Seilspule.", progress = "Habt Ihr, worum ich Euch gebeten habe?", completion = "In Ordnung. Helft mir, mich ans Steuer zu binden.\n\n<Mürrisch nimmt einen Schluck aus der Flasche.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26428] = { id = 26428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Dieben stehlen", description = "Die Hure! Das Flittchen! Kenata lebt noch; ihre Familie blüht und gedeiht, während ich leide. Verlassene, wahrhaftig!\n\nMeine Familie ist tot, Opfer der Seuche. Unser Besitz ebenfalls dahin, während des Kriegs geplündert und niedergebrannt. Und nach alldem haben sie und ihre lausigen Kinder die Stirn, das einzig Kostbare zu stehlen, das ich noch hatte.\n\nMir sind die Sachen, die sie gestohlen haben, längst einerlei. Ich will ihre Köpfe!\n\nTötet sie für mich! Geht zum Bauernhof der Dabyries in Arathi, nordöstlich der Zuflucht.", sourceObjective = "Enthauptet Kenata Dabyrie, Fardel Dabyrie und Marcel Dabyrie.", progress = "Tötet sie alle und bringt mir ihre Köpfe!", completion = "Ihr steht als Racheengel vor mir und ich verneige mich dankbar vor Euch.\n\nNachdem diese Kuh tot ist und ich weiß, dass ihre Brut sich nicht mehr über Azeroth ausbreiten kann, kann ich meine Energie lukrativeren Dingen zuwenden. Ich hoffe, Ihr habt ihren Bauernhof geplündert, als Ihr sie getötet hattet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26429] = { id = 26429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschmettert die Bleichborken", description = "Die Trolle der Bleichborken und die Oger der Felsfäuste aus Arathi arbeiten Hand in Hand, um uns aus diesen Landen zu vertreiben. Doch weder sie, noch jemand anders wird unser Schicksal besiegeln. Wir werden sie vernichten und ihnen zeigen, dass auch wir hier unsere Heimat haben. \n\nDie Trolle haben sich von uns abgewendet; die Oger benutzten uns als Nahrung und Bettzeug, wenn wir es zuließen. Das darf einfach nicht sein.\n\nWir beginnen unseren Angriff bei den Trollen der Bleichborken südlich von hier. Schlachtet sie scharenweise ab und kehrt erst dann zurück, wenn ihre Lager blutgetränkt sind.", sourceObjective = "Tötet 10 Axtwerfer der Bleichborken, 10 Kopfjäger und 8 Hexendoktoren.", completion = "Eure Kleidung zeugt von Krieg und von Eurer Stirn läuft der Schweiß. Das ist gut, sehr gut sogar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26430] = { id = 26430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Dorf der Bruchhauer", description = "Nicht alle Waldtrolle sind widerliche Plagegeister wie die Bleichborken. Nördlich von hier im Hinterland befindet sich das Dorf der Bruchhauer, Heimat der einzigen Waldtrolle, die noch mit der Horde verbündet sind.\n\nSogar sie können sich der Grausamkeit ihrer Brüder nicht entziehen. Der Stamm der Blutfratzen liegt mit ihnen im Krieg und lenkt sie von unserem Kampf gegen die Allianz ab.\n\nIhr habt hier gut gekämpft. Sprecht mit Urda, wenn Ihr ins Dorf der Bruchhauer fliegen möchtet. Ihr Dorf könnte Eure Stärke gut gebrauchen.", sourceObjective = "Reist zum Dorf der Bruchhauer im Hinterland und sprecht mit dem Ältesten Stumpfhauer.", completion = "Willkommen im Dorf der Bruchhauer, {class}. Ich hoffe, dass der Kampf gegen die Bleichborken Euch nicht ausgelaugt hat - die Blutfratzen sind noch schlimmer.", sourceObjectiveStatus = "unverified-source-field" }
quests[26431] = { id = 26431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archäologie", description = "Nehmt diese Quest an, um Archäologiepunkte auf Eurer Landkarte zu finden!" }
quests[26432] = { id = 26432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall von Jintha'Alor", description = "Wir müssen uns um weit mehr kümmern, als nur Zwerge, Mann. Während ich das Dorf bewache, führt meine Freundin Ura Stumpfhauer unsere Krieger gegen den gemeinen Blutfratzenstamm.\n\nSie haben unsere Brüder getötet und ich wurde sogar einmal von ihnen gefangen genommen. Jetzt ist es genug! Dieses Mal fällt die Stadt Jintha'Alor in unsere Hände.\n\nGeht nach Jintha'Alor und sprecht mit meiner Freundin. Sie hat ein Lager nahe des Eingangs zur Stadt erobert.", sourceObjective = "Findet Ura Stumpfhauer bei Jintha'Alor im Hinterland.", completion = "Willkommen, {class}. Wir werden dafür sorgen, dass die Blutfratzen es bereuen, uns über den Weg gelaufen zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26433] = { id = 26433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das heilige Wasser der Klarheit", description = "Skeezy hat schon gesagt, dass Ihr kommen würdet. Dann lasst uns dieses... Ding mal identifizieren.\n\nZunächst müsst Ihr das heilige Wasser der Klarheit besorgen. Die Naga im Südosten unterhalten einen heiligen Schrein, aus dem köstliches klares und pures Wasser fließt. Sobald man auch nur einen Schluck von diesem heiligen Wasser schlürft, wird der Geist geläutert und der beste Weg liegt dem Trinkenden klar vor Augen.\n\nHört sich gut an, nicht wahr?\n\nBeschafft es aus dem Nek'maniquellbrunnen, der sich an dem höchsten Punkt des Nagacamps befindet. Viel Glück!", sourceObjective = "Beschafft das heilige Wasser der Klarheit aus dem Nek'maniquellbrunnen am Schlingendornkap.", progress = "<Flem spitzt die Ohren, als Ihr Euch nähert.>\n\nDas heilige Wasser der Klarheit? Ist es hier!?", completion = "<Der Goblin stürzt das Wasser in einem Zug hinunter.>\n\nAhh... Wisst Ihr, wie schwer es ist, hier im Schlingendorntal frisches Wasser zu bekommen? Kein Wunder, dass die Naga ihren Schrein so erbittert verteidigen.\n\nOh, stimmt ja... Euer Artefakt und Klarheit. Klarheit...\n\nIch hab's!", sourceObjectiveStatus = "unverified-source-field" }
quests[26434] = { id = 26434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursprüngliche Reagenzien der Macht", description = "Ich sehe es jetzt ganz deutlich... Der Schlüssel, um diesen mysteriösen Talisman zu identifizieren, liegt bei einigen sehr seltenen und wertvollen Gegenständen. Diese ursprünglichen Reagenzien der Macht werden uns den Ursprung des Schatzes enthüllen, wenn sie richtig kombiniert werden.\n\nReist nach Norden auf die Westseite der Arena der Gurubashi und jagt die Katzen, die den Dschungel durchstreifen. Ihre flauschigen Felle werden uns zur Wahrheit führen!", sourceObjective = "Beschafft 4 geschmeidige Tigerinnenfelle und 4 samtige Pantherfelle.", progress = "Achtet darauf, dass die Reagenzien ganz besonders kuschelig sind, {name}. Kratzende Reagenzien reichen einfach nicht.", completion = "<Flem streicht über die Felle und lächelt versonnen.>\n\nAusgezeichnete Arbeit, {name}! Diese Reagenzien werden perfekte Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26435] = { id = 26435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin ein gewaltiger Lügner und Betrüger", description = "Ich habe keine Ahnung, was dieses Artefakt ist. Ich habe auch keine Ahnung, wo ich überhaupt ANFANGEN sollte, herauszufinden, was das ist.\n\nUm genau zu sein habe ich keine Ahnung, warum überhaupt jemand auf die Idee kam, dass ICH in der Lage sein könnte, es zu identifizieren.\n\nIch habe um Wasser gebeten, weil ich Durst hatte. Ich habe um Juwelen und Felle gebeten... nun, für meine Freundin.\n\nHoffentlich kann ich Euch wenigstens die richtige Richtung weisen. Garley Lichtreiter in Beutebucht ist ein Mitglied der Archäologischen Akademie und könnte möglicherweise hilfreicher sein, als ich es war.\n\nTut mir leid.", sourceObjective = "Bringt die geöffnete Schatzkiste der Mosh'Ogg zu Garley Lichtreiter in Beutebucht am Schlingendornkap.", progress = "Ja, {race}? Ich bin sehr beschäftigt.", completion = "Faszinierend!\n\nIch brauche etwas Zeit, um mir das genauer anzusehen. Warum seht Ihr Euch nicht ein wenig in Beutebucht um und kommt später wieder?", sourceObjectiveStatus = "unverified-source-field" }
quests[26436] = { id = 26436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwurzelt", description = "Eure Absichten scheinen ehrlich zu sein.\n\nIch werde den anderen Steinlords von meinem vorsichtigen Vertrauen erzählen.\n\nDanach sollten sie gewillt sein, mit Euch zu sprechen.\n\nUnd was noch wichtiger ist, sie sollten gewillt sein, zuzuhören.\n\nIhre Gunst zu erlangen, wird Zeit in Anspruch nehmen. Die Gunst der Steinmutter zu erringen, wird wohl noch länger dauern. Zeit ist ein wirksames Geschenk, geht also großzügig damit um.\n\nBei den Berstenden Säulen, weit im Nordwesten, findet ihr Kor den Unbeweglichen. Er hat ein ausgeglichenes Gemüt. Aufgrund seiner Lage ist er auf Hilfe von anderen angewiesen.\n\nGeht zu ihm.", sourceObjective = "Findet Kor den Unbeweglichen bei den Berstenden Säulen.", completion = "Diamant sagt, dass man Euch vertrauen kann. Diamant ist geduldig und weise, also werde ich Euch die Möglichkeit geben, Euch zu beweisen.\n\nWie es der Zufall will, könnte ich Hilfe von jemandem gebrauchen, der etwas… beweglicher ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26437] = { id = 26437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallklar", description = "Bei den Berstenden Säulen befinden sich Kristalle. Weiße, kalkhaltige Kristalle. Wir können diese Kristalle in unsere Haut absorbieren. Um uns zu reinigen. Uns zu läutern.\n\nIch wandle nicht mehr zwischen den Steinen. Ich bin eins mit der Erde. Das hat viele Vorteile, doch ich kann mir die Kristalle nicht mehr selbst beschaffen.\n\nBringt mir die Kristalle, so dass ich stärker werde. Nehmt sie den Felsklauen weg. Nehmt sie meinen Söhnen weg. Diese Ehre sollte nur mir vorbehalten sein.", sourceObjective = "Sammelt 8 kalkhaltige Kristallformationen.", progress = "Habt Ihr mir den Gefallen getan, um den ich Euch bat? Habt Ihr mir die Kristalle gebracht?", completion = "Ahh… erfrischend. Vielen Dank, Fleischling.", sourceObjectiveStatus = "unverified-source-field" }
quests[26438] = { id = 26438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intervention", description = "Die Felsklauen sind wahnsinnig vor Hunger. Einst gruben sie mit Bedacht und Mäßigung. Jetzt ist ihr Hunger jedoch unersättlich. Sie sind blutrünstig und gewalttätig geworden.\n\nSie haben sich gegen meine Söhne gewandt. Sie überwältigen sie. Tötet sie. Es muss aufhören.\n\nTötet die Felsklauen. Sie erfüllen keinen Zweck auf dieser Welt. Niemand wird sie vermissen. Rettet meine Söhne. Tötet alle Felsklauen, die Ihr finden könnt.", sourceObjective = "Tötet 12 Jaspisspitzenfelsklauen.", completion = "Ihr habt Euch als nützlich erwiesen, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26439] = { id = 26439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Teile zusammenfügen", description = "{race}. Wenn Ihr den Steinlords dient, gibt es jemanden, der Euch vielleicht helfen wird.\n\nHaltet nach den Steingebundenen Ausschau. Sie schlafen überall bei den Berstenden Säulen verteilt. Es sollte kein Problem sein, sie aufzufordern, sich neu zu binden und Euch gegen die Felsklauen zu unterstützen.", sourceObjective = "Helft 6 schlafenden steingebundenen Elementaren dabei, sich neu zusammenzufügen.", completion = "Danke, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26440] = { id = 26440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anhänglich", description = "<Ein winziger Elementar scheint Gefallen an Euch gefunden zu haben.>\n\nKiris… Krissi… Kristall? <Kieselchen schaut Euch erwartungsvoll an.>\n\n<Erst jetzt bemerkt Ihr die riesige Kristallformation in der Mitte der Berstenden Säulen. Vielleicht solltet Ihr ihn dorthin bringen?>", sourceObjective = "Bringt Kieselchen zur großen Kristallformation in den Berstenden Säulen.", progress = "<Kieselchen schaut Euch erwartungsvoll an.>", completion = "<Die Steine in Kieselchens Körper springen fröhlich auf und ab. Er ist offenbar sehr dankbar.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26441] = { id = 26441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So groß, so rund…", description = "<Kieselchen schaut sich um und scheint über etwas ganz aufgeregt zu sein. Nach ein paar Sekunden der Verwirrung bleibt er stehen und starrt Euch mit großen leuchtenden Edelsteinaugen an.>\n\nHug-nrig… Hungrig…\n\n<So sehr Ihr es auch versucht, gegen diesen Blick seid Ihr einfach machtlos. Vielleicht weiß Kor ja, was Mini-Elementare gerne essen.>", sourceObjective = "Sprecht mit Kor, um herauszufinden, was Kieselchen gerne isst.", completion = "Habt Ihr einen neuen Freund gewonnen?\n\nSeid Ihr sicher, dass Ihr ihn füttern wollt? Er könnte sich an Euch gewöhnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26442] = { id = 26442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felshummer", description = "Wenn ich meine Henkersmahlzeit selbst aussuchen könnte, dann würde ich mich auf jeden Fall für frische Hummerschwänze entscheiden. Irgendetwas an dem leckeren Krustentier ist unwiderstehlich! Vor Kurzem haben wir begonnen, Hummer hier in Sturmwind zu fangen. Würde es Euch etwas ausmachen, hinauszugehen und die Fallen für mich zu überprüfen?\n\nEins noch... Passt auf die Haie auf. Die können ziemlich grausam sein.", sourceObjective = "Sammelt 6 Felshummer aus den Käfigen unter den Docks im Hafen von Sturmwind auf. Achtet auf Haie!", progress = "Anscheinend seid Ihr den Haien erfolgreich ausgewichen. Waren Hummer in den Fallen?", completion = "Die Fallen funktionieren anscheinend! Danke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26443] = { id = 26443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflische Pläne", description = "Der Dämon hat dieses Pergament fallengelassen, das erstaunlicherweise in Gemeinsprache verfasst ist! Die darin erwähnten Namen, Diathorus und Gorgannon, gehören zwei berüchtigten Schreckenslords, die in dieser Gegend die Dämonen kontrollieren.\n\nDie Pläne beschreiben genau die Vorbereitungen auf einen Angriff der Dämonen auf Waldeslied im Norden. Das ist der Ort, an dem eine neue Siedlung der Draenei erbaut wird. \n\nMöglicherweise interessiert sich Verteidiger Vedaar am Holzfällerlager des Kriegshymnenklans hierfür?", sourceObjective = "Liefert die teuflischen Pläne bei Verteidiger Vedaar am Holzfällerlager des Kriegshymnenklans in Eschental ab.", progress = "Was habt Ihr da, mein Herr?", completion = "Bei den sieben Kristallen von Ata'mal, das darf nicht sein! Sie haben vor, Waldeslied anzugreifen?!\n\nNicht, solange ich Dienst habe!\n\n<Verteidiger Vedaar zerknüllt die von Dämonen gekritzelten Pläne in seiner Faust.>\n\nNein. Das werden wir nicht zulassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26444] = { id = 26444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstört die Legion", description = "Ich werde ihre Existenz in dieser Welt nicht dulden! Die Brennende Legion hat unser Volk so gut wie zerstört, und wir haben uns zurückgezogen, um in einer neuen Welt eine neue Heimat zu erschaffen. Dann kehrten sie zurück, und wir haben uns erneut zurückgezogen, wieder und wieder.\n\nNicht länger!\n\nIm Süden und im Westen befinden sich noch Überreste der Legion. Die Regionen heißen Dämonenhügel, Dämonensturz und Dämonenstieg. Das ist von der Streitmacht, die einst in diese Welt einfiel, noch übrig.\n\nGeht und vernichtet so viele von ihnen, wie möglich, bevor es zu spät ist!", sourceObjective = "Tötet 15 beliebige Dämonen am Dämonenhügel, am Dämonensturz und am Dämonenstieg.", completion = "Ihr habt meinen Respekt und meinen Dank, {class}. Vielleicht können wir jetzt hier eine neue Heimat schaffen, ohne uns um die Brennende Legion Sorgen machen zu müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26445] = { id = 26445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nie wieder!", description = "{name}, es ist Eure Aufgabe dafür zu sorgen, dass dieser Angriff der Brennenden Legion niemals stattfindet. Geht und erschlagt diese Schreckenslords. Ohne sie sind Dämonen nur ein Haufen geistloser Untiere.\n\nIhr findet Gorgannon im Dämonensturz südlich hinter dem Dämonenhügel in der Nähe des schwebenden Speers von Mannoroth.\n\nDiathorus der Sucher lebt irgendwo im Grabhügel auf dem Dämonensturz. Um dort hinaufzugelangen, sucht nach einem Stieg in der Nähe des Denkmals für Grom Höllschrei.\n\nBringt mir ihre Waffen.", sourceObjective = "Besorgt Gorgannons flammende Klinge und den Teufelsspeer des Suchers.", progress = "Unsere Nachtelfenspione berichten, dass die Vorbereitungen für den Angriff fast abgeschlossen sind. Diese Schreckenslords müssen schnell sterben, {name}!", completion = "Die Brennende Legion wird das Eschental nie wieder bedrohen! Ihr habt uns vor einem Kampf gerettet, den wir wahrscheinlich verloren hätten, {class}.\n\nIch danke Euch, {name}, und die tiefste Dankbarkeit der Hand von Argus. Es ehrt mich, Euch auf unserer Seite zu wissen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26446] = { id = 26446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung des Dämonenhügels", description = "Kleines Wesen. Im Südwesten gibt es ein Gebiet im Nachtweisenwald, das seit kurzer Zeit Dämonenhügel genannt wird. Es ist sehr traurig zu sehen, wie die Dämonen auf ihm herumkrabbeln und ihre Verderbnis verbreiten.\n\nIch habe ein paar Samen, die ich für eine solche Gelegenheit aufgehoben habe. Bringt sie zum Dämonenhügel und pflanzt sie in fruchtbare Erdhaufen.", sourceObjective = "Pflanzt 8 Baumsetzlinge in die fruchtbaren Erdhaufen.", completion = "Gut. Auch wenn es vielleicht lange Zeit dauern mag, bis aus den Setzlingen Urtume werden, werden sie uns dann im Kampf gegen die Feinde des Eschentals helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26447] = { id = 26447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflische Pläne", description = "Der Dämon hat dieses Pergament fallenlassen, welches überraschenderweise auf Orcisch geschrieben wurde! Darin werden Diathorus und Gorgannon erwähnt, zwei berüchtigte Schreckenslords, die die Dämonen in dieser Gegend anführen.\n\nDie Pläne enthalten genaue Vorbereitungen für einen dämonischen Angriff auf den Splitterholzposten im Nordwesten.\n\nIhr seid Euch sicher, dass Valusha im Splitterholzposten daran interessiert ist.", sourceObjective = "Bringt die teuflischen Pläne zu Valusha im Splitterholzposten im Eschental.", progress = "Was habt Ihr da, Bruder?", completion = "Schreckenslords! Sie planen uns hier am Splitterholzposten anzugreifen?!\n\nNicht solange ich noch am Leben bin!\n\n<Valusha zerknüllt die Pläne mit dem Dämonengekritzel in ihrer Faust.>\n\nNein. Wir werden das nicht zulassen. Sie sind ein Schandfleck in unserer Welt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26448] = { id = 26448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstört die Legion", description = "Die Überreste der Brennenden Legion sind uns schon zu lang ein Dorn im Auge!\n\nEs ist an der Zeit, sie dafür bezahlen zu lassen!\n\nDie Dämonen greifen von den Gebieten im Osten, die als Dämonenhügel, Dämonensturz und Dämonenstieg bekannt sind, an.\n\nGeht und zerstört so viele von ihnen, wie Ihr könnt, und erlangt Ruhm für Euch selbst und für die Horde!", sourceObjective = "Tötet 15 beliebige Dämonen am Dämonenhügel, am Dämonensturz und am Dämonenstieg.", completion = "So ist es schon besser! Nichts ist so gut, wie unsere Welt von einem Dämonen zu befreien. Und sie sind würdige Gegner, nicht so wie die schwachen Völker der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[26449] = { id = 26449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nie wieder!", description = "{name}, es ist Eure Aufgabe dafür zu sorgen, dass dieser Angriff der Brennenden Legion niemals stattfindet. Geht und erschlagt diese Schreckenslords. Ohne sie ist der Rest der Dämonen nur ein Haufen geistloser Untiere.\n\nIhr findet Gorgannon im Dämonensturz südlich hinter dem Dämonenhügel in der Nähe des schwebenden Speers von Mannoroth.\n\nDiathorus der Sucher lebt irgendwo im Grabhügel auf dem Dämonensturz.\n\nKehrt mit ihren Waffen als Beweis Eurer Taten zurück.", sourceObjective = "Besorgt Gorgannons flammende Klinge und den Teufelsspeer des Suchers.", progress = "Diese Schreckenslords müssen bald sterben, {name}!", completion = "Nie wieder wird die Brennende Legion die Orcs oder ein anderes Volk der Horde versklaven! Ihr habt tapfer gekämpft, {class}!\n\nDas wahre Herz der Horde schlägt in Euch! Ihr bringt uns sehr viel Ehre!", sourceObjectiveStatus = "unverified-source-field" }
quests[26450] = { id = 26450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn sie sie einfach herumliegen lassen ...", description = "Mir kam gerade ein Gedanke, {name}. Diese Naga haben mehr als nur Schilfrohr dort unten. Sie haben kleine Statuen auf ihren Schreinen im Sand unter den Bäumen herumliegen. Sie scheinen sie nicht zu benutzen.\n\nIch könnte diese Statuen gebrauchen. Ich könnte... sie überall im Lager aufstellen, damit es sich hier etwas heimeliger anfühlt. Alles ist besser als eine blutige Dinosaurierleichenpumpe. Ich könnte sie als Andenken verkaufen.\n\nIch könnte sie an die Naga zurückverkaufen!\n\nWarum holt Ihr nicht ein paar, während ich mir etwas ausdenke.", sourceObjective = "Beschafft 6 Nagaikonen von der Südlichen Ungezähmten Küste am Schlingendornkap.", progress = "Lasst mal sehen!", completion = "Gute Arbeit, {name}. Jetzt muss ich mich nur noch entscheiden, was ich damit mache...", sourceObjectiveStatus = "unverified-source-field" }
quests[26451] = { id = 26451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurubashiherausforderung: Jeder gegen jeden in der Arena", description = "Die Arena ist ein Kampfort wie kein anderer. Darin habt Ihr keine Freunde. Bündnisse, die eingegangen werden, sind kurzlebig und Eure Verbündeten können sich von einem Augenblick zum anderen gegen Euch wenden. Horde gegen Allianz, Allianz gegen Allianz, Horde gegen Horde - alles ist möglich.\n\nNehmt diese Schlachtstandarte, {race}, und platziert sie auf dem Arenaboden. Besiegt den herbeigerufenen Kämpfer und kehrt zu mir zurück.\n\nSeid jederzeit wachsam, {race}. In der Arena der Gurubashi ist alles möglich.", sourceObjective = "Stellt die Herausforderungsflagge der Gurubashi im Kampfring ab und besiegt dann den Herausforderer der Arena der Gurubashi.", progress = "Bevor Ihr mich erneut ansprecht, sollte ein wenig mehr Blut auf Eurer Rüstung zu sehen sein.", completion = "Gut gemacht, {race}! Habt Ihr es gespürt? Den Rausch des Nahkampfs? Das wahre Risiko des Kampfes, jeder gegen jeden?\n\nDa heute Euer erster Tag hier ist, dürft Ihr noch einen Wettbewerb für eine weitere Belohnung austragen. Wenn Ihr in Zukunft zurückkehrt, dürft Ihr einmal am Tag antreten. Eure Belohnungen werden natürlich immer besser, je stärker Ihr werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26452] = { id = 26452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurubashiherausforderung", description = "Ihr seid zurückgekehrt, {race}. Das bedeutet, dass Ihr den Ruf der Arena erneut verspürt habt. Also gut.\n\nNehmt diese Schlachtstandarte, {race}, und platziert sie auf dem Arenaboden. Besiegt den herbeigerufenen Kämpfer und kehrt zu mir zurück.\n\nSeid jederzeit wachsam, {race}. In der Arena der Gurubashi ist alles möglich.", sourceObjective = "Stellt die Herausforderungsflagge der Gurubashi in dem Kampfring ab und besiegt dann den Herausforderer der Arena der Gurubashi.", completion = "Gut gemacht, {race}! Ich freue mich darauf, Euch bald wieder kämpfen zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26453] = { id = 26453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine helfende Hand", description = "Meine Leute haben im Osten des Eschentals mithilfe der Kaldorei eine wichtige Entdeckung gemacht.\n\nUnter der Aufsicht von Architekt Nemos und Verteidiger Vedaar erneuern sie einen alten elfischen Außenposten. Der Wiederaufbau wird nicht leicht werden, {name}, denn sie stehen vielen Herausforderungen und Feinden gegenüber. Ich weiß, dass Architekt Nemos und seine Landsleute in Waldeslied jede Hilfe, die sie bekommen können, zu schätzen wissen, und er hat mich gebeten, <jeden Mann, der/jede Frau> die; Interesse hat, zu ihm zu schicken.\n\nSprecht mich erneut an und ich werde dafür sorgen, dass Ihr schnell zu ihrer Stellung gebracht werdet.", sourceObjective = "Geht nach Waldeslied im Eschental und sprecht mit Architekt Nemos.\n\nVerteidigerin Palanaar kann Euch ein Reittier anbieten, um schneller dorthin zu gelangen.", completion = "Es ist schön, einen Neuankömmling hier in Waldeslied begrüßen zu dürfen.\n\nVerteidigerin Palanaar sendet so viel Hilfe, wie sie aufbringen kann, und jede helfende Hand ist willkommen.\n\nSchaut Euch um, {class}. Es ist vielleicht noch nicht viel, aber mit der Zeit und der Hilfe unserer Nachtelfenverbündeten werden wir eine Siedlung errichten, die es wert ist, Zuhause genannt zu werden. Es gibt hier viel zu tun, und für jede Hilfe, die Ihr uns leisten könnt, sind wir sehr dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26454] = { id = 26454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schändliche Verschwendung", description = "Willkommen in Waldeslied, {class}. Wo Ihr jetzt noch Zelte seht, werden einst Gebäude stehen, aber dieses Ziel erfordert einen ständigen Nachschub an Baumaterial. Ich bringe es nicht übers Herz, unseren Arbeitern zu befehlen, die uralten Bäume dieses Hains zu fällen, aber unsere Nachbarn im Süden und Westen haben keine so große Ehrfurcht vor dem Wald.\n\nWir werden das verdorbene Holz aus der Festung der Satyrn im Westen zurückfordern. Bringt das Holz zu Knorre im Holzfällerlager des Kriegshymnenklans. Er ist ein Urtum, der es für unsere Zwecke reinigen wird.", sourceObjective = "Sammelt 5 Stück verdorbenes Satyrnaarholz.", progress = "<Das Urtum knarrt, als es sich zu Euch umdreht>\n\nArchitekt Nemos sagte, Ihr brächtet Holz, das Ihr aus dem verdorbenen Satyrnaar errettet habt.", completion = "Holz, das von widerwärtiger Dämonenmagie verzerrt wurde, ist für die Draenei in Waldeslied nutzlos. Nichts Vernünftiges lässt sich daraus erbauen, doch ich werde es reinigen und Architekt Nemos zurückgeben, auf dass er und seine Leute es benutzen können.\n\nSo wird die Tragödie doch ein gutes Ende haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26455] = { id = 26455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Kelch", description = "Das Gebiet westlich von hier, das nun Satyrnaar heißt, war einst ein bedeutender Schrein meines Volkes. Dort befand sich ein Relikt von unschätzbarem Wert, Elunes Kelch, der den Hütern des Schreins von den Priestern Elunes anvertraut wurde. Einst reisten Pilger zu dem Schrein, um die heilenden Kräfte, die dem Kelch nachgesagt wurden, am eigenen Leib zu erfahren.\n\nVielleicht sind diese Geschichten nur Ammenmärchen, aber wenn nur ein Körnchen Wahrheit in ihnen steckt, könnte der Kelch vielleicht der Schlüssel zur Wiederherstellung unseres leidenden Waldes sein. Ich muss es wissen, {name}.", sourceObjective = "Bringt Elunes Kelch in Euren Besitz.", progress = "Könnt Ihr ihn fühlen, {name}, den Hauch von Verderbnis im Wind? Wenn wir nichts tun, wird er noch stärker werden. Deshalb suche ich Elunes Kelch. Konntet Ihr ihn finden?", completion = "Ausgezeichnete Arbeit, {name}. Es schlummert eine deutliche Macht in ihm, die nicht einmal die Verderbnis der Satyrn trüben kann.\n\nSeht Ihr, wie er immer noch glänzt, nach all den Jahren?", sourceObjectiveStatus = "unverified-source-field" }
quests[26456] = { id = 26456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht von der Nordfront", description = "Die Schlacht gegen das Holzfällerlager des Kriegshymnenklans wird nicht nur vom Rajenbaumturm aus geführt, {name}. Eine beträchtliche Anzahl von Schildwachen der Silberschwingen hat sich im Hain der Silberschwingen, in der Nähe der Grenze zum Brachland, postiert. Schildwache Weltensang ist für unsere Bemühungen gegen die, die unser Land zerstören wollen, verantwortlich.\n\nIch bin mit meinem Bericht an Schildwache Weltensang etwas spät dran, möchte aber den Turm nur ungern unbewacht lassen. Wenn Eure Reisen Euch in die Nähe des Silberschwingenhains bringen, könntet Ihr dann meinen Bericht abgeben?", sourceObjective = "Bringt Schildwache Melyrias Bericht zu Schildwache Weltensang im Hain der Silberschwingen im Eschental.", progress = "Was habt Ihr da, {class}?", completion = "Vielen Dank für diesen Bericht, {name}. Nach dem, was Schildwache Melyria schreibt, scheint es, als wären unsere schlimmsten Befürchtungen wahr geworden. Mit jedem Fortschritt, den wir machen, scheint die Horde umso entschlossener, so viel Schaden wie möglich anzurichten.\n\nWir können es uns nicht leisten, klein beizugeben. Das Schicksal des Landes unserer Vorfahren steht auf dem Spiel. Wenn wir mehr von Eurer Sorte an der Front hätten, könnten wir sicher triumphieren.\n\nWerdet Ihr Euch unserem Kampf anschließen? Eine neue Front hat sich gerade im Süden in der Kriegshymnenschlucht gebildet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26457] = { id = 26457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agenten der Zerstörung", description = "Das Holzfällerlager des Kriegshymnenklans ist ein Schandfleck in unserer Landschaft. Wann immer wir Fortschritte dabei machen, ihre Arbeiten zu stoppen, befiehlt Vorarbeiter Gorthak seinen Holzarbeitern, ihre Anstrengungen noch zu verdoppeln!\n\nJetzt fällen die Orcs mehr Holz, als sie je verbrauchen können und lassen es verrotten, während ihre Klingen schon wieder in frisches Holz schlagen! Dies ist eine Beleidigung gegenüber allem, für das wir einstehen, {name}, und wir werden ihnen zeigen, dass wir uns eine weitere Zerstörung unseres Landes nicht gefallen lassen!\n\nGeht, und ruht nicht, bevor Vorarbeiter Gorthak und seine Lakaien tot sind!", sourceObjective = "Tötet Vorarbeiter Gorthak und 12 weitere, beliebige Mitglieder der Horde im Holzfällerlager des Kriegshymnenklans.", completion = "Endlich haben wir ein Zeichen gesetzt, das die Orcs nicht ignorieren können. Jeder Vorarbeiter oder Großknecht, der einen Fuß in das Lager setzt, um Gorthak zu ersetzen, wird meinen Zorn zu spüren bekommen!\n\nWir müssen unseren Vorteil ausnutzen, {name}, und nicht ruhen, bevor das Holzfällerlager des Kriegshymnenklans nichts mehr als eine weit entfernte Erinnerung ist und junge Bäume ihre Wurzeln in diesen Boden schlagen.\n\nWas sagtet Ihr noch gerade über Sprengstoff...?", sourceObjectiveStatus = "unverified-source-field" }
quests[26462] = { id = 26462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die bösen Bruchhauer", description = "Die Trolle der Bruchhauer meinen etwas Besonderes zu sein, weil sie Teil der Horde sind. Da kann ich nur lachen!\n\nWisst Ihr, das wirklich Witzige ist, dass es egal ist, ob sie der Horde angehören oder nicht, ob sie ein Trollimperium besitzen oder die Brennende Legion selbst sind. Wir haben Trolle in diesen Ländern seit Urzeiten bekämpft.\n\nUm genau zu sein werde ich Euch dabei sogar helfen lassen, <Junge/Mädchen>! Nehmt Euch eine Waffe und begebt Euch zum Schlachtfeld, um unsere Jungs östlich von hier zu unterstützen.", sourceObjective = "Tötet 10 Pirscher der Bruchhauer oder Verhexer der Bruchhauer.", completion = "Nicht schlecht für einen {race} aus der Stadt. Nette Vorführung!", sourceObjectiveStatus = "unverified-source-field" }
quests[26463] = { id = 26463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Teronis", description = "Eine Freundin von mir aus Astranaar, Raene Wolfsläufer, hat mich gebeten, einen Kundschafter zum Falathimsee im Westen zu schicken. Teronis ist vor Tagen aufgebrochen, kurz bevor die Horde angegriffen hat.\n\nEr war auf der Suche nach einem Gegenstand, von dem er dachte, dass er die Furbolgangriffe auf unser Volk mildern könnte: eine Rute, die von einem mittlerweile toten, bösen Zauberer hergestellt worden ist.\n\nBevor er aufbrach, erwähnte er einen Edelstein für die Rute.\n\nLeider wissen wir, dass der See von einer bösen Macht heimgesucht wird. Bitte, {name}, macht meinen Freund ausfindig.", sourceObjective = "Sucht am Falathimsee im Eschental nach Teronis.", completion = "Teronis' Körper liegt zerschmettert auf einem kleinen Hügel neben dem Bewahrer.\n\nTiefe Schnitte ziehen sich kreuz und quer über seine Leiche.", sourceObjectiveStatus = "unverified-source-field" }
quests[26464] = { id = 26464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Stein", description = "Während Ihr Teronis' Habseligkeiten durchstöbert, stoßt Ihr auf ein durchnässtes Tagebuch.\n\nIhr blättert schnell durch die letzten noch lesbaren Seiten und lest, dass Teronis erwähnt, wie er den Edelstein gefunden hat, ihn dann aber in der Umgebung des Falathimsees verloren hat.\n\nJetzt müsst Ihr nur noch eines tun: den Edelstein finden. Vielleicht haben ihn die Tentakel...", sourceObjective = "Findet den leuchtenden Edelstein.", progress = "Ah, willkommen zurück, {name}.", completion = "Wie schrecklich, {name}. Teronis ist tot?!\n\nIch werde ihn später betrauern, aber jetzt müssen wir uns zuerst auf unsere Aufgaben konzentrieren. Ich schicke ein paar der Schildwachen aus, um Teronis' Leiche herzubringen und dem Hüter beizustehen.\n\nIhr habt den Edelstein, den Teronis suchte? Er muss sofort nach Astranaar gebracht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26465] = { id = 26465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die antiken Statuetten", description = "Ich möchte Euch mit einer Aufgabe betrauen, {class}.\n\nIch war auf meinem Boot und dümpelte über die versunkenen Ruinen von Zoram, als Naga mich angriffen. Sie sprangen aus dem Wasser und griffen mit ihren Klauen nach mir! Ich flüchtete, und der Rest ist - wie man so schön sagt - Geschichte.\n\nIch bin eine Art Archäologe und ich versuche, die Artefakte der verlorenen Stadt wiederzufinden.\n\nWürdet Ihr Euch hinaus zum Zoramstrand im Südwesten begeben und alle antiken Statuetten, die Ihr finden könnt, bergen? Sie sind der Grund, dass ich den Gefahren des Zoramstrandes getrotzt habe.", sourceObjective = "Besorgt 10 antike Statuetten.", progress = "Habt Ihr viele Statuetten gefunden, {name}?", completion = "Das sind ja doch einige, die Ihr gefunden habt! Danke, {name}!\n\nDie alte Stadt Zoram birgt viele Geheimnisse, und diese Statuetten könnten der Schlüssel zu einigen davon sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26466] = { id = 26466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuzel", description = "Ich fürchte, die Geheimnisse der antiken Statuetten werden für immer verborgen bleiben, wenn Ihr nicht den Schlüssel zu ihren antiken Schlössern findet.\n\nDieser Schlüssel ist ein Ring, der Ring von Zoram. Er gehörte einst den Herrschern dieser Stadt, bevor sie in den Wellen der Großen Zerschlagung unterging.\n\nÜber Jahre hinweg war der Ring verloren, aber die Naga haben ihn vor Kurzem gefunden.\n\nRuuzel, ihre Anführerin, haust auf einer Insel am nördlichen Ende des Zoramstrands. Bitte, {name}, beschafft mir den Ring!", sourceObjective = "Nehmt den Ring von Zoram an Euch.", progress = "Es heißt, dass der Ring von Zoram der Schlüssel zu allen Schlössern der Stadt sei. Habt Ihr ihn, {name}?", completion = "Ihr habt den Ring gefunden! Danke, {name}.\n\nBitte nehmt das hier als Lohn und wisset, dass ich Eure heutige Tat nie vergessen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[26467] = { id = 26467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elende Satyrn! Die Dryaden sind in Gefahr!", description = "Ich weiß zwar nicht, wer Ihr seid, aber ich brauche Eure Hilfe. Meine Schwestern wollten den Satyrn den Zweig des Cenarius abnehmen. Sie sagten, dass sie bald zurück sein würden, aber das war vor zwei vollen Tagen!\n\n{name}, Ihr müsst sie finden! Sie wollten nach den Ruinen eines Nachtelfentempels in Xavian im Nordwesten suchen. Ich weiß nicht, was ich davon halten soll. Sucht nach Anilia, sie wollte sie bei der Suche führen.", sourceObjective = "Sucht in Xavian im Eschental nach Anilia.", completion = "Der klaffenden Wunde in ihrer Seite nach zu urteilen, steht Anilia an der Schwelle des Todes.", sourceObjectiveStatus = "unverified-source-field" }
quests[26468] = { id = 26468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zweig des Cenarius", description = "Anilia legt Euch die Hände auf die Schultern und zieht Euch zu sich heran. Nach Luft ringend zeigt sie in Richtung des Bogens im Norden, bevor sich ihre Augen schließen und sie einen letzten, keuchenden Atemzug ausstößt. \"Er hat ihn... Geltharis...\" In Eurem Herzen wisst Ihr, dass es Anilias letzter Wunsch war, den Zweig des Cenarius wieder in den Händen der Dryaden zu sehen.", sourceObjective = "Erhaltet den Zweig des Cenarius.", progress = "Habt Ihr sie gefunden? Was hat Anilia gesagt? Wo ist sie?", completion = "Anilia ist tot? Nein... das kann nicht sein! Noch vor kurzem sind wir zusammen durch die Wälder getollt und haben gespielt.\n\nDiese Zeiten sind jetzt wohl vorbei...", sourceObjectiveStatus = "unverified-source-field" }
quests[26469] = { id = 26469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satyrn schlachten!", description = "Ich kann nicht glauben, dass Anilia von uns gegangen ist... Wir haben doch immer zusammen in den Wäldern gespielt. Ich fühle beinahe so etwas wie... Trauer.\n\nEs gibt aber etwas, das mich vielleicht aufheitern könnte! Bitte, erschlagt die Satyrn, die mir Anilia genommen haben! Bringt mir ihre Hörner als Beweis Eurer Taten und Ihr könnt Euch auf ewig meines Dankes gewiss sein.", sourceObjective = "Erhaltet 16 Satyrhörner.", progress = "Bitte, helft mir Anilias Tod zu rächen.", completion = "Danke, {race}, Ihr seid sehr freundlich. Der Geist meiner Schwester ist dankbar für Eure Bemühungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26470] = { id = 26470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung des Mystralsees", description = "Wir hätten die Silberwindzuflucht ohne Weiteres gegen den Ansturm der Horde halten können, wenn sie uns nicht die Kontrolle über unsere Wasserelementarverteidiger im Mystralsee entrissen hätten.\n\nEiner ihrer Schamanen hat Tideress heraufbeschworen, einen alten, wütenden Wassergeist des Waldes, der unsere Elementare besudelt und gegen uns aufgebracht hat. Da sowohl der See als auch die Horde über uns hereingebrochen sind, hatten wir keine andere Wahl, als uns hierher zur Spitze zurückzuziehen.\n\nBegebt Euch nach Osten. Erobert den See zurück, sodass eine Chance besteht, dass wir eines Tages die Zuflucht wieder einnehmen können.", sourceObjective = "Tötet 12 beschmutzte Wasserelementare und Tideress.", completion = "Gut gemacht, {name}! Nun da die Ränge der beschmutzten Wasserelementare dezimiert sind und Tideress wieder in den See verbannt wurde, sollten wir einen Gegenangriff auf die Silberwindzuflucht starten können.\n\n\n\nSobald wir mit der Verteidigung der Spitze fertig sind...", sourceObjectiveStatus = "unverified-source-field" }
quests[26472] = { id = 26472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irrsinnige Druiden", description = "Die Druiden sind tot. Ihre Anführer haben sie getötet - sie wurden von der Horde, die das Herz des Waldes verderben, in den Wahnsinn getrieben. Ich kann die Verderbnis sogar von hier spüren und wage es nicht, weiterzugehen.\n\nIch stehe zu sehr im Einklang mit Eschental und dem Herz des Waldes - aber Ihr... Ihr könntet in den Grabhügel hinabsteigen und das tun, was getan werden muss. Ich habe dort eine Spur für Euch gelegt.\n\nObwohl es mir das Herz zerreißt, muss ich Euch darum bitten, die einstmals großartigen Anführer der Druiden zur ewigen Ruhe zu betten: Taneel Finsterwald, Uthil Mondweise und Mavoris Wolkenbruch.", sourceObjective = "Tötet die irrsinnigen Druiden: Taneel Finsterwald, Uthil Mondweise und Mavoris Wolkenbruch.", completion = "Ruht in Frieden, meine Freunde.\n\n<Ihr könnt den Schmerz in den Katzenaugen des Druiden sehen.>\n\nIch fühlte, dass die Pein der Grabhügel von Dor'Danil nachließ und wusste, dass Ihr Euren Auftrag erfüllt hattet.\n\nWas Ihr tun musstet, war grausam, {name}, denn die Geister, die Ihr vernichten solltet, waren doch nur unschuldige Opfer der Bösartigkeit der Horde. Hoffen wir, dass auch die anderen wahnsinnigen Geister endlich Ruhe finden, da sie jetzt vernichtet sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[26473] = { id = 26473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bathranshaar", description = "In den alten Ruinen von Bathrans Schlupfwinkel, der sich auf der anderen Seite der Straße im Osten befindet, wächst eine Pflanze. Diese Pflanze heißt Bathranshaar und man sagt ihr nach, dass sie Leiden des Geistes heilen kann.\n\nJetzt erntet die Horde diese Pflanze für ihre eigenen, finsteren Pläne.\n\nIn Astranaar befindet sich ein krankes Kind. Wir glauben, dass seine Krankheit nicht nur körperlicher Natur ist. Ich habe meinem Herrn versprochen, dass ich helfen werde, ein Heilmittel zu suchen, aber ich bin kein Kämpfer. \n\nWürdet Ihr zu Bathrans Schlupfwinkel gehen und die Pflanzen sammeln?", sourceObjective = "Sammelt 8 Büschel Bathranshaar.", progress = "Habt Ihr Bathranshaar gesammelt, {name}? Die Gesundheit des Kindes schwindet mit jeder Stunde...", completion = "Ah, Ihr habt das Haar! Das ist ein guter erster Schritt. Wir werden noch weitere Zutaten benötigen, aber das Haar des gefallenen Urtums könnte die wichtigste sein.\n\nIch hoffe nur, dass die Verlassenen aus der Pflanze keine Waffe entwickeln. Wir haben einfach nicht genug Leute, um sie jetzt zu vertreiben, insbesondere, da Maestras Posten angegriffen wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[26474] = { id = 26474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orendils Heilmittel", description = "{name}, nun da es von Elunes gesegnetem Licht durchflutet wurde, glaube ich, dass das Gebräu dem kranken Kind helfen wird. Bitte bringt es nach Astranaar und gebt es dem Vater des Kindes, Pelturas Weißmond.\n\nUm nach Astranaar zu gelangen, folgt ihr der Straße nach Süden und dann nach Osten. Wenn Ihr aber schneller dorthin gelangen wollt, sprecht mit Schildwache Avana.", sourceObjective = "Bringt Orendils Heilung zu Pelturas Weißmond in Astranaar im Eschental.", progress = "Ich muss mich entschuldigen, aber ich habe jetzt keine Zeit, um zu plaudern. Meine Tochter Relara ist todkrank!", completion = "Das ist von Orendil?\n\nSeine Fertigkeiten in Kräuter- und Heilkunde sind enorm. Dieses Heilmittel gibt mir Hoffnung, dabei hatte ich schon fast aufgegeben...", sourceObjectiveStatus = "unverified-source-field" }
quests[26475] = { id = 26475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Träne", description = "Ich hatte gehofft, Orendils Heilmittel würde Relara retten, aber ich fürchte, es hat die Krankheit, die in meinem Kind wütet, nur gedämpft. Wir müssen eine stärkere Medizin finden! Zum Glück hat mir Orendil von weiteren Arzneien erzählt, sollte seine Erste versagen.\n\nElunes Träne ist eine Gesteinsart, die nur an einem Ort vorkommt: den Überresten des Irissees, der durch den Ausbruch des Donnergipfels nordöstlich von Astranaar zerstört worden ist. Orendil sagte, der Stein könne Verderbnis wegwaschen.\n\nBitte, {name}, bringt mir eine Träne Elunes und betet, dass sich die Erkrankung meiner Tochter damit heilen lässt!", sourceObjective = "Erhaltet eine Träne Elunes.", progress = "Habt Ihr die Überreste des Irissees gefunden, {name}? Habt Ihr die Träne?", completion = "Oh, Ihr habt sie gefunden! Merkwürdig...der Stein sieht irgendwie angelaufen aus. Ich werde die Träne in einen Eintopf geben und beten, dass meine Tochter davon geheilt wird.\n\nDanke! Danke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26476] = { id = 26476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dryadenlieferung", description = "Ah, da seid Ihr ja, {name}. Ich habe mich in die Anmerkungen vertieft, die Teronis gemacht hat, und es sieht so aus, als ist Euer nächster Schritt, die Teile von Dartols Rute zu finden.\n\nIch würde zunächst nach Osten reisen, zum Rajenbaumturm.\n\nDort findet Ihr eine Dryade namens Shael'dryn, die Euch eine bessere Führerin sein wird. Sucht sie auf.\n\nBehaltet den Edelstein bei Euch - Shael'dryn wird ihn brauchen, um Euch bei der Wiederherstellung der Rute zu helfen.", sourceObjective = "Liefert den leuchtenden Edelstein bei Shael'dryn beim Rajenbaumturm im Eschental ab.", progress = "Hallo. Wie geht es Euch?", completion = "Oh, Raene hat Euch geschickt? Dann muss es wohl wirklich dringlich sein.\n\nWie kann ich Euch helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26477] = { id = 26477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht den Schaft", description = "Ich wünschte, Ihr hättet bessere Nachrichten.\n\nRaene hat Recht, ich weiß von Dartols Werk und den Treants, den Baumwesen in diesem Gebiet - zumindest wusste ich es einst. Heute sind sie verderbt, ihre Natur verzerrt.\n\nFalls es Euer Ziel ist, das nächste Teil der Rute zu finden, solltet Ihr zunächst den Schlüssel suchen, mit dem die Truhe geöffnet werden kann, in der es sich befindet.\n\nEiner der Treants nordöstlich von hier in der Nähe des Teufelswalds hat ihn. Sobald Ihr ihn habt, sucht nach einem kleinen Tal westlich der Straße nahe der Grenze zum Teufelswald am Heulenden Tal. Wenn Ihr es gefunden habt, sucht nach einer kleinen Lichtung hinter dem Tunnel in diesem Tal. Die Truhe ist dort irgendwo versteckt.", sourceObjective = "Sucht den hölzernen Schlüssel und benutzt ihn, um den Eisenschaft von Dartols Rute zu finden.", progress = "Es bestürzt mich sehr, dass die Treants verderbt wurden. Ich wünschte, ich könnte mehr tun, um ihnen zu helfen.", completion = "Wie ich mich freue, dass Ihr zurück seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26478] = { id = 26478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich tot stellen", description = "Das letzte Stück der Rute ist im Besitz der Druiden der Klaue. Ich habe ihren Anführer, Oso Dornennarbe, gebeten, es mir auszuhändigen, aber er und seine Wächter hätten mich beinahe umgebracht! Offenbar hat die Verderbnis des Herzens des Waldes seitens der Horde auch die Druiden betroffen.\n\nAber ich habe eine Idee, wie Ihr in Osos Höhle gelangen und den Knauf an Euch nehmen könnt.\n\nSchon als kleiner Faun war ich immer ziemlich gut darin, mich tot zu stellen. Das funktioniert wunderbar gegen Bären! Ich kann es Euch beibringen! Geht nach Osten zum Schattenwinkel und wenn sie versuchen, Euch anzugreifen, probiert einfach meine Taktik aus.", sourceObjective = "Erhaltet das letzte Teil von Dartols Rute, den Eisenschwertknauf.", progress = "Habt Ihr das letzte Teil der Rute gefunden, {name}? Hat meine Taktik funktioniert?", completion = "Ihr habt das letzte Teil gefunden? Wie wunderbar für Euch... und für Raene.\n\nDann sollten wir beginnen, sie zu reparieren, meint Ihr nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[26479] = { id = 26479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Raene", description = "Ich schlage vor, dass Ihr Raene aufsucht und sie wissen lasst, dass die Rute fertiggestellt ist. Sie weiß bestimmt, was Ihr als Nächstes tun solltet.\n\nSeid vorsichtig damit... ich spüre eine große Macht darin, zum Guten wie auch zum Bösen. Ich hoffe nur, dass Raene und Ihr wisst, was Ihr tut.\n\nViel Glück, {name}.", sourceObjective = "Liefert Dartols Rute bei Raene Wolfsläufer in Astranaar im Eschental ab.", progress = "Ja, {name}? Wie liefen Eure Bemühungen?", completion = "Ihr habt die Rute wieder zusammengesetzt, die Teronis finden wollte? Wie schön, das zu hören.\n\nShael'dryns Hilfe war unentbehrlich. Teronis wäre stolz gewesen, wenn er gesehen hätte, dass seine Aufgabe selbst nach seinem tragischen Ende noch fortgeführt wurde.\n\n<Raene betrachtet die wiederhergestellte Rute mit Anerkennung und in ihren Augen spiegeln sich die vielen Gedanken, die in ihr vorgehen.>\n\nDie Zeit ist gekommen, ihre Macht gegen die Feinde des Eschentals einzusetzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26480] = { id = 26480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dartols Rute", description = "Leider bin ich mir nicht ganz sicher, was er als Nächstes vorhatte.\n\nWenn es wahr ist, was er über die Macht der Rute sagte, könnt Ihr mit ihrer Hilfe eine völlig andere Gestalt annehmen, vermutlich die eines Furbolgs.\n\nVielleicht wollte er ihre Kräfte nutzen, um näher an die besudelten Furbolgs heranzukommen, aber selbst die nicht verderbten Kreaturen hätten ihn getötet, wäre er nicht vorsichtig gewesen. Durch die Rute verwandelt, hätte Dartol wahrscheinlich mit einem Furbolg gesprochen, der noch unverderbt war.\n\nIch würde meine Suche bei dem Furbolg beginnen, der als Krolg bekannt ist. Sucht nach seiner Hütte südöstlich vom Mystralsee.", sourceObjective = "Benutzt Dartols Rute, um mit Krolg bei Krolgs Hütte im Eschental kommunizieren zu können.\n\nBereitgestellter Gegenstand:", completion = "Ja, ja... du erscheinst als einer meiner Art, aber mich kümmert nicht, was du in Wirklichkeit bist, solange du den Furbolgs helfen kannst.\n\nDie Nachtelfen und jetzt auch die Orcs haben meinem Volk viele Gräuel angetan.\n\nVerderbnis fließt durch unsere Adern, Verderbnis, die von den überheblichen Nachtelfen und den kriegerischen Orcs über uns gebracht wurde. Sie sind diejenigen, die das unserem Volk angetan haben... Sie sind diejenigen, denen ich die Schuld dafür gebe, dass mein Stamm mich verstoßen hat.\n\nBei Nacht kann ich noch immer die Lagerfeuer in der Dunkelheit brennen sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26481] = { id = 26481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Verzierung", description = "Ich bin mir sicher, dass der seit langem tote Zauberer Dartol diese Rute dazu benutzen wollte, uns zu unterwerfen und zu zerstören, genauso wie es die Nachtelfen und Orcs versucht haben. Jetzt aber werden wir dieses Ding einem unvorhergesehenen Zweck zuführen.\n\nRan Blutreißer ist König über alle Furbolgs im Eschental. Sein Stamm, die Blutreißer, sind am mächtigsten und grenzen sich in einem Lager im Osten ab.\n\nTötet sie alle und bringt mir seinen Schädel. Wollen wir doch einmal sehen, ob wir nicht einen guten Verwendungszweck dafür finden können.", sourceObjective = "Erhaltet Ran Blutreißers Schädel und Dartols Rute.", progress = "Habt Ihr Ran schon erschlagen, Freund? Wir müssen seinen Schädel haben, wenn mein Volk frei sein soll.", completion = "Das habt Ihr gut gemacht, mein Freund.\n\nSchnell jetzt, gebt mir Rans Schädel. Solange noch seine Essenz ihn besudelt, können wir ihn an Dartols Rute befestigen und Euch die Macht verleihen, meine Brüder zu beeinflussen und sie vom Bösen zu befreien!", sourceObjectiveStatus = "unverified-source-field" }
quests[26482] = { id = 26482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wahre Macht der Rute", description = "Nehmt jetzt die Rute und sprecht, während Ihr unter ihrem Effekt steht, mit meinem Bruder Ota Wen.\n\nOta ist bei den anderen Furbolgs, die von den Orcs gefangen genommen und in den riesigen Käfig nördlich der Silberwindzuflucht gesperrt worden sind. Die Rute wird es Euch erlauben, Ota und die anderen Furbolgs dazu zu bringen, sich gegen die Horde aufzulehnen.\n\nDanach dürft Ihr Eures Weges ziehen. Wisst nur, dass Ihr mit Euren Taten einen neuen Freund gefunden habt.", sourceObjective = "Benutzt Dartols Rute und sprecht mit Ota Wen. Überzeugt ihn, sich gegen die Unterdrücker der Horde aufzulehnen. Bringt dann Dartols Rute zu Raene Wolfsläufer.", progress = "Ihr seid zurück, {name}. Was ist das dort an der Spitze der Rute? Ein Schädel?", completion = "Ihr habt also den Schädel des Furbolgkönigs benutzt, um die Macht der Rute zu verändern? Ihr habt dann diese Macht benutzt, um die gefangenen Furbolgs zur Revolte zu bewegen und die Horde in der Silberwindzuflucht anzugreifen?\n\nIch bin mit Euren Fähigkeiten mehr als zufrieden und beeindruckt, {name}. Die Schildwachen können Euch nicht genug danken. Es sollte nun einfach sein, die Orcs hinwegzufegen und die Zuflucht zurückzuerobern!\n\nTeronis wäre stolz. Ihr habt meinen größten Respekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26483] = { id = 26483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gan'dranda", description = "So viel Spaß es ja auch macht, die Trolle auf die Hörner zu nehmen, wir haben hier unten noch anders zu tun. Es wäre doch schöner, diesen Kampf endlich zu beenden, nicht wahr?\n\nIhr Kommandant, Gan'dranda, sitzt zwischen den eingestürzten Mauern im Südosten des Schlachtfelds. Unsere Jungs sind zum größten Teil unabkömmlich, also möchte ich, dass Ihr Euch dort hinschleicht und Gan'dranda beseitigt. Wenn sie dort sehen, wie <ein/eine:r> {race} über der Leiche ihres größten Helden steht, sollte ihnen das den Schneid abkaufen.", sourceObjective = "Tötet Gan'dranda.", completion = "Na, das höre ich doch gerne! So ist's recht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26484] = { id = 26484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Steinruh", description = "Die Irdenen und die Steintroggs haben vor mehr als fünfzehntausend Jahren einen Weg durch Uldum nach Tiefenheim gefunden. Seitdem befinden sie sich im Krieg.\n\nWenn wir das mittlere Fragment der Weltensäule wiedererlangen wollen, muss der Steinvater gerettet werden.\n\nBitte geht nach Steinruh und tut alles, was in Eurer Macht steht, um den Irdenen im Kampf gegen die Steintroggs zu helfen.\n\nIhr seid unsere größte Hoffnung, {name}.", sourceObjective = "Sprecht mit Spalt Steinbrecher in Steinruh in Tiefenheim.", completion = "Der Sohn des Steinvaters, Flint, hat Euch geschickt? Keine Zeit zu reden.\n\nWir müssen verhindern, dass sich eine zweite Front in dieser Schlacht aufbaut!", sourceObjectiveStatus = "unverified-source-field" }
quests[26485] = { id = 26485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnappkiefer, Bursche!", description = "Ich habe mir vorgenommen, für diese lästigen Trolle etwas ganz Besonderes zusammenzubrauen. Ja, ich sagte für sie... ein Gebräu, das sie niemals vergessen werden! Nach dem Genuss dieses Gebräus werden sie ihre Hauer aus den Abhängen sammeln können.\n\nEinige Zutaten weiche ich hier bereits ein, aber ich könnte Hilfe dabei gebrauchen, noch mehr zu beschaffen. Am Fuße der Aussichtsklippen im Osten in der Nähe des Ufers sind eine ganze Menge Schnappkiefer. Ich brauche frische, intakte Muskelmägen für mein Kawummbräu.", sourceObjective = "Beschafft 8 Schnappkiefermuskelmägen von Salzwasserschnappkiefern", progress = "Habt Ihr die Mägen?", completion = "Ah, schön frisch. Ich werde damit anfangen, während Ihr mir noch ein paar Sachen besorgt...", sourceObjectiveStatus = "unverified-source-field" }
quests[26486] = { id = 26486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "99 Flaschen Wein am Strand", description = "Ich weiß ja, dass hier ein kleiner Kampf tobt, aber unten an diesen Aussichtsklippen sind überall Flaschen verteilt, die sehr verführerisch aussehen. Ich kann nicht zulassen, dass so ein gutes Tröpfchen der Horde in die Finger fällt!\n\nWenn Ihr zufällig dort vorbeikommt, dann sammelt die Flaschen für mich ein und bringt sie her. Ich werde Euch dafür bezahlen, als hättet Ihr sie selbst abgefüllt.", sourceObjective = "Sammelt 12 Flaschen mit Pupellyverbos' Portwein.", progress = "12 sollten reichen, oder?", completion = "Was für ein gutes Zeug! Wir können doch nicht zulassen, dass irgendwelche Trolle oder Goblins sich ein Schlückchen davon genehmigen, oder?\n\nVielleicht kann ich ein bisschen davon in meinem nächsten Gebräu verarbeiten…", sourceObjectiveStatus = "unverified-source-field" }
quests[26487] = { id = 26487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bündelweise Akiris", description = "Es ist nicht einfach, eine Kombination aus 5-Sterne-Exotikhotel und Verwertungsanlage für Dschungelmaterial zu führen! Zumindest wäre es nicht einfach, wenn ich nicht das Organisationstalent der persönlichen Assistentin eines Handelsprinzen hätte!\n\nDer erste Trick ist, mehrere Dinge auf einmal zu erledigen. Zum Beispiel: Die Forscher der Naga im Süden tragen wertvolles Seeschilf bei sich, Akiris. Wir können dieses Schilf an unsere Kunden in Übersee verkaufen und gleichzeitig die Matratzen unserer Kunden damit polstern! Wenn ich so darüber nachdenke, könnten wir es sicher auch für andere Zwecke verwenden.", sourceObjective = "Beschafft 6 Bündel Akirisschilfrohr von den Forschern der Naga.", progress = "Mal sehen… Wir brauchen ein paar Gewehre für unsere Naturwanderungen, Ruderboote für unseren Tagesausflug zum Bohrturm und…\n\nOh, Ihr seid schon zurück?", completion = "He, he! Nicht übel, gar nicht übel! Ihr könntet eine Zukunft im Beschaffungswesen haben. Oder im Hotelmanagement.", sourceObjectiveStatus = "unverified-source-field" }
quests[26488] = { id = 26488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein großer Schluck", description = "Arnold und ich haben uns immer am Burggraben im Tal der Helden ausgeruht. Eines Tages habe ich mein Medaillon am See verloren und habe es nie wiedergefunden. Es gibt Gerüchte, dass riesige königliche Seeteufel in dem Burggraben leben. Diese Fische fressen einfach alles! Ich weiß, es hat nicht besonders viel Aussicht auf Erfolg, aber glaubt Ihr, Ihr könntet ein paar Seeteufel fangen und nach meinem Medaillon schauen?\n\nBitte gebt mir umgehend Bescheid, wenn Ihr es findet. Es bedeutet mir sehr viel.", sourceObjective = "Fischt einen königlichen Seeteufel aus dem Burggraben im Tal der Helden in Sturmwind. Wenn Ihr einen Seeteufel angelt, filetiert ihn und seht nach, ob er das Medaillon verschluckt hat.", progress = "Habt Ihr mein Medaillon gefunden?", completion = "Ihr habt es gefunden! Ich kann kaum glauben, dass es all die Jahre dort unten war! Ihr habt keine Ahnung, wie viel mir das bedeutet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26489] = { id = 26489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr hier?!", description = "Ja, wie kann ich Euch…\n\n<Sassy fällt die Kinnlade herunter.>\n\n{name}! Seid Ihr das wirklich?! Wie groß und stark Ihr geworden seid! Lasst mich mal Euren Bizeps fühlen.\n\nIch? Ich habe versucht, hier im Dschungel ein wenig Gold zu scheffeln. Wir sind hauptsächlich in der Materialbeschaffung tätig, aber auch im Tourismus.\n\nIch weiß, genial, oder?\n\nHe, hört mal. Da fällt mir gerade was ein. Die Forscher der Naga im Süden tragen wertvolles Akirisschilf bei sich, das wir verkaufen und gleichzeitig als Polsterung für unsere Gästematratzen verwenden können. Habt Ihr Lust, ein paar Naga zu töten? Es wäre ganz wie in alten Zeiten!", sourceObjective = "Beschafft 6 Bündel Akirisschilfrohr von den Forschern der Naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[26490] = { id = 26490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstklassiger Schleim", description = "Nicht viele Zwerge wissen das, aber um meinem Gebräu noch einen richtigen Schub zu verleihen, füge ich noch ein wenig von dem Schlamm hier aus der Gegend hinzu. Ja, von den riesigen, grünen, zwergenfressenden Schlammhaufen.\n\nDieses Gebräu braucht allerdings einen RIESIGEN Extraschub, also brauchen wir einen großen Schlamm! Im Lauerfels befindet sich die Mutter aller Schlamme, sie ist wirklich riesig... Wir nennen sie den Terrorhaufen.\n\nWenn Ihr das Zeug dazu habt, geht dorthin und bringt mir einen Brocken von dem Terrorklumpen!", sourceObjective = "Beschafft eine Terrorklumpenprobe vom Terrorklumpen.", progress = "Habt Ihr es?", completion = "Schaut Euch das an! Das wird der Mixtur richtig Dampf verleihen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26491] = { id = 26491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Lauerfels aufräumen", description = "Vor Jahren gab es einmal eine Basis der Horde tief im Lauerfels. Sie ist seitdem verlassen, aber es handelt sich immer noch um ein wichtiges Gebiet, das es wert wäre, für unsere Verbündeten eingenommen zu werden.\n\nDas Problem ist, es ist voller zwergenfressender Schleime und Schlamme. Diese Dinger sind fast genauso eklig wie Trolle und bereiten uns dauernd Ärger.\n\nUnsere Jungs sind vollauf damit beschäftigt, gegen die Bruchhauer zu kämpfen, deshalb müsst Ihr nach Lauerfels gehen und dort für mich aufräumen.", sourceObjective = "Tötet 10 jadegrüne Schlamme.", completion = "Es ist schön, Euch wieder hier zu sehen... einschließlich aller Arme und Beine.", sourceObjectiveStatus = "unverified-source-field" }
quests[26492] = { id = 26492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauerfelsvorräte", description = "Ich hatte einen Cousin, der im Zweiten Krieg gekämpft hat! Er hat mir immer davon erzählt, dass sie einen Schlachtzug gegen Lauerfels geführt haben. Sie sind dort hineingestürmt und haben die Trolle wie Ratten aus ihrem Nest vertrieben. Sie haben sie den ganzen Weg bis nach Alterac gejagt!\n\nKurz darauf haben die Schleime Einzug gehalten, aber dort drin gibt es immer noch ganze Kisten voller Waren der Horde. Ich sage, wir lassen nicht zu, dass die Trolle sich das zurückholen!\n\nBringt mir einige Kisten vom Lauerfels im Nordwesten.", sourceObjective = "Sammelt 5 schlammbedeckte Vorratskisten ein.", progress = "Habt Ihr die Kisten?", completion = "Es sieht so aus, als ob darin noch alles gut ist! Hm... Ist das Bananenbrot? Das ist sogar noch frisch!\n\nHier mein Junge, nehmt Euch Euren Anteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[26493] = { id = 26493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jemand dort draußen will es haben", description = "Also, da Ihr ohnehin schon von der Erledigung der ganzen anderen Sachen schwitzt, dachte ich, Ihr könntet noch eine Aufgabe für mich erledigen. Das macht Euch doch nichts aus, oder?\n\nDas neueste Wissenschafts- und Explosionsjournal ist gerade aus Bilgewasserhafen eingetroffen und darin ist dieser Artikel über dieses heiße, neue Reagenz. Die Preise für dieses Reagenz schießen in den Himmel und wir haben beste Voraussetzungen, daraus Kapital zu schlagen!\n\n<Sassy beugt sich zu Euch und flüstert Euch die Einzelheiten ins Ohr.>\n\nVerstanden? Gut. Ihr findet die Basilisken in einer Höhle, weit im Osten.", sourceObjective = "Beschafft 7 Einheiten von Sassys Geheimzutat von Donnerschwanz- und Eisenkieferbasilisken in der Kristalladermine.", progress = "Ich hoffe, Ihr habt die Extraktionsmethode, die wir besprochen haben, angewendet.", completion = "Großartig! Die sehen... widerlich aus. Sie sind aber wahrscheinlich ziemlich wertvoll. Gehen wir und teilen sie auf. Ein paar für mich, ein paar für Jasper, ein paar für Chabal...", sourceObjectiveStatus = "unverified-source-field" }
quests[26494] = { id = 26494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mischmeister Jasper", description = "Würde es Euch etwas ausmachen, ein bisschen von dem Zeug hier Jasper zu bringen? Er ist bei den luxuriösen Wohnungen. Ich bin sicher, er wird dafür Verwendung haben.\n\nDanke, {name}!", sourceObjective = "Bringt Sassys Proben zu Mischmeister Jasper in Hartzangs Versteck.", progress = "Hey, ist das das Zeug? Aus der Zeitschrift?", completion = "Ich werde das erst einmal aufbewahren. Vielleicht können wir später herumexperimentieren.\n\n<Jasper schaut zu Euch hinüber.>\n\nJa, Ihr werdet reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26495] = { id = 26495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chabal", description = "Chabal, der Troll drüben am botanischen Garten/biologischen Waffenlabor, ist ein ganz besonderer Gast. Er ist ein Repräsentant der Zandalari-Trolle und hat eine weite Reise hinter sich, um bei uns zu sein.\n\n<Sassy packt einige der Gegenstände, die Ihr gesammelt habt, in ein kleines Paket und übergibt es Euch.>\n\nHier, gebt ihm das. Sagt ihm, dass die Zandalari in Hartzangs Versteck immer willkommen sind. Und erwähnt, dass Empfehlungen der Schlüssel zur Aufrechterhaltung unserer Geschäftsbeziehungen sind!", sourceObjective = "Bringt Sassys großzügige Gabe zu Chabal in Hartzangs Versteck.", progress = "Was soll das, {class}?", completion = "<Der Troll schaut in das Paket.>\n\nIch danke Euch.\n\nIch habe darauf gewartet, dass Ihr mich ansprecht, {race}. Ich habe festgestellt, dass Ihr der vielversprechendste {race} in dieser merkwürdigen Stadt seid. Ich habe eine Aufgabe für Euch, falls Ihr sie annehmen möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26496] = { id = 26496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit den Blutfratzen", description = "Die Bruchhauer sind nicht der einzige Stamm schändlicher Trolle, um die wir uns kümmern müssen! Die Blutfratzen haben dieses Land seit Jahren aus ihrer Festung Jintha'Alor heraus verdorben.\n\nWir sitzen nicht länger am Nistgipfel und drehen Däumchen, falls es Euch entgangen sein sollte. Doran Stahlschwing führt den Sturmangriff gegen die Blutfratzen von einem Lager im Süden, das die Jungs gerade eingenommen haben. Sprecht mit ihm und schließt Euch dem Kampf an!", sourceObjective = "Findet Doran Stahlschwing bei Jintha'Alor im Hinterland.", completion = "Seid gegrüßt, {name}! Wir müssen viele Trolle töten und haben mehr als alle Hände voll damit zun!", sourceObjectiveStatus = "unverified-source-field" }
quests[26497] = { id = 26497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutfratzenabschaum", description = "Die Blutfratzen sind ein anderer Stamm als die Bruchhauer, aber die Unterschiede sind kaum wahrnehmbar. Soweit es uns betrifft ist nur ein toter Troll eine guter Troll!\n\nAber täuscht Euch nicht, die Blutfratzen sind auch ohne die Ketten der Horde um ihre Hälse ausgesprochen bösartig. Sie werden das ganze Land vergiften, wenn wir uns nicht erheben und sie loswerden.\n\nIhr könnt mit ihren Hexendoktoren und Kopfjägern auf der unteren Etage beginnen. Sagt mir Bescheid, wenn Ihr eine ansehnliche Zahl von ihnen vernichtet habt.", sourceObjective = "Tötet 5 Hexendoktoren der Blutfratzen und 5 Kopfjäger der Blutfratzen in Jintha'Alor.", completion = "Ja, wir werden diese Trolle noch loswerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26498] = { id = 26498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Blutfratzen", description = "Wir machen gute Fortschritte. Rückt weiter vor und lasst nicht nach!\n\nDie Berserker der Blutfratzen kämpfen wie wilde Tiere und peitschen sich in einen wahren Blutrausch. Ihre Schattenzauberer rufen widerwärtige Geister aus dem Jenseits herbei. Das ist der Grund, warum wir uns dieser verdorbenen Kreaturen entledigen, {name}, vergesst das nicht.\n\nBegebt Euch auf die mittlere Stufe und tötet Berserker und Schattenzauberer!", sourceObjective = "Tötet 5 Berserker der Blutfratzen und 5 Schattenzauberer der Blutfratzen in Jintha'Alor.", completion = "Es wird nicht lange dauern, bis wir die einzigen Zwerge sind, die auf diesen Mauern noch atmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26499] = { id = 26499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen des Steinvaters", description = "Solange der Steinvater gefangen gehalten wird, ist die Moral meiner Truppen am Boden. Normalerweise nimmt es jeder von meinen Leuten mit mindestens fünf Steintroggs auf einmal auf. Aber jetzt…\n\nGeht hinaus auf das Feld um das Dorf herum. Stellt Steinvater Erzmantels Banner in der Nähe meiner Verteidiger auf. Schenkt ihnen seinen Segen und erinnert sie daran, wofür sie kämpfen.", sourceObjective = "Gewährt 12 Irdenen Verteidigern den Segen des Steinvaters", completion = "Ihr habt meinen Dank, {name}. Ihr habt das Blatt komplett gewendet. Das Schicksal dieser feigen Steintroggs ist besiegelt.\n\nJetzt müssen wir uns daran machen, Steinruh zurückzuerobern.", sourceObjectiveStatus = "unverified-source-field" }
quests[26500] = { id = 26500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sind umzingelt", description = "Unser Krieg tobte schon, bevor die Zeitrechnung Eures Volkes begann. Mal sehen, ob Ihr etwas verändern könnt, {race}.\n\nDie Steintroggs sind ein Fehler der Titanen. Auf Eurer Welt sind sie dem Fluch des Fleisches erlegen. Doch hier in Tiefenheim seht Ihr sie in ihrer wahren Gestalt.\n\nWir sind hier umzingelt. Warum geht Ihr nicht hinaus und zertrümmert ein paar Troggs für uns? Seht Euch an, was in ihnen steckt.", sourceObjective = "Tötet 12 Wegelagerer der Steintroggs.", completion = "Kein schlechter Anfang, aber Ihr werdet noch mehr töten müssen, wenn Ihr den Steinvater retten wollt.\n\nViel mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[26501] = { id = 26501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versiegelung des Eingangs", description = "Den Steintroggs ist es gelungen, sich unter unseren Häusern nach oben zu graben!\n\nIch habe Geomanten ausgesandt, die alle Gebäude versiegeln sollen. Sie benötigen jedoch Reagenzien und genügend Zeit außerhalb des Kampfes, um ihre Felssturzrituale zu vollenden.\n\nMeldet Euch bei General Kies Langfels, wenn Ihr fertig seid. Ihr findet ihn gen Norden an der Zerrissenen Front.", sourceObjective = "Helft den Irdenen Geomanten, sich aus dem Kampfgeschehen auszuklinken und gebt ihnen dann die Felssturzreagenzien, damit sie das Rüstlager, das Gasthaus, die Baracken und den Schrein versiegeln können.", completion = "Das ist gut. Nun müssen wir uns keine Sorgen mehr über einen Angriff der Steintroggs aus dem Hinterhalt machen.\n\nMal sehen, wie Ihr uns an der Front von Nutzen sein könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26502] = { id = 26502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnersteine", description = "Die Zerrissene Front liegt im Norden. Dort finden die schwersten Gefechte statt.\n\nBegebt Euch ins eigentliche Steinruh und besorgt so viele Donnersteine, wie Ihr könnt. Unsere Ingenieure benötigen sie für die Katapulte.\n\nBringt sie zu Klei Lehmachse, wenn Ihr genug gefunden habt. Stört Euch nicht an seinem Ton. Er ist alt und griesgrämig und hätte schon vor Tausenden von Jahren in die Erde zurückkehren sollen.", sourceObjective = "Besorgt 12 Donnersteine.", progress = "<Der ältere Irdene hat mehr Risse als alle anderen. Er ist offensichtlich uralt.>\n\nWas stellt Ihr denn dar? Eine Art fleischiger Fehler? Verflucht, das seid Ihr!\n\n<Klei spuckt Staub auf den Boden.>Macht Euch nützlich oder haut ab von meiner Front.", completion = "<Klei grummelt in sich hinein.>\n\nJa, die passen. Legt sie da hinten hin.\n\n<Der Irdene mustert Euch mit einem Auge und spuckt Staub auf den Boden.>\n\nIch werde gleich etwas für Euch zu tun haben. Vielleicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26503] = { id = 26503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Einschätzung der Gefahr", description = "Diese verdammten, wertlosen Gnolle führen nichts Gutes im Schilde. Ich spüre es in meinen Knochen. Die Gnollaktivität hat sich in den letzten zwei Wochen verdreifacht. Ich befürchte, dass sie einen Angriff auf Seenhain vorbereiten.\n\nIch möchte, dass Ihr die Lager der Gnolle in dieser Gegend aufsucht und dort alle Informationen sammelt, die Ihr finden könnt. Durchsucht die Lager unmittelbar nördlich von hier, östlich von hier und südöstlich von hier. Bringt mit, was Ihr dort findet.", sourceObjective = "Stehlt die Schlachtpläne der Gnolle, die Befehle der Gnolle und den Strategieführer der Gnolle.", progress = "Habt Ihr die Pläne der Gnolle gefunden?", completion = "Ich wusste es! Anscheinend steckt Jauler hinter dem Aufstand - was unglaublich ist, da wir ständig Gnolle namens Jauler umbringen. Ich weiß nicht, wie viele Söhne der ursprüngliche Jauler hatte, aber es müssen an die hundert sein.\n\nSieht jedenfalls so aus, als hätten wir noch einen Jauler zu töten.\n\nMagistrat Solomon muss davon erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26504] = { id = 26504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Rotkammgnolle", description = "Auf Befehl der Königswache von Sturmwind sollen alle Gnolle in dem Drei Ecken genannten Gebiet in der südwestlichen Ecke des Rotkammgebirges getötet werden.\n\nWenn Ihr die Gnolle in dieser Gegend beseitigt habt, dann meldet Euren Sieg Wachhauptmann Parker an der Turmwacht.", sourceObjective = "Tötet 15 beliebige Rotkammgnolle in der Drei Ecken genannten Gegend des Rotkammgebirges.", completion = "Wer gute Arbeit leistet, verdient eine Belohnung, oder?\n\nGebt nicht alles an einem Ort aus, {class}. Verteilt es ordentlich, wenn Ihr versteht, was ich meine.", sourceObjectiveStatus = "unverified-source-field" }
quests[26505] = { id = 26505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parkers Bericht", description = "<Wachhauptmann Parker händigt Euch einen Bericht aus.>\n\nHier ist er, {name}. Bringt meinen Bericht nach Seenhain nördlich dieses Turms und übergebt ihn Magistrat Solomon. Erklärt ihm, dass wir eine umfassendere Lösung für den Umgang mit den Gnollen benötigen. Schlagt Sprengstoff vor. Viel Sprengstoff.\n\nUnd bleibt auf der Straße, wenn Ihr wisst, was gut für Euch ist. Zu überleben ist gut für Euch, nebenbei bemerkt. Falls Ihr Euch gefragt hattet, was gut für Euch ist. Jetzt wisst Ihr es... Ach, vergesst es!", sourceObjective = "Bringt Parkers Bericht zu Magistrat Solomon nach Seenhain im Rotkammgebirge.", progress = "Wo habe ich mein Monokel nur hingelegt?! Conacher, seid Ihr das?", completion = "<Magistrat Solomon setzt sein Monokel auf.>\n\nOh, Ihr seid nicht Conacher. Was habt Ihr denn da?\n\n<Ihr gebt Magistrat Solomon Parkers Bericht.>\n\nDas kann doch nicht wahr sein. Jauler? SCHON WIEDER?", sourceObjectiveStatus = "unverified-source-field" }
quests[26506] = { id = 26506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Würstchen mit Bohnen", description = "Ich brauche Eure Hilfe, {race}! Unsere Rationen sind verbraucht und die Wachen werden hungrig. Sie sehnen sich nach meinen weltberühmten Würstchen mit Bohnen, aber mir fehlen die Zutaten. Seid ein Schatz und helft mir, bitte.\n\nIch brauche ein paar Greiferzahnnieren, Kondorinnereien und TarantelaugenI. Ihr findet Greiferzähne, Kondore und Taranteln nahe dieses Turms. Seht Euch nur um!", sourceObjective = "Besorgt 4 Tarantelaugen, 4 Kondorinnereien und 4 Greiferzahnnieren.", progress = "Habt Ihr meine Zutaten bekommen?", completion = "PERFEKT! Die kommen sofort in den Topf. Das Abendessen sollte in ein paar Stunden fertig sein.\n\nDanke, Herzchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26507] = { id = 26507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versteinerte Delikatessen", description = "Versteinerte Fledermäuse.\n\nElementare dieser Größe sind wählerisch. So leicht werdet Ihr nichts Besseres finden.\n\nIm Osten gibt es Basilisken. Sie lassen Steinfledermäuse zu Stein werden, die ihnen zu nahe kommen und essen sie als Zwischenmahlzeit. Ihr solltet Fledermäuse in ihrem Territorium finden.\n\nIch muss Euch jedoch warnen... wenn Ihr diesem kleinen Elementar zu viel Aufmerksamkeit schenkt, werdet Ihr ihn möglicherweise nie wieder los. Er kann sehr aufmerksamkeitsbedürftig sein.", sourceObjective = "Besorgt 12 erstarrte Steinfledermäuse für Kieselchen.", progress = "<Kieselchen sieht zu Euch auf. Seine Augen beginnen schwach zu leuchten, werden mit jeder Sekunde größer und größer.>", completion = "<Kieselchen springt auf den Haufen versteinerter Fledermäuse und wälzt sich darin, so als habe er vergessen, dass es Euch überhaupt gibt. Es wäre vielleicht das Beste, Kors Warnungen Glauben zu schenken.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26508] = { id = 26508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nidas Halskette", description = "Meine Freundin Nida hat ihre Halskette verloren. Wir finden sie nicht mehr. Wir haben den ganzen Tag hier geangelt und auch schon die Umgebung abgesucht. Ich befürchte, dass sie in den See gefallen ist. Unsere Eltern wollen nicht, dass wir im See schwimmen gehen... meine Mama sagt, Unterwasser gäbe es fiese Wesen, aber Ihr seht nicht aus, als ob Ihr Angst vor fiesen Wesen hättet.\n\nKönntet Ihr die Kette für Nida finden, bitte?", sourceObjective = "Findet Nidas Halskette.", progress = "Hallo. Ich habe meine Halskette verloren. Mein Papa hat sie mir geschenkt. Papa sagt, dass es Ungeheuer im See gibt. Habt Ihr Ungeheuer verprügelt?", completion = "Danke, dass Ihr meine Halskette gefunden habt, ehrenwerter {class}... Ihr seid sehr nett! Mein Kätzchen dankt Euch auch – nicht wahr, Effsee?", sourceObjectiveStatus = "unverified-source-field" }
quests[26509] = { id = 26509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ungebetener Gast", description = "Schon wieder wurde mein Garten zertrampelt und geplündert. Und ich weiß, welche Bestie das getan hat. Es ist dieser verdammte Eber, den Marschall Marris Stopfwanst nennt.\n\nDie Narzissen kann ich erst wieder zur nächsten Saatzeit pflanzen. Zerstört! Dieser bösartige Eber hat alles zerstört. Erledigt diesen Schädling! Zeigt mir seinen Hauer, dann werde ich Euch gern belohnen. Meistens sucht er auf dem Feld südwestlich von Seenhain nach Futter, aber manchmal verschlägt es ihn hierher in meinen Garten.", sourceObjective = "Tötet Stopfwanst und nehmt Stopfwansts Hauer an Euch.", progress = "Ist Stopfwanst noch da draußen oder habt Ihr Seenhain endgültig von diesem Schädling befreit?", completion = "Endlich ist diese Landplage vorbei! Danke, {name}, Ihr habt mir einen großen Dienst erwiesen. Der Garten wird zur Erntezeit in voller Blüte stehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26510] = { id = 26510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir müssen uns vorbereiten!", description = "Jeden Tag verschwinden weitere Bürger. Wir glauben, dass die Gnolle dafür verantwortlich sind, aber wir wissen nicht, wo sie unsere Bürger hinbringen! Wenn Ihr uns helfen wollt, die Gnolle zu besiegen und unsere Bürger zu finden, müsst Ihr ordentlich ausgerüstet sein. Leider haben wir keine Gnomcorder mehr. Ohne einen Gnomcorder können wir während Eures Einsatzes nicht mit Euch kommunizieren.\n\nUnseren letzten funktionstüchtigen Gnomcorder haben die Murlocs letzte Woche bei einem Überfall gestohlen. Begebt Euch östlich von hier zum Immerruhsee und bringt ihn an Euch!", sourceObjective = "Findet den Gnomcorder.", progress = "Habt Ihr den Gnomcorder gefunden?", completion = "Hervorragend! Ich ändere noch ein paar Einstellungen, dann können wir beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26511] = { id = 26511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung des Immerruhsees", description = "Auf dem Weg zum Immerruhsee? Es wird Euch sicher freuen, dass wir gerade eine Belohnung auf Murlocs ausgesetzt haben. Tötet so viele Ihr könnt, dann wird man Euch belohnen. Es ist egal, welche Murlocs. Tötet sie einfach wahllos.\n\nDer Immerruhsee liegt genau östlich von Seenhain. Es ist der See. Ist Wasser drin... Kommt Euch das bekannt vor?", sourceObjective = "Tötet 10 beliebige Murlocs im Immerruhsee.", completion = "Ihr habt den Murlocs eine Lektion erteilt. Hoffentlich überlegen sie es sich demnächst zweimal, ob sie unsere Stadt überfallen wollen.\n\nNein, ich glaube auch nicht daran.", sourceObjectiveStatus = "unverified-source-field" }
quests[26512] = { id = 26512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einstellung des Gnomcorders", description = "Der Gnomcorder scheint zu funktionieren. Ich habe ihn Euch angelegt, aber wir müssen noch die Empfangsfrequenz einstellen.\n\nVerlasst Seenhain in Richtung Norden und folgt der Straße bis zum Friedhof. Wenn Ihr am Friedhof angekommen seid, versuche ich zu senden.", sourceObjective = "Geht zum Friedhof von Seenhain, um die Frequenz des Gnomcorders einzustellen.", completion = "<Der Gnomcorder knistert und kracht.>\n\nKönnt Ihr mich hören, {name}? Ist das Ding an? Ah ja, ich sehe Euch jetzt dort.\n\nWir können anfangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26513] = { id = 26513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie ein Furz im Wind", description = "Wir wurden letzte Nacht überfallen oder war es die Nacht davor? Ich weiß es nicht mehr genau. Seit drei Tagen kriege ich kein Auge zu. Wahrscheinlich verliere ich schon den Verstand.\n\nGnolle haben unsere Vorratslager geplündert. Alles haben sie mitgenommen! Rein und raus, lautlos wie ein Furz im Wind! Meine Soldaten sahen sie zu den Schluchten nordwestlich von hier laufen. Bringt unsere Vorräte zurück, {class}!", sourceObjective = "Bergt 8 Vorratskisten des Rotkammgebirges.", progress = "Habt Ihr die Vorräte geborgen?", completion = "Danke, Bürger. Ohne Euch wären wir verhungert oder schlimmer noch, hätten dort draußen selbst nach Nahrung suchen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26514] = { id = 26514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schluchtenspringen", description = "<Der Gnomcorder summt.>\n\nAls erstes steht ein flotter Marsch durch die Rotkammschlucht direkt im Norden von Seenhain an. Tötet jeden Gnom, den Ihr seht... huch, habe ich Gnom gesagt? Ich meinte Gnoll. Tötet jeden GNOLL, den Ihr seht und nehmt ihnen zum Beweis Eurer Tat das Halsband ab.\n\nEine Warnung, {name}; hütet Euch dort draußen vor den Ettins. Meine Kundschafter haben in letzter Zeit riesige blutdürstige Ettins in den Schluchten gesehen. Geht ihnen aus dem Weg, wenn Ihr weiterleben wollt.\n\nSolomon Ende. Ich melde mich.", sourceObjective = "Sammelt 10 Halsbänder der Rotkammgnolle.", progress = "Habt Ihr die Halsbänder bekommen?", completion = "<Der Gnomcorder knistert und kracht.>\n\nGute Arbeit, {name}. Ich habe gerade wichtige Informationen erhalten. Anscheinend sind unsere verhasstesten Feinde, die Schwarzfelsorcs, schlauer geworden...\n\n\n\nIch habe Euch ein paar Silbermünzen für die getöteten Gnome... äh, Gnolle übermittelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26515] = { id = 26515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ongo'longos Rache", description = "Ich hab vor, Troll auf Troll zu hetzen.\n\nDie Blutfratzen halten einen miesen, alten Terrortroll in einer Grube gefangen. Seine Ketten sehen nicht sehr stabil aus. Ich weiß, wie so ein Unhold kämpft. Sie werden ihn nicht halten können, wenn er richtig wütend wird und loslegt.\n\nFindet den Terrortroll und kämpft gegen ihn, {name}. Bringt ihn nicht um... schlagt nur ein wenig auf ihn ein, bis er rot sieht und ausbricht. Dann geht ihm aus dem Weg. Der wird den Blutfratzen ordentlich Beine machen.", sourceObjective = "Kämpft gegen Ongo'longo, bis er seine Ketten sprengt.", completion = "Was für ein Spaß! Ich wünschte, ich wäre dabei gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26516] = { id = 26516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gehört jetzt uns", description = "Nur die stärksten und bösartigsten Blutfratzen sind übrig geblieben. Die Seelenfresser und Bluttrinker, die verkommenen Anhänger des bösen Gottes Hakkar.\n\nDenkt daran, dass Ihr hier nicht nur gegen Trolle kämpft, {name}. Ihr kämpft gegen dunkle und böse Kräfte, die dieses Land zu Asche verbrennen werden, wenn wir sie leben lassen!\n\nZeigt keine Gnade!", sourceObjective = "Tötet 5 Bluttrinker der Blutfratzen und 5 Seelenfresser der Blutfratzen in Jintha'Alor.", completion = "Wir haben sie niedergemäht! Jintha'Alor ist so gut wie ausgelöscht!", sourceObjectiveStatus = "unverified-source-field" }
quests[26517] = { id = 26517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksalsgipfel", description = "Geht jetzt zum Gipfel, {name}. Unsere Krieger wagen sich nur bis zu den letzten Toren vor. Sie sagen, dort es sei still wie in einem Grab; kein Geräusch, kein Atemzug, nichts rührt sich.\n\nSie halten es für eine Falle, aber das, was Ihr mir gebracht habt, lässt mich befürchten, dass etwas weit Böseres dort lauert. Geht zum Altar, findet heraus, was geschehen ist... und bringt mir ALLE mystischen Gegenstände oder dunklen Götzen, die Ihr dort findet! Habt Ihr mich verstanden?", sourceObjective = "Sammelt 8 Spinnengötzen der Blutfratzen auf dem Gipfel von Jintha'Alor.", progress = "Was habt Ihr gefunden?", completion = "Tot? Alle in der Nähe des Altars? Und sie hatten diese Spinnengötzen bei sich...\n\nDas ist Shadra. Die Spinnenloa! Sie versuchen ihre Kraft abzuzapfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26518] = { id = 26518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfprämie", description = "Es gibt kaum einen größeren Troll als Umboda Dreikopf. Er ist ein grausamer Schlächter, der die Köpfe von Zwergen und Trollen sammelt! Wird langsam Zeit, dass er bekommt, was er verdient.\n\nFindet den großen Schläger auf den unteren Terrassen und kommt mit seinem Kopf zurück!", sourceObjective = "Besiegt Umboda Dreikopf und holt Euch seinen Kopf.", progress = "Lasst mal sehen!", completion = "Was für eine hässliche Fratze. Hat wohl gehofft, unter den anderen Köpfen einen hübscheren zu finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[26519] = { id = 26519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer die Ettins beherrscht", description = "Ihr seid über ein Dokument der Gnolle gestolpert. Der Gnoll, von dem diese Propaganda stammt, kann ein wenig schreiben:\n\nBRÜDER VON JAULER, HÖRT SCHMUTZPRANKE AN! ORCS GEBEN SCHMUTZPRANKE KUGEL! SCHMUTZPRANKE BEHERRSCHT ETTIN-VIECHER! SCHMUTZPRANKE ZERMALMT MENSCHIES! HOLT EUCH SCHMUTZPRANKES PRANK-O-GRAPH IN DEN RETHBANHÖHLEN. HÖHLE IM WESTEN, IN SCHLUCHT VERSTECKT!\n\n<Die Unterschrift besteht aus einem Prankenabdruck.>\n\n<Anscheinend hat jemand auch ein Stück aus der Schriftrolle gebissen.>\n\nIhr solltet dem vielleicht nachgehen.", sourceObjective = "Tötet Ardo Schmutzpranke.", progress = "<Mächtige Magie geht von der Kugel aus.>", completion = "<Die Kugel zischt, als Ihr sie berührt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26520] = { id = 26520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet Großknecht Oslow", description = "<Als Ihr die Kugel berührt, hört Ihr ein leises Klicken.>\n\n<Ihr nehmt die Kugel von ihrem Sockel.>\n\nNun kontrolliert Ihr die Kugel und damit auch die Ettins. Vielleicht könntet Ihr mit einem Ettin den riesigen Felsbrocken entfernen, unter dem Großknecht Oslow in Seenhain eingeklemmt ist. Findet einen Ettin und wendet die Kugel bei ihm an. Begebt Euch dann nach Seenhain.", sourceObjective = "Benutzt die Ettinsteuerungskugel, um einen Ettin zu unterwerfen. Setzt die Ettinsteuerungskugel dann bei Eurem gebändigten Schluchtettin ein und bringt ihn dazu, Großknecht Oslow in Seenhain von dem riesigen Felsbrocken zu befreien.", completion = "Ihr habt einen Ettin benutzt, um den Felsbrocken zu entfernen, unter dem Großknecht Oslow eingeklemmt war? Unglaubliche Leistung, {name}! Oslow wird Euch sehr dankbar sein, wenn er sich wieder gefangen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[26521] = { id = 26521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichter des Bösen", description = "Die Blutfratzen haben ihre Tikimasken überall in Jintha'Alor an die Mauern gehangen. Wir werden ihre widerlichen Zauber und ihre dunkle Magie nicht dulden.\n\nDiese Botschaft werden wir ihnen überbringen und gleichzeitig ihre Abwehr durchbrechen! Nehmt diese Fackel, {class}. Zündet ihre Tikimasken an und lasst sie brennen. Wenn ihre dunklen Idole zu Asche zerfallen, werden sie erkennen, dass sie den Wildhämmern nicht willkommen sind!", sourceObjective = "Zündet mit der Tikifackel 8 Tikimasken in Jintha'Alor an.", completion = "Die Elemente tanzen, das Feuer lodert. Durch die Flammen sollen sie den Preis ihrer Verruchtheit erkennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26523] = { id = 26523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles, was krabbelt", description = "Da oben hab ich noch was bemerkt... Jintha'Alor ist voller Spinnen. Kleine, nicht größer als Eure Hand. Nicht ungewöhnlich für das Hinterland, aber etwas daran ist seltsam.\n\nIch vertraue den Trollen nicht, wenn sie Haustiere halten. Sie haben was vor. Bringt mir ein paar dieser Spinnen. Haltet sie am Leben, wenn es geht, dann werden wir sehen, was mir die Geister zu erzählen haben...", sourceObjective = "Sammelt 8 huschende Spinnlinge in Jintha'Alor.", progress = "Zeigt mir, was Ihr habt.", completion = "Bei Kurdans Bart... solche Spinnen hab ich noch nie gesehen. Dahinter steckt dunkle Magie.", sourceObjectiveStatus = "unverified-source-field" }
quests[26524] = { id = 26524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Gefäße", description = "Die Blutfratzentrolle hier beten seit jeher den verderbten Gott Hakkar, Loa des Blutes, an. Er war ein krankes, pervertiertes Wesen. Vor langer Zeit wäre er beinahe in unsere Welt vorgedrungen, konnte jedoch besiegt werden.\n\nDie Blutfratzen rühren immer noch in ihren dunklen Kesseln, die sie vor Jahren mit Blut gefüllt haben. Entweder hoffen sie auf einen längst verstorbenen Geist oder sie haben einen neuen, ebenso düsteren Plan.\n\nBesorgt mir diese Gefäße, {name}. Wir müssen sie gemeinsam mit den Spinnen untersuchen, um zu verstehen, was hier vorgeht!", sourceObjective = "Besorgt 5 Gefäße mit besudeltem Blut aus Jintha'Alor.", progress = "Seid in der Nähe der Kessel vorsichtig, {class}. Die Blutfratzen werden sie nicht freiwillig hergeben!", completion = "Das ist nicht nur Blut... das ist Gift!\n\nSpinnen... Gift... Hoffentlich habe ich mit meiner Ahnung unrecht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26525] = { id = 26525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftige Geheimnisse", description = "Wenn das Opfer bereits vollbracht wurde, wird Shadra diese Welt langsam vergiften. In der Höhle wimmelt es wahrscheinlich schon von ihrer Brut.\n\nLasst sie nicht entkommen, {name}. Bringt alle Spinnen um, die Ihr finden könnt!", sourceObjective = "Tötet 8 Bruten von Shadra.", completion = "Die sind wir los. Mögen diese schrecklichen Wesen nie wieder unser Land betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26526] = { id = 26526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt die Bewahrerin", description = "Shadra, die Spinnenloa... die Königin des Giftes, ein Geist der Dunkelheit und des Todes! Wenn es ein Opfer gegeben hat, werden die Trolle einen letzten verzweifelten Versuch unternehmen, um sie heraufzubeschwören.\n\n Sollten die Blutfratzen Rituale begonnen haben, dürfen sie nicht vollendet werden.\n\nÜberprüft die Höhle hinter dem Altar an der Spitze von Jintha'Alor. In ihrem Inneren verbirgt sich vielleicht noch eine von Shadras Bewahrerinnen. Tötet sie und bringt mir, was sie bei sich trägt, damit wir herausfinden können, was dort los ist.", sourceObjective = "Tötet Morta'gya die Bewahrerin und bringt die Tafel von Shadra an Euch.", progress = "Durchsucht ihre Leiche. Ich will nicht, dass mögliche Fallen der Blutfratzen durch ihre Tode unentdeckt bleiben.", completion = "Eine Tafel! Wenn ich das richtig lese... wird hier ein Ritual beschrieben, mit dem man Shadra selbst in diese Welt holen kann, sowie die Götzen, die man dafür benötigt.\n\nDass Ihr die Bewahrerin getötet und die Tafel an Euch gebracht habt, war sehr gut, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26527] = { id = 26527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greifenmeister Krallenaxt", description = "Ich würde diese Tafel in Stücke schlagen, wenn ich das Recht dazu hätte. Doch diese Entscheidung darf ich nicht fällen. Greifenmeister Krallenaxt muss sie sehen.\n\nKehrt mit der Tafel zum Nistgipfel zurück. Greifenmeister Krallenaxt kümmert sich im Greifenhorst um die Tiere.\n\nBeeilt Euch... aber lasst die Tafel bloß nicht aus den Augen!", sourceObjective = "Bringt die Tafel von Shadra zu Greifenmeister Krallenaxt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26528] = { id = 26528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Shadra", description = "Greifenmeister Krallenaxt hat mich hierher geschickt, damit ich mich um Shadra, die Königin des Giftes, kümmere. Jintha'Alor zu erobern, ist nicht genug... die Trolle könnten sich neu formieren und die Kreatur zu einem späteren Zeitpunkt beschwören, wenn wir es am wenigsten erwarten.\n\nZuerst sammeln wir die Artefakte, dann holen wir Shadra unter unseren eigenen Bedingungen in diese Welt. Wir werden die verdorbene Kreatur mit unseren Hämmern vernichten. Ihr müsst dabei helfen, die Artefakte zu finden, und wenn Ihr schon dabei seid, dann fügt den restlichen Trollen ordentlich Schaden zu.\n\nDazu benötigen wir zuerst das Auge von Shadra, das in Agol'watha im Norden bewacht wird.", sourceObjective = "Besorgt das Auge von Shadra aus Agol'watha.", progress = "Hatte die Tafel recht? Habt Ihr das Auge gefunden?", completion = "Gut gemacht, {name}. Schon bald werden wir an die Tür des Achtbeins klopfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26529] = { id = 26529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fangzahn von Shadra", description = "Als nächstes brauchen wir den Fangzahn von Shadra.\n\nShadras eigene Brut bewacht ihn in den Gruselruinen im Osten. Abscheuliche Spinnen, groß wie Zwerge und doppelt so stark. Ihr Gift ist stark, {name}... seid nicht nachlässig.", sourceObjective = "Besorgt den Fangzahn von Shadra aus den Gruselruinen.", progress = "Habt Ihr den Fangzahn?", completion = "Das ist er... nur noch eines, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[26530] = { id = 26530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Panzer von Shadra", description = "Wir brauchen nur noch dieses letzte Stück, um Shadra endgültig auszuräuchern.\n\nDer Panzer von Shadra befindet sich im Besitz von Quiaga der Bewahrerin, der letzten Hohepriesterin der Spinnengöttin. Sie hält sich an der Spitze des Altars von Zul auf und wird von anderen fanatischen Zeloten bewacht.\n\nErklimmt den Altar bis zur Spitze und vernichtet sie. Sie wird den Panzer bei sich tragen. Bringt ihn hierher.", sourceObjective = "Tötet Qiaga die Bewahrerin und bringt den Panzer von Shadra an Euch.", progress = "Habt Ihr ihn?", completion = "Das war alles, mein Freund! Wir sind bereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[26531] = { id = 26531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschwörung von Shadra", description = "Unsere besten Kämpfer stehen bereit, das Idol wurde zusammengesetzt... es ist soweit, {name}.\n\nWir werden wie folgt vorgehen. Ihr reist mit dem Idol uns voran in Richtung Südwesten, nach Shadra'Alor. Ihr müsst das Idol an allen drei Tempeln einsetzen und Euch durch die Trolle, die sie bewachen, kämpfen.\n\nWenn Ihr das getan habt, wird Shadra in unsere Welt eindringen. Wir erwarten sie mit Zorn in unseren Herzen. Sagt meinen Jungs in Eurer Nähe Bescheid, sobald Ihr das Ritual vollendet habt.", sourceObjective = "Benutzt das Idol von Shadra am nordwestlichen, südwestlichen und östlichen Tempel in Shadra'Alor.", completion = "Krallenaxt und die Jungs sind direkt hinter Euch. Lasst uns beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26532] = { id = 26532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadra, Königin des Giftes", description = "Keine Zeit verschwenden, {name}! Sie kommt schon aus dem Wasser!\n\nGreifenmeister Krallenaxt ist bereits mit den Jungs unterwegs. Zeigen wir es dem Achtbein!", sourceObjective = "Tötet Shadra die Königin des Giftes.", completion = "Ihr habt heute Großes für die Wildhämmer geleistet, {name}. Ich wünschte, Falstad hätte das miterlebt.\n\nIm Namen des ganzen Klans möchte ich Euch gerne dafür entschädigen, dass Ihr diesen widerwärtigen Schatten von diesen Ländern ferngehalten habt. Ihr habt diese Belohnung redlich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[26533] = { id = 26533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanzils Geheimnis", description = "Vor vielen Jahren verstießen die Gurubashi einen der ihren aus Zul'Gurub: Einen Troll namens Zanzil. Die Gründe dafür sind unklar, aber ich nehme an, dass es mit den starken, verhaltensverändernden Drogen zusammenhing, die er jedem, dem er begegnete, verabreichte. Wie dem auch sei, die Priester der Gurubashi und ihr Blutgott sind vernichtet worden, aber Zanzil der Ausgestoßene existiert noch...\n\n...ebenso wie seine starken, verhaltensverändernden Drogen.\n\nIch würde sie gern in die Finger bekommen, {race}. Überprüft die Zombies im Südosten.", sourceObjective = "Beschafft 5 Phiolen von Zanzils Mixtur.", progress = "Hervorragend... Ihr seid noch kein Zombie. Das ist gut.\n\nOh, äh... nichts. es gab nur ein... ein potentielles Risiko. Hatte ich vergessen, Euch zu warnen?", completion = "<Jasper analysiert das seltsame Gemisch vorsichtig.>\n\nDiese Mixtur ist... Ich verstehe sie nicht. Vielleicht sollten wir einige klinische Tests vornehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26534] = { id = 26534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was hast du zu bieten, Zanzil?", description = "Besucher von Hartzangs Versteck müssen bei ihrer Ankunft einige Verzichtserklärungen unterschreiben. Eine davon erlaubt es uns, einfache Tests an ihnen vorzunehmen. Diese Klausel werden wir wohl wieder aktivieren.\n\nDoch dieses Mal sollten wir versuchen, unsere Kunden nicht zu vergiften. Ist besser fürs Geschäft.\n\n<Jasper füllt eine Karaffe mit Zanzils Mixtur und gestoßenem Eis.>\n\nDer südöstliche Turm des Verstecks dient als provisorisches Gefängnis. Wir nennen es \"Hartzangs Zuchthaus\". Lasst die Gefangenen trinken und sagt mir, was passiert.", sourceObjective = "Bietet Jaspers DschungelschorleGmurgl, Orgus und Kapitän Bartholomäus Weichbart an.", completion = "Was, wirklich? Das ist hochinteressant. In dem Fall...\n\nWen interessiert, wie das Zeug funktioniert! Ich brauche das Rezept!", sourceObjectiveStatus = "unverified-source-field" }
quests[26535] = { id = 26535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zutaten für eine Katastrophe", description = "Ich brauche Zanzils Rezept mehr als je zuvor. Einer von Zanzils Lakaien in den Ruinen von Aboraz müsste es haben. Reist nach Osten, zur anderen Küste des Kaps und stehlt es für mich!", sourceObjective = "Besorgt Zanzils Rezeptur von einem von Zanzils Anhängern in den Ruinen von Aboraz.", progress = "Hat er Schimmerkraut verwendet? Er hat bestimmt Schimmerkraut benutzt.\n\nNein, warte... Bernsteinsamen! Es muss Bernsteinsamen sein.", completion = "Das ist faszinierend! Denkt an all die Anwendungsgebiete!\n\nNur um Missverständnissen vorzubeugen: Ich will keine Sklavenarmee oder so etwas. Nein, nein... Die Ogerexplosionen interessieren mich viel mehr!", sourceObjectiveStatus = "unverified-source-field" }
quests[26536] = { id = 26536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerfälle", description = "Arnold und ich angeln schon seit Jahren in der Gegend um Sturmwind. So lange braucht man, um eine gute Stelle zu finden. Einer meiner Lieblingsorte wird Donnerfälle genannt.\n\nEr liegt südlich von Sturmwind im Wald von Elwynn. Das Beste an den Donnerfällen ist der violette Flussbarsch. Man findet ihn nur dort oben an den Wasserfällen. Arnold und mir fällt der lange Weg in letzter Zeit schwer, deshalb möchte ich Euch bitten, für uns dorthin zu gehen und einige Barsche zu fangen.", sourceObjective = "Fangt 4 violette Flussbarsche bei den Donnerfällen südlich von Sturmwind. Kehrt mit Eurem Fang zu Catherine Leland zurück.", progress = "Habt Ihr die Fälle gefunden?", completion = "Diese Barsche sehen gut aus, {name}. Wollt Ihr mit uns heute Abend Fische grillen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26537] = { id = 26537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschmettert sie!", description = "Geht hinaus und erledigt sie für mich.\n\nBerserker, Erdberster, Todesreiter... mir egal! Zerschmettert diese Steintroggs!", sourceObjective = "Tötet 12 beliebige Steintroggs an der Zerrissenen Front.", completion = "Ihr habt ihnen ganz schön zugesetzt. Aber ich glaube, wir müssen auf eine etwas andere Weise vorgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26538] = { id = 26538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soforthilfe", description = "Viele unserer Krieger sind bei dem Zwielichtangriff auf unsere Luftflotte gefallen. Die Überlebenden schwimmen den Überresten der Flotte entgegen. Sie bluten und haben schwere Verbrennungen erlitten. Ich brauche Unterstützung vom Ufer, um diese Männer zu retten!\n\nIm Hafen des Drachenmals wird es doch wohl einen Arzt oder Medizinmann geben, der gewillt ist, anderen Orcs zu helfen. Geht ans Ufer und versucht, Heilvorräte aufzutreiben und zur Flotte zu bringen!", sourceObjective = "Sucht einen Medizinmann im Hafen des Drachenmals, nahe des Ufers.", completion = "<Gregor verbeugt sich respektvoll vor Zaela.>\n\nWenn dies Zaelas Wunsch ist, dann sollt Ihr Eure Vorräte bekommen. Sagt nur dem Kriegshäuptling des Drachenmals nichts davon...", sourceObjectiveStatus = "unverified-source-field" }
quests[26539] = { id = 26539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festgefahrene Verhandlungen", description = "Der Aufenthaltsort des Kriegshäuptlings ist unbekannt! Aber sein Plan muss fortgeführt werden. {name}, Ihr seht aus wie jemand, der weiß, was er tut.\n\nUnsere Verhandlungen mit dem Drachenmalklan sind festgefahren. Ihr Kriegshäuptling ist... anders als erwartet. Sorgt dafür, dass die Verhandlungen fortgeführt werden.\n\nTrefft Euch mit Ornak am Ufer. Er wird Euch alles erklären.\n\nRedet mit Horzog hier an Deck. Er wird für einen raschen Transport zum Ufer sorgen.", sourceObjective = "Sprecht mit Ornak im Hafen des Drachenmals. Horzog wird für einen raschen Transport zum Ufer sorgen.", completion = "Ich bin froh, dass Ihr hier seid, {class}. Vielleicht kann ein erfahrener Veteran, der für die Horde in Nordend und an anderen Orten gekämpft hat, den Anführern des Drachenmalklans Vernunft einreden...", sourceObjectiveStatus = "unverified-source-field" }
quests[26540] = { id = 26540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliches Mitleid", description = "Der rote Drachenschwarm stellt den Aspekt des Lebens dar. Deshalb hat sein Blut heilende Wirkung.\n\nDie Verbände in dieser Kiste wurden in rotes Drachenblut getränkt. Das sind meine letzten Vorräte. Mögen sich Eure Krieger dank ihnen rasch erholen.\n\nEs ist egal, wie Eure Verhandlungen hier ausgehen, Ihr werdet immer Freunde im Drachenmalklan haben.", sourceObjective = "Bringt die Kiste mit Bandagen des Drachenmals zurück zu Kriegsfürst Krogg auf See vor dem Hafen des Drachenmals.", progress = "Könnt Ihr unseren Verwundeten Hoffnung machen?", completion = "Drachenblut!? Wir sollten unseren Verbündeten unter den roten Drachen besser nichts davon erzählen.\n\nTrotzdem ist es mächtige Magie... Unsere Truppen werden bald wieder bereit stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26542] = { id = 26542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Das Hinterland!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Greifenmeister Krallenaxt im Greifenhorst am Nistgipfel zu melden.\n\nUnsere neuen Brüder in der Allianz brauchen unsere Hilfe dabei, die aggressive Hordenoffensive in ihrer geliebten Heimat abzuwehren. Reist vom Arathihochland nach Norden durch den zwergischen Bergpass und folgt der Straße nach Nordwesten Richtung Nistgipfel.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Reist zum Nistgipfel im Hinterland und sprecht mit Greifenmeister Krallenaxt.", completion = "Willkommen am Nistgipfel, {name}. Im Namen des Obersten Thans Falstad danke ich Euch für Euer Kommen, um uns zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26543] = { id = 26543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muscheln meucheln", description = "Nichts schmeckt so gut wie frisches monströses Muschelfleisch, {name}. In den letzten Wochen hatte ich so viel zu tun, dass ich keine Zeit hatte, mich zu den örtlichen Muschelgründen zu begeben. Könntet Ihr mir vielleicht einige dieser Delikatessen besorgen?\n\nIhr findet die Muscheln in der Nähe des Strandes an der Ostküste von Durotar. Rund um den Hafen von Orgrimmar sollte es jede Menge geben.", sourceObjective = "Besorgt 10 Stücke Fleisch einer monströsen Muschel von den Muscheln an der Ostküste Durotars, südlich von Orgrimmar. Kehrt danach zu Razgar zurück.", progress = "Habt Ihr die Muscheln gefunden?", completion = "Scheinen die richtigen Muscheln zu sein, {name}. Die werden gut schmecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[26544] = { id = 26544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie werden schlauer...", description = "<Der Gnomcorder kracht und knackt.>\n\nDie Schwarzfelsorcs scheinen doch noch klug zu werden. Man hat mir gemeldet, dass sie sich mit den Gnollen verbündet haben und einen Angriff planen, Ich brauche Einzelheiten. {name}!\n\nÜberprüft die Rethbanhöhlen im westlichen Teil der Rotkammschlucht für mich. Sucht nach Orcs mit dunkler Haut. Tötet alle, denen Ihr begegnet und durchsucht ihre Leichen nach Informationen.\n\nSolomon Ende.", sourceObjective = "Besorgt das Sendschreiben der Orcs des Schwarzfelsklans.", progress = "Was habt Ihr herausgefunden?", completion = "<Der Gnomcorder summt und surrt.>\n\nLegt das Sendschreiben in das kleine Fach, damit ich es lesen kann. Ich spreche fließend Orcisch.\n\n<Ihr hört einen entsetzten Schrei im Hintergrund.>\n\nDiese Orcs scheinen auf Jaulers direkten Befehl hier zu sein. Das bedeutet, dass Jauler den Invasionsplan der Orcs besitzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26545] = { id = 26545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jauler muss sterben!", description = "<Der Gnomcorder summt.>\n\nIhr müsst Jauler finden, {name}. Er hält sich irgendwo im nördlichen Teil der Rotkammschlucht auf. Tötet den räudigen Hund und durchsucht seine Leiche nach den Invasionsplänen des Schwarzfeldklans. Sollte das gelingen, bringt die Pläne zu mir in das Rathaus von Seenhain.\n\nSolomon Ende.", sourceObjective = "Tötet Jauler und bergt die Invasionspläne des Schwarzfelsklans.", progress = "Habt Ihr die Invasionspläne des Schwarzfelsklans?", completion = "<Ihr gebt Magistrat Solomon die Pläne. Er beginnt zu lesen.>\n\nSchattenfellarmee!? Diese verfluchten Orcs! Diese Invasionspläne weisen darauf hin, dass die Orcs und die Gnolle eine gewaltige Streitmacht im Osten zusammenziehen. Gath'Ilzogg, der General des Schwarzfelsklans will wohl mit seinen Armeen durch Seenhain marschieren und Sturmwind direkt angreifen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26546] = { id = 26546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klingenschnabelfreunde", description = "Für unseren Klan sind Greifen heilige Tiere. Wir verehren sie. Es sind majestätische Himmelswesen, mehr als nur Tiere. Sie sind intelligent und listig.\n\nManche behaupten, wir würden sie halten, aber es ist eher wie eine Freundschaft. Wenn Ihr Euch mit den Wildhämmern anfreunden wollt, dann freundet Euch zuerst mit unseren Greifen an! Nehmt diesen Futtersack. Alles darin ist frisch und gut. Ihr findet unsere ausgebildeten Klingenschnabelgreifen in den Wäldern südlich des Greifenhorsts. Würdet Ihr einige von ihnen für mich füttern?", sourceObjective = "Füttert 7 ausgebildete Klingenschnabelgreifen mit dem Greifenfutter.", completion = "Behandelt sie respektvoll, dann werden sie ebenso mit Euch umgehen.\n\nVergesst Eure Manieren und Ihr seid ein Auge los!", sourceObjectiveStatus = "unverified-source-field" }
quests[26547] = { id = 26547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räudige Bedrohung", description = "Wir beschützen unser Volk und unsere Greifen mit allen Mitteln. Dazu gehört, dass wir Räuber verjagen, und zwar die aus dem Wald und die der Horde.\n\nErst einmal werde ich Euch noch nicht bitten, uns vor den zweibeinigen Ungeheuern zu schützen. Räudige Silbermähnen streunen durch die Wälder im Süden. Sie attackieren die Greifen, die zu niedrig fliegen. Jagt einige Silbermähnen, damit sie erkennen, dass Greifen keine Beute sind.", sourceObjective = "Tötet 8 räudige Silbermähnen.", completion = "Das hilft uns sehr, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26548] = { id = 26548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zur Front", description = "Wir benötigen Eure Hilfe nun in dringenderen Angelegenheiten, {name}.\n\nDie Horde wird dort draußen immer dreister. Sie sind in unserer Territorium eingedrungen und greifen uns hemmungslos an. Die Waldtrolle der Bruchhauer attackieren den Sturmfederaußenposten sogar bei Tage!\n\nIch brauche Eure Hilfe. Sprecht draußen mit Guthrum Donnerfaust. Er wird Euch einen Greifen zum Sturmfederaußenposten geben. Kerr Eisenblick wird Euch alles erklären, wenn Ihr dort eintrefft.", sourceObjective = "Sprecht mit Kerr Eisenblick im Sturmfederaußenposten.", completion = "Schön, Euch hier draußen zu sehen! Wir können anfangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26549] = { id = 26549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahnsinn", description = "Unsere letzten beiden Verhandlungsführer sind von den Gesprächen mit dem Kriegshäuptling des Drachenmalklans noch nicht zurückgekehrt. Ich glaube, wir müssen unsere Muskeln spielen lassen.\n\nDeshalb möchte ich, dass IHR dieses Mal den Unterhändler begleitet. Ihr Kriegshäuptling wird seine Haltung vielleicht ändern, wenn er erkennt, dass die Horde voll von kampferprobten Helden wie Euch ist.\n\nIhr müsst den Unterhändler nur in das Hauptlager im Hafen des Drachenmals begleiten und bedrohlich aussehen.", sourceObjective = "Begleitet den Hordenunterhändler in den Hauptsaal im Hafen des Drachenmals und trefft Euch mit Kriegshäuptling Mor'ghor vom Drachenmalklan. Sprecht mit Ornak an der Küste, sollte Euch der Unterhändler abhanden kommen.", progress = "{name}, ich habe gehört, dass Ihr mit dem \"Kriegshäuptling\" über den Beitritt zu Eurer Horde sprechen wollt.\n\nSeid vorsichtig, {class}.\n\nKommt danach zu mir...", completion = "Aufwachen, {name}! Wir haben nicht viel Zeit.\n\nIch habe Eure Ausrüstung gerettet.\n\nJetzt habt Ihr die Torheit unseres Anführers am eigenen Leib erlebt. Sein Blut ist verseucht, seine Wut unbezähmbar -- sein Bestreben, die Horde zu schlagen, wird uns alle vernichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[26550] = { id = 26550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch die Hintertür", description = "Zanzil der Ausgestoßene, der vom Gurubashistamm verbannt wurde, soll meine Beute werden. Vor kurzem habe ich von meinen Brüdern im Norden erfahren, dass er in die Gesellschaft zurückkehren will. Aus diesem Grund hat er einen Abgesandten zu den Schädelspaltern geschickt. Das sind keine guten Nachrichten.\n\nIch möchte, dass Ihr Euch Zanzils Pläne einmal anseht. Nehmt diesen Weihrauch und stellt ihn vor dem Fledermaustotem in den Ruinen von Jubuwal östlich von hier ab. Hir'eek wird Euch von dort an führen.", sourceObjective = "Stellt den Weihrauch der Gurubashi vor dem Totem von Hir'eek ab und hört Euch Zanzils Plan an.", completion = "Das hatte ich vermutet. Zanzil ist zu hochmütig, um sich in die Streitigkeiten zwischen den Blutskalpen und den Schädelspaltern einzumischen. Nein, er ist Teil eines größeren Plans... Jin'do der Verhexer will mit seiner Hilfe Hakkar zurück nach Zul Gurub bringen.\n\nGut, dass wir das herausgefunden haben, denn es gibt eine einfache Lösung.", sourceObjectiveStatus = "unverified-source-field" }
quests[26551] = { id = 26551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beseitigt den Ausgestoßenen", description = "Ihr werdet Zanzil töten. Ihr seid auf Hir'eeks Schwingen geritten und habt durch seine Augen geblickt; Ihr wisst, wo sich Zanzil in den Ruinen von Aboraz versteckt. Reist dorthin und tötet ihn.\n\nOh, und {race}: Benutzt diesen Fetisch, falls wir getrennt werden. Er funktioniert nur im Schlingendorntal und wird Euch hierher zurückbringen, solltet Ihr rasch zu mir gelangen müssen.\n\nViel Glück, {race}. Zanzil ist kein gewöhnlicher Gegner.", sourceObjective = "Reist zu den Ruinen von Aboraz am Kap des Schlingendorntals und kümmert Euch um Zanzil den Ausgestoßenen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26552] = { id = 26552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Trollloch", description = "Zanzils Portal nach Zul'Gurub ist noch geöffnet. Zul'Gurub ist ein gefährlicher Ort, aber Chabal glaubt, dass Ihr diese Aufgabe erfüllen könnt.\n\nDas Portal erwartet Euch.", sourceObjective = "Benutzt Zanzils Portal und betretet Zul'Gurub.\n\nSolltet Ihr Euch verlaufen oder nach Zul'Gurub zurückkehren müssen, sprecht mit Chabal in Hartzangs Versteck.", sourceObjectiveStatus = "unverified-source-field" }
quests[26553] = { id = 26553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hohepriesterin Jeklik", description = "Vor Euch ragt eine Rampe, die zu einer der zahlreichen Terrassen der Stadt führt, bedrohlich empor. Die fledermausförmigen Totems vor Euch weisen darauf hin, dass Ihr Euch im Reich der Hohepriesterin Jeklik, einer Anhängerin von Hir'eek, befindet.\n\nJeklik gehörte zu den Hakkar anbetenden Priestern, die Zanzil wiedererwecken wollte. Wenn Ihr Euch beeilt, gelingt es Euch vielleicht, die Erweckung aufzuhalten!", sourceObjective = "Vernichtet die Leiche der Hohepriesterin Jeklik, bevor Zanzil sie wiedererwecken kann.\n\nSolltet Ihr Euch verlaufen oder nach Zul'Gurub zurückkehren müssen, sprecht mit Chabal in Hartzangs Versteck.", sourceObjectiveStatus = "unverified-source-field" }
quests[26554] = { id = 26554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hals über Kopf nach Zul'Gurub", description = "Zanzil der Ausgestoßene ist erneut durch eines seiner Portale geflohen. Folgt ihm!", sourceObjective = "Geht durch Zanzils Portal.\n\nSolltet Ihr Euch verlaufen oder nach Zul'Gurub zurückkehren müssen, sprecht mit Chabal in Hartzangs Versteck.", sourceObjectiveStatus = "unverified-source-field" }
quests[26555] = { id = 26555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hohepriester Venoxis", description = "Venoxis war der zweite der beiden Priester, die Zanzil von den Toten erwecken wollte. Es ist Euch bereits gelungen, Hohepriesterin Jekliks Leiche zu vernichten... Venoxis muss der nächste sein.", sourceObjective = "Kümmert Euch um Zanzil den Ausgestoßenen und Hohepriester Venoxis.\n\nSolltet Ihr Euch verlaufen oder nach Zul'Gurub zurückkehren müssen, sprecht mit Chabal in Hartzangs Versteck.", completion = "Ich hatte Euch gebeten, Zanzil den Ausgestoßenen zu töten, einen niederen verbannten Einsiedler der Gurubashi, und was macht Ihr? Ihr stürmt in die Hauptstadt der Gurubashi und eliminiert einen ihrer Hohepriester! Beinahe sogar zwei! Es gibt nur ein Wort, um ein so unbedachtes und tollkühnes Unterfangen zu beschreiben:\n\nHeldenmut.\n\nJin'do der Verhexer schleicht immer noch in Zul'Gurubs Mauern umher, aber als Ihr Jeklik zerschmettertet, verlor er eines seiner Beine. Heute ist der Sieg unser.", sourceObjectiveStatus = "unverified-source-field" }
quests[26556] = { id = 26556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Müll abladen verboten", description = "Seit die Goblins in Orgrimmar Schutz gesucht haben, werfen sie all ihren Unrat in unsere Wasserspeicher.\n\nIch weiß nicht, welche Konsequenzen das für unseren Fischbestand haben wird, aber es sind bestimmt keine guten. Ich habe Berichte über eine neue mutierte Fischart erhalten, die in der toxischen Pfütze nahe ihres Lagers gesichtet worden ist. Einige Exemplare würden mir dabei helfen herauszufinden, was genau dort vorgeht.\n\nWürdet Ihr mir aushelfen?", sourceObjective = "Angelt 6 giftige Pfützenfische und kehrt zu Razgar ins Tal der Ehre zurück, wenn Ihr fertig seid.", progress = "Habt Ihr ein paar Exemplare geangelt?", completion = "Gute Arbeit, {name}. Dank dieser Exemplare werden wir herausfinden, was in der giftigen Suppe dort vorgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26557] = { id = 26557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen auf beim Angeln", description = "Seit Jahren angle ich im Wasser von Orgrimmar Sandkarpfen. In letzter Zeit ist mir aufgefallen, dass meine Köder nicht mehr so gut funktionieren wie früher. Ich vermute, dass dies etwas mit den Tauren zu tun hat, die ins Tal der Weisheit gezogen sind.\n\nIch habe mit einigen ihrer Angler gesprochen. Anscheinend hat sich der Geschmack der Fische geändert. Heutzutage beißen sie wohl bei Hirschaugen an. Ihr solltet nördlich von Orgrimmar, unmittelbar hinter dem nördlichen Tor, jede Menge Hirsche finden.", sourceObjective = "Erlegt einen Hirsch nördlich von Orgrimmar und benutzt sein Auge als Köder, um einen Sandkarpfen im Tal der Weisheit zu fangen. Kehrt danach zu Razgar ins Tal der Ehre zurück.", progress = "War das Auge ein guter Köder?", completion = "Hervorragend! Diese Sandkarpfen sind ganz schön wählerisch, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[26558] = { id = 26558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschwörung von Shadra", description = "Der Götze ist bereit, {name}. Ich hoffe, Ihr seid es auch.\n\nReist mit dem Götzen vor uns nach Shadra'Alor im Südwesten. Ihr müsst den Götzen an jedem der drei Tempel einsetzen.\n\nWenn Ihr das tut, wird Shadra in dieses Reich beschworen. Die Todespirscher und ich werden rasch zu Euch stoßen, sie überwältigen und ihren Körper verwerten. Sprecht mit dem Späher, den ich vorangeschickt habe, wenn das Ritual vollendet ist, und wartet auf mein Eintreffen.", sourceObjective = "Benutzt den Götzen von Shadra am nordwestlichen, südwestlichen und östlichen Tempel in Shadra'Alor.", completion = "Marnal kommt näher...und Shadra noch näher. Bereitet Euch auf Blutvergießen vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[26560] = { id = 26560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jorgensen", description = "Ich weiß nicht, wo Krakauer oder Danforth sind, aber Jorgensen wurde nordwestlich von hier, in Renders Lager festgehalten. Wir saßen im gleichen, verdreckten Käfig, bevor man mich nach Althers Mühle verlegte.\n\nUm ihn zu befreien, brauchen wir den Schlüssel. Eine eiskalte Hexe aus der Hölle namens Utroka die Schlüsselmeisterin hält ihn fest in den Klauen. Wir müssen sie töten, wenn wir Jorgensens Käfigschlüssel haben wollen. Sie hält sich nördlich von hier in dem Tal auf, das zur Brennenden Steppe führt.\n\nAuf geht's, <Junge/Mädchen>.", sourceObjective = "Besorgt Jorgensens Käfigschlüssel.", progress = "Messner! Verdammt, es tut gut, ein freundliches Gesicht zu sehen. Holt mich hier raus!", completion = "Ich weiß, wo Krakauer und Danforth festgehalten werden. Wir müssen uns beeilen. Die beiden sollen geopfert werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[26561] = { id = 26561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krakauer", description = "Krakauer steht schon auf dem Richtblock! Die Orcs haben einen Hexendoktor der Gurubashi geholt, der ein dunkles Ritual über ihn sprechen soll. Wir müssen den Troll töten und Krakauer befreien!\n\nLos! Er ist in der Höhle dort. Geht nach rechts an der ersten Gabelung.", sourceObjective = "Tötet Ritualist Tarak.", completion = "Wa... Wo bin ich? Was ist passiert? Messner? Jorgensen?\n\nOH MEIN GOTT! Wir müssen Danforth holen! Hoffentlich ist es noch nicht zu spät!", sourceObjectiveStatus = "unverified-source-field" }
quests[26562] = { id = 26562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Nachzügler... Danforth", description = "Danforth wird auf der anderen Seite der Höhle gefoltert. Wer weiß, in welchem Zustand er mittlerweile ist! Wir müssen zu ihm und ihn retten!\n\nOberanführer Barbarius trägt den Schlüssel zu dem Hebel, der Danforth oben hält, bei sich. Wenn wir zusammen arbeiten, können wir Barbarius, dieses Schwein, töten. Wenn Barbarius tot ist, holen wir Danforth mit seinem Schlüssel herunter und hauen ab!\n\nBereit?", sourceObjective = "Tötet Oberanführer Barbarius und bergt den Hebelschlüssel des Schwarzfelsklans. Befreit Danforth mit dem Hebelschlüssel des Schwarzfelsklans.", progress = "Sieh mal einer an! Die ganze Truppe ist hier... abgesehen von Keeshan.", completion = "Worauf habt ihr Feiglinge denn die ganze Zeit gewartet? Meine Arme wurden schon müde.", sourceObjectiveStatus = "unverified-source-field" }
quests[26563] = { id = 26563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der Kompanie Bravo", description = "Ich weiß nicht, wer Ihr seid, <Freund/Schwester>, aber Ihr habt Euch den Respekt und die Bewunderung der Kompanie Bravo verdient. Ihr habt unsere Haut gerettet und auch noch eine Bootsladung voller Orcs getötet. Wir werden den Gefallen erwidern.\n\nReist zurück nach Seenhain und meldet Euch bei Oberst Trottmann. Wir werden Johnny finden und die gute Nachricht persönlich überbringen. Wenn die Kompanie Bravo loslegt, haben diese Orcs keine Chance.", sourceObjective = "Meldet Euch bei Oberst Trottmann in Seenhain im Rotkammgebirge.", completion = "<Oberst Trottmann salutiert.>\n\nUnglaubliche Arbeit, {name}. Ihr habt es geschafft, die ganze Kompanie Bravo aus den Klauen der Schwarzfelsorcs zu befreien? Jetzt, da Keeshans Team gerettet ist und seine Habseligkeiten wieder da sind, gibt es für ihn keine Möglichkeit, uns abzuweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26564] = { id = 26564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimwerker", description = "<Klei sieht Euch verächtlich an und macht ein Geräusch, das klingt, als reibe man zwei Steine aneinander.>\n\nSie haben all unsere Katapulte zerschlagen. Das hier versuche ich zu reparieren, aber bis jetzt ohne Erfolg.\n\nIhr könntet Euch nützlich machen. Reist zur Front und bringt mir alle Ersatzteile, die Ihr findet.\n\nKriegt Ihr das hin, Fleischsack?", sourceObjective = "Besorgt 6 Katapultteile.", progress = "Und? Ich hab nicht den ganzen Tag Zeit.", completion = "Also gut. Vielleicht seid Ihr doch in Ordnung.\n\nSchon gut, schon gut... kriegt Euch wieder ein. Gebt mir etwas Zeit mit diesen Teilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26565] = { id = 26565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wütender Fang", description = "Steht Euch der Sinn nach einer Herausforderung, {name}? Gut, das hatte ich gehofft. Der Südstrom führt westlich an Orgrimmar vorbei. Eure Herausforderung schwimmt in seinen mächtigen Wassern.\n\nWir suchen nach einem riesigen, wütenden Hecht. Dieser geschätzte Fisch war früher zahlreich in dieser Gegend vertreten, doch seit der Flut sieht man ihn nur noch selten. Begebt Euch zum Fluss, dann werden wir sehen, wie gut es wirklich um Eure Angelkünste bestellt ist.", sourceObjective = "Fangt einen riesigen wütenden Hecht im Südstrom. Ihr findet den Südstrom vor dem westlichen Tor von Orgrimmar. Kehrt danach ins Tal der Ehre zu Razgar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[26566] = { id = 26566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Triumph gnomischer Erfindungsgabe", description = "Wir werden alle Waffen, Erfindungen und Soldaten brauchen, die wir kriegen können, wenn wir Razlo Ritzelstoß und seine Anhänger besiegen wollen.\n\nIm Nordosten werdet Ihr Ingenieur Schleiffunke finden, der einer neuen Generation brillanter Gnomendenker angehört. Stellt Euch vor: er hatte seit mehr als drei Prototypen keine Explosion mehr!\n\nGenug angegeben. Ingenieur Schleiffunke arbeitet an einem Bot, mit dessen Hilfe er den Toxischen Flugplatz reinigen will. Stellt Euch ihm vor. Vielleicht könnt Ihr ihm bei den Tests des Bots helfen.", sourceObjective = "Sprecht mit Ingenieur Schleiffunke in Neu-Tüftlerstadt.", completion = "Sogar Mekkadrill selbst hat also von meinem kleinen Projekt gehört? Wunderbar! Mein neuester Prototyp ist zwar fast fertig, aber Ihr könntet mir noch bei der Suche nach den letzten Teilen helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26567] = { id = 26567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "John J. Keeshan", description = "Habt Ihr mal von John Keeshan gehört, {name}? Ich war in allen drei großen Kriegen sein Kommandant. Ich sage Euch, dieser Mann hat mehr Orcs getötet als jeder andere. Wenn jemand die Invasion der Schwarzfelsorcs aufhalten kann, dann JOHN J. KEESHAN. Wir müssen ihn dazu bringen, uns zu helfen. Wenn die gewaltige Schwarzfelsarmee auf ihrem Weg nach Elwynn durch Seenhain marschiert, wird sie das ganze Land in Schutt und Asche legen.\n\nIch habe gehört, dass er dem geheimen Kampfclub angehört, der sich im Gasthaus von Seenhain trifft. Findet ihn und erzählt ihm alles, was Ihr wisst.", sourceObjective = "Bemüht Euch um die Hilfe von John J. Keeshan im Gasthaus Seenhain in Seenhain.", completion = "Euch helfen? Diesen Leuten helfen? Diese Leute, die mich eher anspucken als anlächeln würden?", sourceObjectiveStatus = "unverified-source-field" }
quests[26568] = { id = 26568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is' nich' mein Krieg", description = "Sie verlangten von mir, in diesen Kriegen zu kämpfen. Ich habe sie nicht darum gebeten! Ich tat, was ich tun musste, um zu siegen. Irgendwann wurde ich von diesen schmutzigen, mit Unrat beschmierten, verlausten Orcs gefangen genommen. Fünf lange Jahre benutzten sie mich als ihre Toilette. Schließlich brach ich aus, kehrte in meine Heimatstadt zurück... und was geschah? Die Leute spuckten mich an, beschimpften mich und nannten mich einen Babyorcmörder und andere üble Verleumdungen.\n\nNein, ich werde Euch wohl eher nicht helfen. Geht zurück zu Trottmann und sagt ihm, das sei nicht mein Krieg.", sourceObjective = "Kehrt zu Oberst Trottman zurück.", completion = "<Trottmann seufzt.>\n\nIch werde ihn noch nicht aufgeben, {name} - und ich werde das Rotkammgebirge nicht aufgeben. Wir müssen ihn aufmuntern... Weckt das schlafende Monster in ihm auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[26569] = { id = 26569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermessungsausrüstung", description = "Ah, meine Rettung! Ich habe gehört, dass Ihr Euch auf einer Mission zur Rettung von Seenhain ... und meiner Brücke... befindet. Hab viel zu lang daran gearbeitet, um zuzusehen, wie das verdammte Ding von plündernden Orcungeheuern zerstört wird!\n\nSolltet Ihr auf dem Weg nach Norden, zu Renders Lager, sein, könntet Ihr mir einen Gefallen erweisen. Besorgt ein paar Teleskope von den Fährtenlesern des Schwarzfels. Könnte ich gut für meine neue Vermessungsausrüstung gebrauchen.", sourceObjective = "Beschafft 5 Teleskope des Schwarzfelsklans.", progress = "Habt Ihr die Teleskope bekommen?", completion = "Großartige Arbeit, {name}! Bei meinem nächsten Projekt, der SUPERBRÜCKE von Seenhain, die sich über den gesamten Immerruhsee erstrecken soll, werden sie mir gute Dienste erweisen. Die Brücke sollte in rund 20 Jahren fertig sein. Plus minus einem Jahrzehnt, oder zwei.", sourceObjectiveStatus = "unverified-source-field" }
quests[26570] = { id = 26570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renders Armee", description = "Hey, auf dem Weg nach Norden? Hättet Ihr Lust, Euren eigenen kleinen Krieg gegen diese Schwarzfelsmonster anzuzetteln? Was sagt Ihr dazu, {name}?\n\nTötet jeden Schwarzfelsorc, der Euch rund um Althers Mühle oder Renders Lager begegnet. Tötet, bis sich Eure Haut von ihren Blutspritzern rot färbt und kommt dann zu mir zurück. Ich werde Euch großzügig belohnen.\n\nDas wird die Invasion des Schwarzfelsklans wahrscheinlich nicht aufhalten, aber es wird ihre Pläne empfindlich stören.", sourceObjective = "Tötet 25 beliebige Schwarzfelsorcs in Althers Mühle oder Renders Lager.", completion = "Ihr habt uns einen Tag, vielleicht sogar zwei verschafft. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26571] = { id = 26571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegswaffen", description = "Das, worum ich Euch bitten möchte, wird nicht leicht zu erfüllen sein, {name}. Keeshan hat alles in diesem Orcgefängnis zurückgelassen, und damit meine ich nicht nur seine Seele und seinen Lebenswillen.\n\nWenn Johnny für uns kämpfen soll, müssen wir seinen wertvollsten Besitz bergen. Die Orcs haben Keeshans Bogen und sein Überlebensmesser an sich gebracht.\n\nReist nach Althers Mühle östlich von hier und sucht nach den beiden Orcleutnants Murdunk und Homurk. Sie haben Keeshans Ausrüstung. Holt sie Euch.\n\nIch bleibe mit dem Gnomcorder in Verbindung.", sourceObjective = "Bergt Keeshans Bogen und Keeshans Überlebensmesser.", progress = "Habt Ihr Murdunk und Homurk eliminiert?", completion = "<Der Gnomcorder summt voller Energie.>\n\nMeldet Euch, {name}. Versteht Ihr mich? Hier ist Trottmann! Danke, dass Ihr Keeshans Waffen zurückgebracht habt! Jetzt müsst Ihr nur noch eine letzte Mission erfüllen. Stellt Ihr Euch der Herausforderung?", sourceObjectiveStatus = "unverified-source-field" }
quests[26572] = { id = 26572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elektrisierender Einfall", description = "Wisst Ihr, was ein goldener Steinfisch ist, {name}? Diese Fische kann man nicht mit normalen Mitteln fangen. Ihre Kiefer sind so stark, dass sie Angelhaken und Köder einfach durchbeißen.\n\nMan findet sie im Donnergrat südlich von Orgrimmar. Früher war der Grat voller Donnerechsen, aber sie sind alle bei der Flut ertrunken.\n\nNehmt mein Messer, schwimmt dort hinein und schneidet ihre Schwänze ab. Der Stromschlag des Schwanzes sollte die Steinfische töten.", sourceObjective = "Schneidet im Donnergrat, südlich von Orgrimmar, den Schwanz einer ertrunkenen Donnerechse mit Razgars Filetiermesser ab. Benutzt den Schwanz nahe eines goldenen Steinfischs, um ihn damit zu töten. Kehrt danach zu Razgar ins Tal der Ehre zurück.", progress = "Wie ist es da unten gelaufen? Hattet Ihr Glück mit den Schwänzen und den Steinfischen?", completion = "Gut gemacht, {name}! Ganz ehrlich, goldene Steinfische bekommt man nur schwer. Das ist ein besonderer Leckerbissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26573] = { id = 26573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er muss mit ganzem Herzen dabei sein", description = "<Der Gnomcorder klickt.>\n\nSeine Ausrüstung allein reicht nicht, {name}. Er muss diese Schlacht von ganzem Herzen wollen. Um das zu erreichen, benötigen wir Gegenstände von sentimentalem Wert. Die Schwarzfelsorcs von Renders Lager im Norden besitzen zwei solcher Gegenstände, die Keeshan gehören.\n\nBegebt Euch dorthin und durchsucht ihre Kisten nach Keeshans Stirnband und einem Jadeamulett, das ihm seine Frau - die bei einer Invasion der Schwarzfelsorcs brutal ermordet wurde - hinterlassen hat.\n\nBringt sie zu mir, solltet Ihr fündig werden.", sourceObjective = "Findet Keeshans rotes Stirnband und Keeshans Jadeamulett.", progress = "Habt Ihr Stirnband und Amulett gefunden?", completion = "Ich hoffe, dass er dank dieser Gegenstände und seiner geretteten Kameraden seine Meinung ändert. Ohne Keeshan sind wir aufgeschmissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26574] = { id = 26574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adellas geheimes Lager", description = "Lady Shandris hat Euch bereits darum gebeten, uns noch mehr zu helfen.\n\nAdella hat sich in Richtung Osten aufgemacht, zu den Waldpfotengnollen, und ein kleines Lager südlich von Camp Mojache errichtet. Wenn Ihr Lady Shandris und der Allianz weiter dienen wollt, so solltet Ihr Euch bei Adella melden.\n\nBegebt Euch nicht zu nahe an Camp Mojache heran... die Horde wird mit einem Angriff nicht zögern. Haltet Euch südlich und haltet nach unseren Bannern Ausschau.", sourceObjective = "Meldet Euch bei Adella im Schattengeäst in Feralas.", completion = "Willkommen im Schattengeäst, {name}. Lady Shandris hat Euer Kommen angekündigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26575] = { id = 26575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinalt", description = "Ich muss Euch um einen weiteren Gefallen bitten, Fleischling.\n\nEs dreht sich um einen Basilisken, der viel größer und älter als die anderen ist. Normalerweise fürchten wir sie nicht, doch dieser Basilisk ist mittlerweile so stark, dass er sogar einige meiner Söhne versteinert hat. Das dürfen wir nicht hinnehmen.\n\nSucht Gorgonit im Osten und erschlagt ihn. Er hat bereits viel länger gelebt als nötig.", sourceObjective = "Tötet Gorgonit.", completion = "Danke, {race}. Ihr habt alles getan, worum ich Euch zu bitten wagte. Ich werde der Steinmutter berichten, welch guten Eindruck Ihr bei mir hinterlassen habt.\n\nMöge der Stein unter Euren Füßen Euch bei der Suche nach der Weltensäule stets stützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26576] = { id = 26576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhige Hand", description = "Im Norden, ganz in der Nähe, werdet Ihr Terrath den Beständigen finden. Er hat die Aufgabe angenommen, die Steindrachen zurückzugewinnen. Alle paar hundert Jahre muss das wiederholt werden... die Steindrachen sind launisch und beugen sich nur der Stärke.\n\nTerrath ist ausgeglichen und vernünftig, doch seine Ziele werden schwer zu erreichen sein. Geht zu ihm. Appelliert an die ausgeglichenere Seite der Steinmutter.", sourceObjective = "Sprecht mit Terrath dem Beständigen vor dem Bleichen Hort.", completion = "Seid gegrüßt, {race}. Man hat mir Euer Kommen bereits angekündigt. Wenn Ihr mir helfen möchtet, dann könnte ich vielleicht auch Euch behilflich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26577] = { id = 26577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felserhebung", description = "Auf der Rubinspanne im Osten werdet Ihr Gorsik finden. Er steht für den instabilen und gewalttätigen Teil des Naturells unseres Volkes. Er ist weder freundlich noch offenherzig, aber seine Stimme hat Gewicht.\n\nBeweist Euch Gorsik, dann wird es Euch leichter fallen, Euch auch der Steinmutter zu beweisen.", sourceObjective = "Sprecht mit Gorsik dem Tosenden auf der Rubinspanne.", completion = "Ihr seid Diamants Auserwählter.\n\nSo klein. So zerbrechlich.\n\nIst Euch bewusst, dass auf der Grundlage Eurer Handlungen der gesamte \"Irdene Ring\" beurteilt wird? Seid Ihr sicher, dass Ihr wirklich stellvertretend für so viele handeln wollt?\n\nIhr seid ein Narr. Ein zuversichtlicher Narr. Wir werden sehen, ob Ihr auch ein fähiger Narr seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[26578] = { id = 26578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammnispilze", description = "Die Spalte, die in Eure Welt führt, hat unsere Heimat vergiftet. Korrumpiert. Verschmutzt.\n\nDiese Spanne schwärt und wächst. Unter dem ganzen Dreck kann man die Reinheit des Steins kaum noch erkennen.\n\nWenn Ihr uns zur Seite stehen wollt, dann beseitigt diese Überwucherung. Sucht nach hell leuchtenden Pilzen, die schneller wachsen als die anderen. Das sind die schlimmsten Übeltäter.", sourceObjective = "Zerstört 10 Verdammnispilze.", completion = "Ihr habt Euch an Diamant gewandt. Er ist geduldig. Vertrauensselig. Vielleicht zu sehr. Ihr müsst mir viel beweisen, wenn Ihr meine Gunst erlangen wollt, {race}.\n\nAber den Anfang habt Ihr immerhin gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26579] = { id = 26579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verweichlicht", description = "Die Fungusungetüme um uns herum sind einer Schwäche erlegen, die der Eurer Art sehr gleicht. Ihre Haut ist weich geworden. Sie gehören nicht mehr zum Stein.\n\nTötet sie. Wir wollen nicht, dass diese Krankheit sich ausbreitet.", sourceObjective = "Tötet 8 Fungusungetüme.", completion = "Ihr tragt ein gewisses Maß an Macht in Euch. Ich kann diese Stärke respektieren, besonders bei Eurer Art.\n\nMeine Bedenken sind noch nicht aus dem Weg geräumt. Weder in Bezug auf das übermäßige Wachstum noch auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26580] = { id = 26580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertraute Eindringlinge", description = "Fleischling. Einige Eurer Art huschen über die Felsen. Zu scheu, um näher zu kommen, zu schnell, um sie zu zerschmettern.\n\nWenn Ihr meine Gunst erlangen wollt, kümmert Euch um sie. Ich bin diese Spielchen leid.", sourceObjective = "Sprecht mit den \"Fleischlingeindringlingen\" auf der Rubinspanne.", completion = "Schön Euch wiederzusehen, Bruder. Wie ich sehe, tragen Eure Bemühungen Früchte. Die Steinlords scheinen Euch zumindest ein wenig zu vertrauen.\n\nWir sind hier, um zu helfen. Vielleicht können wir gemeinsam herausfinden, was diesen plötzlichen Wuchs verursacht. Ich befürchte nämlich, dass Euer Riesenfreund seine Wut auf das falsche Ziel richtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26581] = { id = 26581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kopf in den Wolken", description = "Ich bin zwar kein Druide, aber ein paar dieser Pilze sehen nicht so aus, als seien sie natürlich gewachsen. Ich weiß, dass unser Freund, der Steinlord da hinten, Azeroth die Schuld an diesem Befall geben will, aber ich glaube, die Ursachen sind hausgemacht.\n\nIm Nordosten sah ich einige Wolken aus rotem Nebel am Wasser, die anscheinend neue Wucherungen nach sich zogen. Nehmt einen meiner Windteufel und besorgt mir eine Probe aus diesen Wolken. Es kann sein, dass Ihr in Bodennähe bleiben müsst, um sie zu sehen.", sourceObjective = "Bringt Lorvarius' Windteufel zu den Wolken aus rotem Nebel in der Rubinspanne und bringt eine Probe davon mit.", completion = "Ihr habt zugelassen, dass der Nebel Eure Haut berührt? Ich hoffe, es gab keine unangenehmen Wirkungen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26582] = { id = 26582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unnatürliche Ursachen", description = "Der Ursprung ist definitiv magisch. Nicht einmal druidisch. Ich habe einen der Steintroggs im Norden unter Verdacht.\n\nGeht zu Gorsik und weist ihn auf sie hin. Hoffentlich gewinnt Ihr dadurch seine Unterstützung.", sourceObjective = "Sprecht mit Gorsik dem Tosenden in der Rubinspanne.", completion = "Die Steintroggs? Und ich soll Euren Worten Glauben schenken?\n\nIch mag Verlok ohnehin nicht. Ein Verdacht reicht vollkommen aus, um sie zu Staub zu zermahlen. Wir werden sehen, ob Ihr die Wahrheit sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26583] = { id = 26583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn der Fungumanten", description = "Ihr Anführer versteckt sich in seinem Loch dort vorn. Er hat diese Plage über die Rubinspanne gebracht.\n\nEr muss sterben.\n\nEine Eurer Begleiterinnen vom Irdenen Ring befindet sich bereits im Inneren. Ihr solltet mit ihr sprechen.", sourceObjective = "Sprecht mit Erdheilerin Norsala, tötet dann Fungumant Glop.", progress = "Ich passe nicht hinein. Unsere Elementare sind der Aufgabe nicht gewachsen.\n\nIhr müsst sie erledigen.", completion = "Gut gemacht, {race}.\n\nGorsik wird von Eurer Tat erfahren. Therazane wird von Eurer Tat erfahren.\n\nIhr seid ganz schön teuflisch für Eure Größe... und Eure Weichheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26584] = { id = 26584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschüttelt und gerührt", description = "Ich habe meine Brüder ausgesandt. Sie werden Verlok von oben angreifen. Die Verlok werden sich wie immer auf ihren Felsvorsprüngen versammeln, um unserem Zorn zu entgehen. Sobald sie das tun, werden wir dafür sorgen, dass die Erde bebt, bis sie zu Boden gehen.\n\nDann könnt Ihr Euch nützlich machen. Sorgt dafür, dass sie sich nicht mehr erheben, wenn sie zwischen meinen Brüdern am Boden liegen.", sourceObjective = "Tötet 8 Säulenbrecher von Verlok im unteren Teil der Wacht Verlok.", completion = "Gut gemacht, Fleischling. Ihr habt meine Brüder gut ergänzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26585] = { id = 26585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstörung der Verderbnis", description = "Wenn dieses abscheuliche Wachstum wirklich von den Einwohnern Verloks stammt, dann bewahren sie ihre Vorräte sicher im Dorf im Norden auf. Bringt sie mir, damit ich Eure Behauptung überprüfen kann.", sourceObjective = "Besorgt 8 Taschen des Wunderwachstumsmittels von Verlok.", progress = "Ich warte auf Euren Beweis, {race}…", completion = "Also sind Eure Worte wahr. Ihr habt meinen Dank, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26586] = { id = 26586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach der Kompanie Bravo", description = "Wenn Ihr und Keeshan Seenhain verteidigen wollt, müssen wir sein altes Bataillon finden. Das Letzte, was ich hörte, war, dass Messner, Jorgensen, Krakauer und Danforth von den Schwarzfelsorcs gefangen genommen wurden. Ich weiß zwar nicht, wo sie sein könnten oder ob sie noch leben, aber ich wäre ein verdammter Narr, wenn ich Euch nicht bitten würde, sie zu suchen.\n\nSucht in Althers Mühle östlich von hier nach Hinweisen.", sourceObjective = "Sucht in Althers Mühle nach einem Mitglied der Kompanie Bravo.", completion = "Keeshan? Ihr meint, JOHNNY LEBT? Ihr könnt Euren süßen Allerwertesten wetten, dass ich helfen werde, aber erst müsst Ihr mich aus diesem verdammten Käfig befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[26587] = { id = 26587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel zum Erfolg", description = "Der Schlüssel zu diesem Käfig befindet sich in einem Beutel nördlich von diesem Ort im Höhlenbau der Worgen. Das Problem ist, dass dieser Beutel sicher auf einem Baumstumpf inmitten blutdürstiger, mordgieriger Worgs liegt. Holt den Schlüssel, ohne die schlafenden Worgs aufzuwecken.\n\nIhr habt nur einen Versuch. Reist zum Höhlenbau der Worgs und findet einen Weg zur Mitte. Seid vorsichtig und nehmt Euch vor dem Worghauptmann des Schwarzfels in Acht. Holt den Schlüssel und kehrt zu mir zurück.\n\nSolltet Ihr einen Begleiter haben, wäre es besser, ihn zurückzulassen!", sourceObjective = "Besorgt Messners Käfigschlüssel.", progress = "Habt Ihr den Käfigschlüssel?", completion = "RACHE!", sourceObjectiveStatus = "unverified-source-field" }
quests[26588] = { id = 26588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wütender Fang", description = "Steht Euch der Sinn nach einer Herausforderung, {name}? Gut, das hatte ich gehofft. Der Südstrom führt westlich an Orgrimmar vorbei. Eure Herausforderung schwimmt in seinen wilden Wassern.\n\nWir suchen nach einem riesigen, wütenden Hecht. Dieser geschätzte Fisch war früher zahlreich in dieser Gegend vertreten, doch seit der Flut sieht man die großen nur noch selten. Begebt Euch zum Fluss, dann werden wir sehen, wie gut es wirklich um Eure Angelkünste bestellt ist.", sourceObjective = "Fangt einen riesigen wütenden Hecht im Südstrom. Ihr findet den Südstrom vor dem westlichen Tor von Orgrimmar. Kehrt danach zu Razgar ins Tal der Ehre zurück.", progress = "Konntet Ihr einen riesigen Hecht fangen?", completion = "{name}, Ihr habt einen! Einen so starken, schönen Fisch bekommt man nur selten zu Gesicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26589] = { id = 26589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wildnis von Feralas", description = "Ihr habt heldenhaften Mut, uns dabei helfen zu wollen, diese Länder zu beschützen. Wenn Ihr der Wildnis noch mehr helfen wollt, so werden sich noch andere finden, die Eure Hilfe gebrauchen können.\n\nDer üppige Wald von Feralas liegt südlich von hier. Sucht in den Schatten der mächtigen Zwillingskolosse Konu Runentotem auf. Er hat Hinweise auf eine beunruhigende Krankheit gefunden.\n\nFolgt der Straße nach Westen, vorbei an den Zwillingskolossen, bis Ihr Camp Ataya erreicht. Geht in Frieden, {name}, und mit der Erdenmutter.", sourceObjective = "Reist nach Feralas und sprecht mit Konu Runentotem in Camp Ataya.", completion = "Friede sei mit Euch. Ich wünschte, wir würden uns unter freudigeren Umständen treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26590] = { id = 26590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das heilige Wasser der Klarheit", description = "Hey, hört mich an. Ihr seht nicht wie ein gewöhnlicher Tourist aus, und ich stecke ein wenig in der Klemme. Mein Cousin im Norden hat mir dieses seltsame Artefakt geschickt und ich brauche Eure Hilfe, um es zu... äh... identifizieren.\n\nAls erstes müsst Ihr mir das heilige Wasser der Klarheit besorgen. Es heißt, dass jeder, der aus dieser Quelle trinkt, eine Vision der Klarheit erhält. \n\nKlingt recht vielversprechend, oder?\n\nSchöpft es aus dem Nek'maiquellbrunnen am Gipfel des Nagalagers. Viel Glück!", sourceObjective = "Schöpft das heilige Wasser der Klarheit aus dem Nek'maniquellbrunnen Wellspring am Kap des Schlingendorntals.", progress = "<Flem richtet seine Ohren auf, als Ihr Euch nähert.>\n\nDas heilige Wasser der Klarheit? Ist es hier!?", completion = "<Der {race} stürzt das Wasser in einem Schluck hinunter.>\n\nAhh... wisst Ihr, wie schwer es ist, im Schlingendorntal frisches Wasser zu bekommen? Kein Wunder, dass die Naga ihren Schrein so streng bewachen!\n\nOh, stimmt ja... das Artefakt. Klarheit...\n\nMir ist alles klar!", sourceObjectiveStatus = "unverified-source-field" }
quests[26591] = { id = 26591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung an vorderster Front", description = "Ihr scheint schnell zu Fuß zu sein, {race}. Ich brauche jemanden, der sich in das Chaos der Front stürzt und unsere Verletzten versorgt.\n\nNehmt meine Rettungsausrüstung. Sie ist ganz einfach zu verwenden.\n\nHeilt sie, bevor die Steintroggs sie endgültig erwischen.", sourceObjective = "Versorgt 10 verletzte Irdene.", completion = "Falls Ihr Eurer Karriere als {class} je überdrüssig seid, sucht mich auf. Ihr scheint mit diesen fleischigen Händen ziemlich geschickt zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26592] = { id = 26592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diffraktorisches Chromaskop", description = "Ich benötige Analysewerkzeuge, um dieses Artefakt zu identifizieren. Ein diffractorisches Chromaskop sollte ausreichen, glaube ich.\n\nIch habe das Mithrilgehäuse bereits, was seltsamerweise am schwierigsten zu finden ist. Wir brauchen nur noch zwei andere Teile, einen Rubin und einen Saphir.\n\nIn der Nähe lagern Piraten, unmittelbar im Süden von hier und etwas weiter entfernt im Osten. Piraten lieben Schätze... seht doch mal nach, ob Ihr ein paar Edelsteine für mich findet.", sourceObjective = "Besorgt einen Blutsegelrubin und einen Blutsegelsaphir.", progress = "<Flems Augen funkeln.>\n\nSind das etwa Edelsteine?", completion = "<Flem wiegt die Edelsteine in seinen Händen und nickt zufrieden.>\n\nJa, die reichen. Ich beginne die Analyse...\n\n<Der Goblin schlägt die Edelsteine eine Weile gegeneinander, dann sieht er zu Euch empor.>\n\nOh, Ihr seid immer noch hier? Ihr haltet mich doch nicht für einen Betrüger oder so?", sourceObjectiveStatus = "unverified-source-field" }
quests[26593] = { id = 26593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zitterhand Angst einjagen", description = "Wenn ich etwas nicht leiden kann, dann sind das Leute, die ihre Spielschulden nicht bezahlen! Und es gibt 'ne Menge Leute, die mir was schulden. Ob Ihr mir wohl beim Eintreiben helfen könnt?\n\nDa ist zuerst mal \"Zitterhand\" Phillipe unten bei den Docks. Er schuldet mir eine Menge nach dem Spiel letzte Woche und ich will mein Geld jetzt! Aber um da dranzukommen, müssen wir ihm gehörig Angst einjagen.\n\nVerlasst die Stadt und jagt alte Nebeltalgorillas. Sucht Euch ein paar nette Innereien heraus und bringt sie zu Zitterhand. Sagt ihm ja nicht, dass sie von einem Tier stammen, er soll ruhig das Schlimmste annehmen.", sourceObjective = "Erhaltet 5 Nebeltalinnereien von alten Nebeltalgorillas.", progress = "He! Den Blick, den Ihr mir da zuwerft, mag ich gar nicht, Sire.", completion = "Igitt! Wo habt Ihr das denn her? Nein, sagt es mir lieber nicht. Ich will es gar nicht wissen!\n\nWer hat Euch geschickt? Seewolf?", sourceObjectiveStatus = "unverified-source-field" }
